  ["_CeladonHotelBeautyText"] = "Ich mache hier\nmit meinem Bruder\vund meinem Freund\vUrlaub.\fPRISMANIA CITY\nist wunderschön!",
  ["_CeladonHotelGrannyText"] = "In diesem Hotel\nsind keine\vPOKéMON erlaubt!\fTut mir leid.",
  ["_CeladonHotelSuperNerdText"] = "Warum nur mußte\nsie ihren Bruder\vmitnehmen?",
  ["_CeladonMansion1FClefairyText"] = "PIEPI: Piepi!",
  ["_CeladonMansion1FManagersSuiteSignText"] = "PRISMANIA-VILLA\nManager Suite",
  ["_CeladonMansion1FMeowthText"] = "MAUZI: Miauz!",
  ["_CeladonMansion1FNidoranFText"] = "NIDORAN: Nidoran!",
  ["_CeladonMansion1Text10"] = "Dein PIKACHU\nsieht zahm aus.",
  ["_CeladonMansion1Text11"] = "Dein PIKACHU\nscheint Dich zu\vmögen.",
  ["_CeladonMansion1Text12"] = "Du und Dein\nPIKACHU - Ihr\vseid ein\vfantastisches\vTeam!\fIch werde ganz\nneidisch!",
  ["_CeladonMansion1Text2"] = "Meine treuen\nPOKéMON leisten\vmir Gesellschaft.\fMAUZI bringt\nsogar Geld mit\vnach Hause!",
  ["_CeladonMansion1Text6"] = "Oh, Dein PIKACHU\nist ein wahres\vPrachtexemplar!",
  ["_CeladonMansion1Text7"] = "Es sieht aus, als\nwäre es noch\vnicht gezähmt.",
  ["_CeladonMansion1Text8"] = "Du mußt Dich\nviel mehr mit\vDeinem PIKACHU\vbeschäftigen!",
  ["_CeladonMansion1Text9"] = "Du mußt stolz\nsein, so ein\vsüßes POKéMON\vzu besitzen!",
  ["_CeladonMansion2FMeetingRoomSignText"] = "GAME FREAK\nKonferenzraum",
  ["_CeladonMansion3FDevRoomSignText"] = "GAME FREAK\nEntwicklungs-\vAbteilung",
  ["_CeladonMansion3FGameDesignerCompletedDexText"] = "Wow! Fantastisch!\nDein POKéDEX\vist vollständig!\vHerzlichen\vGlückwunsch!",
  ["_CeladonMansion3FGameDesignerCompletedDexText2"] = "Geh und zeige dem\nEntwicklungs-Team\vDein DIPLOM.",
  ["_CeladonMansion3FGameDesignerText"] = "Gefällt Dir das\nSpiel?\fIch habe das\nSpiel gestaltet!\fAuch wenn es sehr\nmühsam ist, den\vPOKéDEX zu\verstellen: Gib\vnicht auf!\fZeige ihn mir,\nwenn er komplett\vist!",
  ["_CeladonMansion3FGameProgramPCText"] = "Der Programmcode!\nDavon sollte man\vbesser die Finger\vlassen!",
  ["_CeladonMansion3FGameScriptPCText"] = "Das Drehbuch!\nIch schaue mir\vdas Ende besser\vnicht an!",
  ["_CeladonMansion3FGraphicArtistText"] = "Ich bin der\nGrafiker!\vIch habe dies\valles gezeichnet!",
  ["_CeladonMansion3FGraphicArtistText2"] = "Ich bin der\nGrafiker!\fWow, Du hast den\nPOKéDEX\vvervollständigt!\vSoll ich Dir zum\vBeweis ein DIPLOM\vausdrucken?",
  ["_CeladonMansion3FGraphicArtistText3"] = "Sag mir Bescheid,\nwenn ich Dir ein\vDIPLOM ausdrucken\vsoll.",
  ["_CeladonMansion3FGraphicArtistText4"] = "Fertig!",
  ["_CeladonMansion3FGraphicArtistText5"] = "OK, wir drucken\nes nicht.",
  ["_CeladonMansion3FPlayingGamePCText"] = "Dort spielt\njemand, anstatt\vzu arbeiten!",
  ["_CeladonMansion3FProgrammerText"] = "Ich? Ich bin der\nProgrammierer!",
  ["_CeladonMansion3FProgrammerText2"] = "Ich? Ich bin der\nProgrammierer!\fDas ist aber eine\nÜberraschung! Ich\vhabe es nicht für\vmöglich gehalten,\vdaß jemand den\vPOKéDEX\vvervollständigt!",
  ["_CeladonMansion3FWriterText"] = "Die Geschichte\nstammt von mir!\vIst ERIKA nicht\vsüß?\fAber MISTY mag\nich auch gerne!\fUnd nicht zu\nvergessen,\vSABRINA!",
  ["_CeladonMansion3FWriterText2"] = "Die Story des\nSpiels stammt von\vmir!\fIch finde es\ntoll, daß Du alle\vPOKéMON gefangen\vhast! Klasse!",
  ["_CeladonMansionRoofHouseHikerText"] = "Ich kenne jedes\nDetail der\vPOKéMON-WELT\vin Deinem\vGAME BOY!\fTriff Dich mit\nFreunden und\vtausche POKéMON!",
  ["_CeladonMansionRoofHouseSignText"] = "ICH WEISS ALLES!",
  ["_CeladonMart1FCurrentFloorSignText"] = "EG: KUNDEN-\nINFORMATION",
  ["_CeladonMart1FDirectorySignText"] = "EG: KUNDEN-\nINFORMATION\fS1: UTENSILIEN\nFÜR TRAINER\fS2: VIDEOSPIELE\fS3: GESCHENK-\nARTIKEL\fS4: DROGERIE\fDACHGARTEN:\nAUTOMATEN",
  ["_CeladonMart1FReceptionistText"] = "Willkommen im\nEINKAUFSZENTRUM\vvon PRISMANIA\vCITY!\fAuf der Tafel\nrechts findest Du\veine Übersicht.",
  ["_CeladonMart2FCurrentFloorSignText"] = "Nützliche Items\nfür Trainer!\fS1: ZUBEHÖR FÜR\nTRAINER",
  ["_CeladonMart2FGirlText"] = "Vor längeren\nAusflügen\vsolltest Du\vBELEBER kaufen.",
  ["_CeladonMart2FMiddleAgedManText"] = "SUPERSCHUTZ hält\nPOKéMON auf\vDistanz...\fEs ist besser als\nnormaler SCHUTZ!",
  ["_CeladonMart3FClerkReceivedTM18Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_CeladonMart3FClerkTM18ExplanationText"] = "TM18 ist KONTER!\nIch brauche die\vTM hier sowieso\vnicht!",
  ["_CeladonMart3FClerkTM18NoRoomText"] = "Dein Rucksack\nist zu voll!",
  ["_CeladonMart3FClerkTM18PreReceiveText"] = "Hallo! Ich habe\nkürzlich POKéMON\vdurchgespielt!\fDu bist noch\nnicht soweit?\vVielleicht hilft\vDir das hier!",
  ["_CeladonMart3FCurrentFloorSignText"] = "S2: VIDEOSPIELE-\nSHOP",
  ["_CeladonMart3FFightingGameText"] = "Ein Kampfsport-\nSpiel! Aufregend!",
  ["_CeladonMart3FGameBoyKid1Text"] = "Jedes gefangene\nPOKéMON erhält\veine ID-Nr. und\vwird mit dem\vNamen des\vORIGINALTRAINERS,\vOT, registriert. \vDer OT ist der\vTrainer, der das\vPOKéMON gefangen\vhat!",
  ["_CeladonMart3FGameBoyKid2Text"] = "Cool!\fMein Kumpel\ntauscht sein\vKANGAMA gegen\vmein GEOROK!",
  ["_CeladonMart3FGameBoyKid3Text"] = "Komm, GEOROK!\fIch bin\nGEOROK-Sammler!\fNanu?\fGEOROK hat sich\nzu einem anderen\vPOKéMON\ventwickelt!",
  ["_CeladonMart3FLittleBoyText"] = "Anhand ihrer\nID-Nr. kannst Du\vPOKéMON, die Du\vbei einem Tausch\verhalten hast,\videntifizieren!",
  ["_CeladonMart3FPokemonPosterText"] = "Die rote und die\nblaue POKéMON-\vEdition! Cool!",
  ["_CeladonMart3FPuzzleGameText"] = "Ein Puzzle-Spiel!\nEs ist bestimmt\vfesselnd!",
  ["_CeladonMart3FRPGText"] = "Ein Rollenspiel!\nIch habe keine\vZeit! Schade!",
  ["_CeladonMart3FSNESText"] = "Das ist ein\nSUPER NINTENDO!",
  ["_CeladonMart3FSportsGameText"] = "Ein Rennspiel!\nDas würde meinem\vVater gefallen!",
  ["_CeladonMart4FCurrentFloorSignText"] = "Bereite anderen\nmit Geschenken\veine Freude!\fS3: GESCHENK-\nARTIKEL\fSONDERANGEBOTE!\nSonderpreise für\vELEMENT-STEINE!",
  ["_CeladonMart4FSuperNerdText"] = "Ich kaufe der\nNACHAHMERIN ein\vGeschenk!\fIch kaufe Ihr\ndiese trendige\vPOKéPUPPE!",
  ["_CeladonMart4FYoungsterText"] = "Ich habe einen\nTip bekommen!\fDu kannst vor\nwilden POKéMON\vfliehen, wenn Du\vsie mit einer\vPOKéPUPPE\vablenkst!",
  ["_CeladonMart5FCurrentFloorSignText"] = "S4: DROGERIE",
  ["_CeladonMart5FGentlemanText"] = "Nur hier kannst\nDu leistungs-\vfördernde Mittel\vfür Deine POKéMON\vkaufen!\fKALZIUM steigert\ndie Stärke von\vSPEZIAL-ATTACKEN!\fCARBON erhöht die\nINITIATIVE.",
  ["_CeladonMart5FSailorText"] = "Ich bin wegen\nder leistungs-\vfördernden Mittel\vfür POKéMON hier.\fPROTEIN steigert\ndie ANGRIFFS-\vSTÄRKE.\fEISEN stärkt die\nABWEHR!",
  ["_CeladonMartRoofCurrentFloorSignText"] = "DACHGARTEN:\nAUTOMATEN",
  ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "Ich bin durstig!\nIch möchte etwas\vtrinken!\fGibst Du dem\nMädchen ein\vGetränk?",
  ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "Welches Getränk\nmöchtest Du ihr\vgeben?",
  ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "Das ist nett\ngemeint, aber ich\vhabe keinen\vDurst!",
  ["_CeladonMartRoofLittleGirlImThirstyText"] = "Ich bin durstig!\nEin Königreich\vfür ein Getränk!",
  ["_CeladonMartRoofLittleGirlNoRoomText"] = "Du hast keinen\nPlatz dafür!",
  ["_CeladonMartRoofLittleGirlReceivedTM13Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM48Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM49Text"] = "{PLAYER} erhält\nTM49!",
  ["_CeladonMartRoofLittleGirlTM13ExplanationText"] = "\f{RAM:wStringBuffer} ist\nEISSTRAHL!\fDamit kann man\nmanche Gegner\veinfrieren!",
  ["_CeladonMartRoofLittleGirlTM48ExplanationText"] = "\f{RAM:wStringBuffer} ist\nSTEINHAGEL!\fDamit kann man\nmanchen Gegnern\vAngst einjagen!",
  ["_CeladonMartRoofLittleGirlTM49ExplanationText"] = "\fTM49 ist\nTRIPLETTE!",
  ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "Ja!\fTAFELWASSER!\fVielen Dank!\fNimm bitte dieses\nGeschenk!",
  ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "Cool!\fLIMONADE!\fVielen Dank!\fNimm bitte dieses\nGeschenk!",
  ["_CeladonMartRoofLittleGirlYaySodaPopText"] = "Cool!\fSPRUDEL!\fVielen Dank!\fNimm bitte dieses\nGeschenk!",
  ["_CeladonMartRoofSuperNerdText"] = "Ob Du es glaubst\noder nicht: Meine\vSchwester ist\veine Trainerin!\fAber sie ist so\nkindisch! Ich\vwerde noch ganz\vverrückt!",
  ["_CeladonPokecenterBeautyText"] = "Ich bin von\nFUCHSANIA CITY\vaus auf dem\vRADWEG\vhinaufgefahren!",
  ["_CeladonPokecenterGentlemanText"] = "Die POKéFLÖTE\nweckt POKéMON mit\veinem Geräusch,\vdas nur POKéMON\vhören können!",
  ["_CeruleanBadgeHouseBoulderBadgeText"] = "Die ANGRIFFE\nDeiner POKéMON\vwerden ein wenig\vverstärkt.\fAußerdem kannst\nDu jederzeit\vBLITZ einsetzen.",
  ["_CeruleanBadgeHouseCascadeBadgeText"] = "POKéMON bis\nLevel 30 folgen\vDeinen Befehlen!\fPOKéMON höherer\nLevel gehorchen\vDir jedoch nicht!\fFerner kannst Du\nden ZERSCHNEIDER\vaußerhalb von\vKämpfen nutzen!",
  ["_CeruleanBadgeHouseEarthBadgeText"] = "Jegliches POKéMON\ngehorcht Dir!",
  ["_CeruleanBadgeHouseMarshBadgeText"] = "POKéMON bis\nLevel 70 folgen\vDeinen Befehlen.\fPOKéMON höherer\nLevel gehorchen\vDir jedoch nicht!",
  ["_CeruleanBadgeHouseMiddleAgedManText"] = "Nur sehr begabte\nTrainer tragen\vPOKéMON-ORDEN.\fWie ich sehe,\nhast Du Dir\vbereits ORDEN\vverdient.\fDie ORDEN sind\ngeheimnisumwoben!",
  ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "Besuche mich,\nwann immer Du\vmöchtest.",
  ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "Also dann...\fÜber welchen der\nacht ORDEN soll\vich Dir etwas\verzählen?",
  ["_CeruleanBadgeHouseRainbowBadgeText"] = "POKéMON bis\nLevel 50 folgen\vDeinen Befehlen.\fPOKéMON höherer\nLevel gehorchen\vDir jedoch nicht!\fZusätzlich kannst\nDu außerhalb von\vKämpfen STÄRKE\veinsetzen.",
  ["_CeruleanBadgeHouseSoulBadgeText"] = "Die VERTEIDIGUNG\nDeiner POKéMON\vwird verbessert.\fFerner kannst Du\naußerhalb von\vKämpfen SURFER\vverwenden.",
  ["_CeruleanBadgeHouseThunderBadgeText"] = "Die INITIATIVE\nDeiner POKéMON\vnimmt zu.\fDesweiteren ist\nes Dir möglich,\vFLIEGEN außerhalb\vvon Kämpfen\veinzusetzen.",
  ["_CeruleanBadgeHouseVolcanoBadgeText"] = "Die SPEZIAL-\nFÄHIGKEITEN\vDeiner POKéMON\vwerden erhöht.",
  ["_CeruleanCityBikeShopSign"] = "FAHRRADLADEN\nFahre leicht und\vschnell mit dem\vRad durch Höhlen\vund Gras!",
  ["_CeruleanCityCooltrainerF1ElectrodePunchText"] = "Oh nein!\nWieder nicht...",
  ["_CeruleanCityCooltrainerF1ElectrodeUseSonicboomText"] = "ULTRASCHALL, los!\nJetzt mach schon!",
  ["_CeruleanCityCooltrainerF1ElectrodeWithdrawText"] = "Nein, nicht!!!\fEs ist schwer,\nein POKéMON\vzu kontrollieren!\fOb Dein POKéMON\ngehorcht,  hängt\vvon Deinen\vFähigkeiten als\vTrainer ab!",
  ["_CeruleanCityCooltrainerF2Text"] = "Ich hätte gern\nein rotes\vFAHRRAD!\fAber ich würde\nnicht damit\vfahren, damit es\vnicht schmutzig\vwird!",
  ["_CeruleanCityCooltrainerMText"] = "Du bist auch ein\nTrainer? Zu\vsammeln und zu\vkämpfen ist nicht\vimmer so leicht!",
  ["_CeruleanCityElectrodeIgnoredOrdersText"] = "LEKTROBALL \nignoriert die\vBefehle...",
  ["_CeruleanCityElectrodeIsLoafingAroundText"] = "LEKTROBALL\nbummelt herum...",
  ["_CeruleanCityElectrodeTookASnoozeText"] = "LEKTROBALL macht\nein Nickerchen...",
  ["_CeruleanCityElectrodeTurnedAwayText"] = "LEKTROBALL\nwendet sich ab...",
  ["_CeruleanCityGuardText"] = "Die Leute hier\nwurden beraubt.\fWir sind sicher,\ndaß TEAM ROCKET\vdahinter steckt!\fSogar die POLIZEI\nist gegen TEAM\vROCKET machtlos!",
  ["_CeruleanCityGymSign"] = "AZURIA CITY\nPKMN-ARENA\vARENALEITERIN: \vMISTY\fDie zauberhafte\nArenaleiterin!",
  ["_CeruleanCityRivalDefeatedText"] = "Hey, \nschon gut! Du\vhast gewonnen!",
  ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}: Soll\nich Dir was\vverraten?\fIch war bei BILL\nund habe mir\vseine seltenen\vPOKéMON\vzeigen lassen!\fDas hat mir\neinige Einträge\vin meinem POKéDEX\vgebracht!\fBILL ist weltweit\nals POKéMANIAC\vbekannt!\fEr hat das \nPOKéMON- \vLagersystem für\vden PC\ventwickelt!\fDu kannst Dich\nbei ihm dafür\vbedanken!\fNaja, ich hau ab!\nMach's mal gut!",
  ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}: Hi,\n{PLAYER}!\fDu bist also\nimmer noch \vunterwegs!\fMir geht es\nbestens! Ich habe\vjede Menge neue,\vstarke POKéMON\vgefangen!\fZeig mal, was Du\ngefangen hast,\v{PLAYER}!",
  ["_CeruleanCityRivalVictoryText"] = "Ha!\nMeiner Genialität\vkannst Du nichts\ventgegensetzen!",
  ["_CeruleanCityRocketIBetterGetMovingText"] = "\fIch gehe wohl\nbesser! Tschüß!",
  ["_CeruleanCityRocketIGiveUpText"] = "OK!\nIch gebe auf!\vIch verschwinde!",
  ["_CeruleanCityRocketIllReturnTheTMText"] = "OK! Ich gebe die\ngestohlene TM\vzurück!",
  ["_CeruleanCityRocketReceivedTM28Text"] = "{PLAYER} erhält\nTM28!",
  ["_CeruleanCityRocketTM28NoRoomText"] = "Schaff Platz für\ndieses coole\vItem!\fIch kann erst\ngehen, wenn ich\ves Dir gegeben\vhabe!",
  ["_CeruleanCityRocketText"] = "He! Bleib\ndraußen! Du hast\vhier nichts zu\vsuchen! Was ich\vhier tue?\fIch bin nur ein\nunschuldiger\vPassant! Was?\vGlaubst Du mir\vetwa nicht?",
  ["_CeruleanCitySignText"] = "AZURIA CITY\nEine mysteriöse\vblaue Aura\vumgibt die Stadt!",
  ["_CeruleanCitySuperNerd1Text"] = "Der Busch vor dem\nLaden steht im\vWeg!\fVielleicht gibt es\neinen anderen\vWeg!?",
  ["_CeruleanCitySuperNerd2Text"] = "Du erstellst eine\nEnzyklopädie der\vPOKéMON? Das\vklingt lustig!",
  ["_CeruleanCitySuperNerd3Text"] = "Die AZURIA\nHÖHLE! Dort leben\vextrem starke\vPOKéMON!\fNur PKMN-LIGA-\nChampions ist der\vZutritt erlaubt!",
  ["_CeruleanCityTrainerTipsText"] = "TIPS FÜR TRAINER\fDrückt man den\nB-Knopf während\vder Entwicklung\veines POKéMON, so\vwird der Prozess\vabgebrochen!",
  ["_CeruleanGymAfterBattleText1"] = "Du mußt Dich\nanderen Trainern\vstellen, um \vherauszufinden,\vwie gut Du bist.",
  ["_CeruleanGymAfterBattleText2"] = "MISTY verbessert\nstets ihr Können!\fJemand wie Du hat\nkeine Chance, sie\vzu besiegen!",
  ["_CeruleanGymBattleText1"] = "Zuerst fordere\nich Dich heraus!\fMISTY muß warten!",
  ["_CeruleanGymBattleText2"] = "Platsch!\fIch bin Dein\nerster Gegner!\vEs geht los!",
  ["_CeruleanGymEndBattleText1"] = "Ich\nbin überwältigt!",
  ["_CeruleanGymEndBattleText2"] = "\nDas darf nicht\vwahr sein!",
  ["_CeruleanGymGymGuideBeatMistyText"] = "Du hast MISTY\nbesiegt! Habe ich\ves nicht gesagt?\fGlaub mir, wir\nbeide bilden ein\vsehr gutes Team!",
  ["_CeruleanGymGymGuideChampInMakingText"] = "Hey! Warte, Du\nChampion in spe!\fIch habe einen\nTip für Dich!\fMISTY, die\nARENALEITERIN,\vkämpft mit\vWASSER-POKéMON!\fDu kannst ihnen\ndas Wasser mit\vPFLANZEN-POKéMON\ventziehen!\fELEKTRO-POKéMON\ndürften sich auch\vals nützlich\verweisen!",
  ["_CeruleanGymMistyCascadeBadgeInfoText"] = "Der QUELLORDEN\nläßt alle POKéMON\vbis Level 30\vDeinen Befehlen\vgehorchen!\fSogar Außenseiter\ngehorchen Dir!\fDeine POKéMON\nkönnen den\vZERSCHNEIDER\vnun jederzeit \veinsetzen!\fDu kannst kleine\nBüsche zerhacken\vund so neue Wege\vfreilegen!\fZu guter Letzt\nschenke ich Dir\vnoch meine\vLieblings-TM!",
  ["_CeruleanGymMistyPreBattleText"] = "Hi, Du mußt hier\nneu sein!\fWelche POKéMON-\nTaktik setzt Du\vein? Wie gehst\vDu vor?\fMeine Devise ist\nder offensive\vEinsatz von\vWasser-POKéMON!\fDeine Gastgeberin\nist MISTY, die\vberühmte Schön-\vheit!\fBist Du bereit,\nSüßer?",
  ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "Wow! Du\nbist sehr gut!\fAlles klar!\fIch überlasse Dir\nden QUELLORDEN\vals Zeichen\vDeines Triumphes!",
  ["_CeruleanGymMistyReceivedTM11Text"] = "{PLAYER} erhält\nTM11!",
  ["_CeruleanGymMistyTM11ExplanationText"] = "TM11 ist der\nBLUBBSTRAHL!\fWASSER-POKéMON\nkönnen diese\vAttacke erlernen!",
  ["_CeruleanGymMistyTM11NoRoomText"] = "Du hast momentan\nkeinen Platz für\vmein Geschenk!",
  ["_CeruleanMartCooltrainerFText"] = "Besitzt Du\nSONDERBONBONS?\fGibt man einem\nPOKéMON ein\vSONDERBONBON,\vdann erreicht es\vden nächsten\vLevel!",
  ["_CeruleanMartCooltrainerMText"] = "Mit SCHUTZ kannst\nDu Dir Käfer und\vschwächere\vPOKéMON vom Leib\vhalten!\fAußerdem solltest\nDu das stärkste\vPOKéMON an die\vSpitze der Liste\vsetzen!",
  ["_CeruleanPokecenterGentlemanText"] = "Hat man Dir schon\nvon BILL erzählt?\fJeder nennt ihn\nden POKéMANIAC!\fAber ich glaube,\ndie Leute sind\vbloß neidisch auf\vBILL.\fWer würde denn\nnicht mit seinen\vPOKéMON prahlen?",
  ["_CeruleanPokecenterGuyText"] = "BILL besitzt\nviele POKéMON!\fEr hat einige\nsehr seltene in\vseiner Sammlung!",
  ["_CeruleanPokecenterSuperNerdText"] = "Dieser BILL!\fIch hörte, für\nseltene POKéMON\vwürde er alles\vtun!",
  ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "Dieses gemeine\nTEAM ROCKET!\fHör Dir an, was\nsie wieder\vverbrochen haben!\fSie haben den\nSCHAUFLER\vgestohlen, eine\vTM, mit der\vPOKéMON Löcher\vgraben können!\fDer SCHAUFLER war\nsündhaft teuer!",
  ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "Was weg ist,\nist weg!\fIch werde DIGDA\nbeibringen, ohne\vden SCHAUFLER\vzu graben!",
  ["_CeruleanTrashedHouseGirlText"] = "TEAM ROCKET\nbraucht den\vSCHAUFLER sicher\vfür irgendeine\vSchandtat!",
  ["_CeruleanTrashedHouseWallHoleText"] = "TEAM ROCKET\nhat Spuren\vhinterlassen!",
  ["_ChampionsRoomOakComeWithMeText"] = "EICH: {PLAYER}!\fDu hast\nbegriffen, daß\vDein Sieg nicht\valleine Dein\vVerdienst war!\fDie Beziehung\nzu Deinen POKéMON\vist vorbildlich!\f{PLAYER}!\nFolge mir!",
  ["_ChampionsRoomOakCongratulatesPlayerText"] = "EICH: Du hast\nalso gewonnen!\vGlückwunsch!\vDu bist der neue\vChampion der\vPKMN-LIGA!\fDu hast viel\ndazugelernt, seit\vDu Dich mit\v{RAM:wNameBuffer} auf\vden Weg gemacht\vhast!\f{PLAYER},\nDu bist schon\vviel erfahrener!",
  ["_ChampionsRoomOakDisappointedWithRivalText"] = "EICH: {RIVAL}!\nDu hast mich\vsehr enttäuscht!\fAls ich hörte, \nDu hättest die\vTOP VIER besiegt,\vkam ich hierher!\fDoch als ich\nankam, warst Du\vder Verlierer!\f{RIVAL}, weißt\nDu, warum Du\vverloren hast?\fDu hast Deinen\nPOKéMON nicht\vgenug Liebe\vund Vertrauen \ventgegengebracht!\fSo wirst Du\nniemals Sieger\vwerden!",
  ["_ChampionsRoomOakText"] = "EICH: {PLAYER}!",
  ["_ChampionsRoomRivalAfterBattleText"] = "Wieso?\vWieso habe\vich verloren?\fIch habe meine\nPOKéMON doch\vsehr sorgfältig\vaufgezogen...\fVerdammt!\nDu bist der neue\vCHAMPION der\vPKMN-LIGA!\fAber ich gönne\nDir das nicht!",
  ["_ChampionsRoomRivalIntroText"] = "{RIVAL}: Hallo!\fAuf diesen Moment\nwarte ich schon\vlange, {PLAYER}!\fIch brauche einen\nstarken Gegner, \vum mich in Form\vzu halten!\fWährend ich\nmeinen POKéDEX\vaktualisierte,\vhabe ich nur die\vstärksten POKéMON\vausgewählt!\fAber nicht nur\ndas: Ich habe\vTeams aufgebaut,\vdie ALLE POKéMON\vbesiegen können!\fUnd nun...\f...bin ich\nChampion der\vPKMN-LIGA!\f{PLAYER}!\fWeißt Du, was das\nbedeutet?\fIch werde es Dir\nsagen!\fIch bin der\nmächtigste\vTrainer der Welt!",
  ["_ChanseyDexEntry"] = "CHANEIRA ist sehr\nwarmherzig und\nfreundlich.\fEs kümmert sich\nliebevoll um\nverletzte POKéMON.",
  ["_ChargeMoveEffectText"] = "{USER}",
  ["_CharizardDexEntry"] = "Wenn dieses\nPOKéMON einen\nStrahl glühenden\fFeuers speit,\nleuchtet seine\nSchwanzspitze auf.",
  ["_CharmanderDexEntry"] = "An sehr stillen\nOrten kann man\ndie brennende\fSchwanzspitze\ndieses POKéMON\nlodern hören.",
  ["_CharmeleonDexEntry"] = "Verfällt dieses\nPOKéMON in\nAufregung, so\fspuckt es\ngleißend helle\nFlammen.",
  ["_ChooseABoxText"] = "Wähle eine\nPOKéMON-BOX!",
  ["_CinnabarGymBlainePostBattleAdviceText"] = "FEUERSTURM ist\ndie mächtigste\vFeuerattacke!\fAllerdings ist\nsie gegen WASSER-\vPOKéMON machtlos!",
  ["_CinnabarGymBlainePreBattleText"] = "Haha!\fIch bin PYRO, der\nARENALEITER der\vZINNOBERINSEL!\fMeine FEUER-\nPOKéMON lassen\vdie Siegesträume\vmeiner Gegner in\vFlammen aufgehen!\fDu solltest schon\nmal FEUERHEILER\vparat halten!",
  ["_CinnabarGymBlaineReceivedTM38Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "Mein Feuer\nist erloschen!\fDu hast Dir den\nVULKANORDEN\vredlich verdient",
  ["_CinnabarGymBlaineTM38ExplanationText"] = "\fTM38 ist\nFEUERSTURM!\fFEUER-POKéMON\nkönnen diese\vAttacke erlernen!\fGLUTEXO und\nPONITA sind dafür\vprädestiniert!",
  ["_CinnabarGymBlaineTM38NoRoomText"] = "Schaffe Platz für\nmein Geschenk!",
  ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "Haha!\fDer VULKANORDEN\nsteigert die\vSPEZIAL-\vFÄHIGKEITEN\vDeiner POKéMON!\fNimm zusätzlich\ndieses Geschenk!",
  ["_CinnabarGymGymGuideBeatBlaineText"] = "{PLAYER}! Du hast\nden Unruhestifter\vgebrandmarkt!",
  ["_CinnabarGymGymGuideChampInMakingText"] = "Hey! Warte, Du\nChampion in spe!\fDer hitzköpfige\nPYRO ist ein\vFEUER-POKéMON-\vSpezialist!\fDu solltest sein\nMütchen mit\vWasser kühlen!\fUnd besorge Dir\nFEUERHEILER!",
  ["_CinnabarGymQuizCorrectText"] = "Und die Antwort\nist... RICHTIG!\fGeh weiter!",
  ["_CinnabarGymQuizDummyIntroText"] = "Willkommen beim\nPOKéMON-Quiz!\fWeißt Du die\nrichtige Antwort,\vdann öffnet sich\vdie Tür!\fIst die Antwort\nfalsch, dann mußt\vDu kämpfen...\fJe mehr Antworten\nDu weißt, desto\vfitter sind Deine\vPOKéMON beim\vKampf gegen den\vARENALEITER!",
  ["_CinnabarGymQuizIncorrectText"] = "FALSCH!\nSo ein Pech!",
  ["_CinnabarGymQuizIntroText"] = "Willkommen beim\nPOKéMON-Quiz!\fWeißt Du die\nrichtige Antwort,\vdann öffnet sich\vdie Tür!\fIst die Antwort\nfalsch, dann mußt\vDu kämpfen...\fJe mehr Antworten\nDu weißt, desto\vfitter sind Deine\vPOKéMON beim\vKampf gegen den\vARENALEITER!\f",
  ["_CinnabarGymQuizShortIntroText"] = "POKéMON-Quiz!\nPrüfe Dein\vWissen!\f",
  ["_CinnabarGymSuperNerd1AfterBattleText"] = "Feuer, oder\npräziser, die\vVerbrennung...\fBla, bla, bla,\nbla...",
  ["_CinnabarGymSuperNerd1BattleText"] = "Was glaubst Du,\nwie heiß der\vFeueratem eines\vPOKéMON werden\vkann?",
  ["_CinnabarGymSuperNerd1EndBattleText"] = "Autsch!\nHeiß, sehr heiß!",
  ["_CinnabarGymSuperNerd2AfterBattleText"] = "Ich kann nicht\naufhören, anderen\vLeuten POKéMON\vzu stehlen!",
  ["_CinnabarGymSuperNerd2BattleText"] = "Ich war ein Dieb!\nDoch nun bin ich\vein ehrenhafter\vTrainer!",
  ["_CinnabarGymSuperNerd2EndBattleText"] = "Ich\nergebe mich!",
  ["_CinnabarGymSuperNerd3AfterBattleText"] = "Du kannst meine\nArbeitsweise\vnicht verstehen!",
  ["_CinnabarGymSuperNerd3BattleText"] = "Du hast keine\nChance! Ich bin\vPOKéMON-Profi!",
  ["_CinnabarGymSuperNerd3EndBattleText"] = "Nein!\nDas war\vunprofessionell!",
  ["_CinnabarGymSuperNerd4AfterBattleText"] = "Ach, könnte ich\ndoch nur Deine\vPOKéMON stehlen!",
  ["_CinnabarGymSuperNerd4BattleText"] = "Ich setze mit\nVorliebe FEUER-\vPOKéMON ein!",
  ["_CinnabarGymSuperNerd4EndBattleText"] = "Du bist\nbrandgefährlich!",
  ["_CinnabarGymSuperNerd5AfterBattleText"] = "PYRO hatte sich\nals Kind in den\vBergen verlaufen,\vals über ihm ein\vFEUERVOGEL\verschien!\fDer Schein dieses\nPOKéMON wies PYRO\vden Rückweg!",
  ["_CinnabarGymSuperNerd5BattleText"] = "Ich weiß, warum\nPYRO ein Trainer\vgeworden ist!",
  ["_CinnabarGymSuperNerd5EndBattleText"] = "Autsch!",
  ["_CinnabarGymSuperNerd6AfterBattleText"] = "PONITA und\nVULNONA sind die\vLieblings-POKéMON\valler Pyromanen!",
  ["_CinnabarGymSuperNerd6BattleText"] = "Ich war in vielen\nPKMN-ARENEN, doch\vdiese mag ich am\vliebsten!",
  ["_CinnabarGymSuperNerd6EndBattleText"] = "Autsch!\nDu bist zu stark!",
  ["_CinnabarGymSuperNerd7AfterBattleText"] = "Wasser löscht\nFeuer, doch Feuer\vschmilzt Eis!",
  ["_CinnabarGymSuperNerd7BattleText"] = "Gegen Wasser\nkann Feuer nichts\vausrichten!",
  ["_CinnabarGymSuperNerd7EndBattleText"] = "Oh! Ich\nhabe verloren!",
  ["_CinnabarGymText_1"] = "Man nennt diese\nPKMN-ARENA auch\vdie QUIZ-ARENA.\fWenn Du zu PYRO\nmöchtest, mußt Du\van einem Quiz\vteilnehmen.\fWenn Du gewinnst\nmußt Du nicht\vgegen uns\vkämpfen!",
  ["_CinnabarGymText_2"] = "Glaubst Du,\nDu wirst es\vschaffen?",
  ["_CinnabarGymText_3"] = "Diese Frage ist\nschwer!",
  ["_CinnabarGymText_4"] = "Auch POKéMON\nlieben dieses\vQUIZ!",
  ["_CinnabarGymText_5"] = "Die QUIZ-ARENA\ngefällt mir gut.",
  ["_CinnabarGymText_6"] = "Dies ist die\nletzte Frage!",
  ["_CinnabarGymText_7"] = "Weißt Du etwa die\nAntwort nicht?",
  ["_CinnabarIslandDoorIsLockedText"] = "Die Tür ist\nverschlossen...",
  ["_CinnabarIslandGamblerText"] = "Forscher\nexperimentieren\vin dem\vausgebrannten\vGebäude.",
  ["_CinnabarIslandGirlText"] = "PYRO, der\nARENALEITER der\vZINNOBERINSEL,\vist ein seltsamer\vMann. Er lebt\vhier seit Jahren.",
  ["_CinnabarIslandGymSignText"] = "ZINNOBERINSEL\nPKMN-ARENA\vARENALEITER: PYRO\fDer hitzköpfige\nQuiz-Master!",
  ["_CinnabarIslandPokemonLabSignText"] = "POKéMON LABOR",
  ["_CinnabarIslandSignText"] = "ZINNOBERINSEL\nDie Stadt\vbrennender\vLeidenschaft!",
  ["_CinnabarLabFishingGuruText"] = "Wir erforschen\nhier POKéMON.\fWir erstellen oft\nGutachten über\vseltene POKéMON.",
  ["_CinnabarLabFossilRoomScientist1ComeAgainText"] = "Du bist jederzeit\nwillkommen!",
  ["_CinnabarLabFossilRoomScientist1FossilIsBackToLifeText"] = "Wo warst Du?\fWir haben\nDein Fossil\vwiederbelebt!\fEin {RAM:wStringBuffer},\nganz wie ich es\vvermutet habe!",
  ["_CinnabarLabFossilRoomScientist1GoForAWalkText"] = "Es wird einige\nZeit dauern!\fKomm einfach\nspäter wieder\vvorbei!",
  ["_CinnabarLabFossilRoomScientist1GoForAWalkText2"] = "Es wird einige\nZeit dauern!\fKomm einfach\nspäter wieder\vvorbei!",
  ["_CinnabarLabFossilRoomScientist1NoFossilsText"] = "Nein? Zu schade!",
  ["_CinnabarLabFossilRoomScientist1SeesFossilText"] = "Oh! Das ist ein\n{RAM:wNameBuffer}!\fEs ist ein Fossil\nvon {RAM:wStringBuffer},\veinem schon lange\vausgestorbenen\vPOKéMON!\fDank modernster\nTechnik können\vwir POKéMON\vaus Fossilien\vwiederbeleben!",
  ["_CinnabarLabFossilRoomScientist1TakesFossilText"] = "Gib es schnell\nher, damit ich\vfortfahren kann!\f{PLAYER} übergibt\ndas {RAM:wNameBuffer}!",
  ["_CinnabarLabFossilRoomScientist1Text"] = "Hallo!\fIch leite hier\ndie Forschungen!\fWir erforschen\nFossilien von\vURZEIT-POKéMON!\fHast Du ein\nFossil für mich?",
  ["_CinnabarLabMeetingRoomSignText"] = "POKéMON-LABOR\nKonferenzraum",
  ["_CinnabarLabMetronomeRoomAmberPipeText"] = "Eine Pfeife aus\nBernstein!",
  ["_CinnabarLabMetronomeRoomPCText"] = "Eine E-Mail ist\nangekommen!\f...\fARKTOS, ZAPDOS\nund LAVADOS sind\vdie 3 legendären\vVOGEL-POKéMON.\fNiemand weiß, in\nwelcher Gegend\vsie leben.\fWir werden als\nnächstes in der\vHöhle nahe AZURIA\vCITY suchen.\fVon: POKéMON-\nFORSCHUNGSTEAM\f...",
  ["_CinnabarLabMetronomeRoomScientist1ReceivedTM35Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_CinnabarLabMetronomeRoomScientist1TM35ExplanationText"] = "Tak-tak-tak!\nSo klingt ein\vMETRONOM!\fDamit setzt Dein\nPOKéMON Attacken\vein, die es gar\vnicht kennt!",
  ["_CinnabarLabMetronomeRoomScientist1TM35NoRoomText"] = "Dein Rucksack\nist zu voll!",
  ["_CinnabarLabMetronomeRoomScientist1Text"] = "Tak-tak-tak!\nIch habe eine\vTM konstruiert!\fSie verursacht\ndie verrücktesten\vDinge!",
  ["_CinnabarLabMetronomeRoomScientist2Text"] = "EVOLI kann sich\nzu einem von drei\vverschiedenen\vPOKéMON\ventwickeln.",
  ["_CinnabarLabPhotoText"] = "Der Gründer des\nLABORATORIUMS,\vDR. FUJI!",
  ["_CinnabarLabRAndDSignText"] = "POKéMON-LABOR\nForschung und\vEntwicklung",
  ["_CinnabarLabTestingRoomSignText"] = "POKéMON-LABOR\nVersuchsabteilung",
  ["_CinnabarLabTradeRoomSuperNerdText"] = "Ich habe auf dem\nMONDBERG ein\vseltsames Fossil\vgefunden!\fIch denke, es\nstammt von einem\vseltenen URZEIT-\vPOKéMON!",
  ["_CinnabarMartScientistText"] = "Man sollte immer\neinige Tränke bei\vsich tragen!",
  ["_CinnabarMartSilphWorkerFText"] = "Trägst Du kein\nX-ANGRIFF bei\vDir? Es ist in\vKämpfen sehr\vnützlich!",
  ["_CinnabarPokecenterCooltrainerFText"] = "Man kann die\nEntwicklung eines\vPOKéMON stoppen.\fBricht man sie\nab, dann bleibt\vdas POKéMON,\vwie es ist.",
  ["_CinnabarPokecenterGentlemanText"] = "Tausche POKéMON\nmit Freunden!\fEin POKéMON, das\nman bei einem\vTausch erhält,\vwächst schneller!\fDu solltest es\nausprobieren!",
  ["_CinnabarPokecenterGuyText"] = "Brichst Du ihre\nEntwicklung ab,\vdann können Deine\vPOKéMON weitere\vAttacken lernen.\fSie können sich\nauch später noch\vweiterentwickeln.",
  ["_CinnabarQuizQuestionsText1"] = "Entwickelt sich\nRAUPY zu SMETTBO?",
