  ["_CopycatsHouse1FMiddleAgedManText"] = "Meine Tochter\nahmt gerne Leute\vnach.\fWegen ihres\nMienenspiels\vnennt man sie die\vNACHAHMERIN!",
  ["_CopycatsHouse1FMiddleAgedWomanText"] = "Meine Tochter\nist furchtbar\vschüchtern! Sie\vhat nur wenige\vFreunde!",
  ["_CopycatsHouse2FCopycatDoYouLikePokemonText"] = "{PLAYER}: Hallo!\nMagst Du POKéMON?\f{PLAYER}: Halt,\nich habe doch\vDich gefragt.\f{PLAYER}: Wie?\nDu bist komisch!\fNACHAHMERIN: Hmm?\nIch soll die\vNachahmerei\vaufgeben?\fAber das ist\ndoch mein Hobby!",
  ["_CopycatsHouse2FCopycatReceivedTM31Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
