  ["_FightingDojoBlackbelt1EndBattleText"] = "\nIch gebe auf!",
  ["_FightingDojoBlackbelt2AfterBattleText"] = "Unser Meister ist\nein echter Profi!",
  ["_FightingDojoBlackbelt2BattleText"] = "Du sollst sehr\ngut sein!\vBeweise es mir!",
  ["_FightingDojoBlackbelt2EndBattleText"] = "\nSchiedsrichter!",
  ["_FightingDojoBlackbelt3AfterBattleText"] = "Die einzige\nSache, vor der\vwir uns fürchten,\vist PSYCHOKINESE!",
