  ["_FightingDojoKarateMasterDefeatedText"] = "\nArrgh! Ich wurde\vgeschlagen!",
  ["_FightingDojoKarateMasterIWillGiveYouAPokemonText"] = "Ich bin Deiner\nGnade unwürdig!\fTrotzdem flehe\nich Dich an,\vunser Emblem\vnicht als Trophäe\vmitzunehmen!\fZum Ersatz gebe\nich Dir ein\vpreisgekröntes\vKAMPF-POKéMON!\fWähle eines von\nbeiden aus!",
  ["_FightingDojoKarateMasterStayAndTrainWithUsText"] = "Hai!\fBleibe doch hier\nund trainiere\vKarate mit uns!",
  ["_FightingDojoKarateMasterText"] = "Willkommen!\fIch bin der\nKARATE-MEISTER!\vIch leite diese\vPKMN-ARENA!\fDu forderst mich\nheraus? Also gut!\vIch kenne keine\vGnade!\fLos geht's!",
  ["_FightingDojoText"] = "KAMPFARENA",
  ["_FileDataDestroyedText"] = "Die Speicherdaten\nsind defekt!",
