  ["_GameCornerClerkCoinCaseIsFullText"] = "Dein MÜNZKORB\nist voll!",
  ["_GameCornerClerkDoYouNeedSomeGameCoinsText"] = "Willkommen\nin der ROCKET\vSPIELHALLE!\fBenötigst Du\nSpiel-Münzen?\fFür ¥1000\nerhältst Du 50\vMünzen. OK?",
  ["_GameCornerClerkDontHaveCoinCaseText"] = "Du benötigst\neinen MÜNZKORB!",
  ["_GameCornerClerkPleaseComePlaySometimeText"] = "Nein? Dann komm\nvorbei, wenn Du\vspielen möchtest!",
  ["_GameCornerClerkThanksHereAre50CoinsText"] = "Danke! Hier sind\nDeine 50 Münzen!",
  ["_GameCornerCoinCaseText"] = "Du benötigst\neinen MÜNZKORB!",
  ["_GameCornerFishingGuru1DontNeedMyCoinsText"] = "Du brauchst meine\nMünzen nicht!",
  ["_GameCornerFishingGuru1Received10CoinsText"] = "{PLAYER} erhält\n10 Münzen!",
  ["_GameCornerFishingGuru1WantToPlayText"] = "Möchtest Du auch\nspielen, Junge?",
  ["_GameCornerFishingGuru1WinsComeAndGoText"] = "Mal gewinnt man,\nmal verliert man!",
  ["_GameCornerFishingGuru2CloselyWatchTheReelsText"] = "Du mußt die\nWalzen genau im\vAuge behalten!",
