  ["_GameCornerGamblerText"] = "Glücksspiele sind\nunheimlich!\vMan wird schnell\vdavon abhängig!",
  ["_GameCornerGymGuideChampInMakingText"] = "Hey!\fDu hast\nWichtigeres zu\vtun, Champion\vin spe!\fDie ARENALEITERIN\nvon PRISMANIA\vCITY heißt ERIKA.\vSie trainiert\vPFLANZEN-POKéMON!\fSie wirkt sanft,\ndoch man sollte\vsie nicht\vunterschätzen!",
  ["_GameCornerGymGuideTheyOfferRarePokemonText"] = "Man kann die\nMünzen gegen\vseltene POKéMON\veintauschen.\fAber ich habe\nkein Glück im\vSpiel!",
  ["_GameCornerMiddleAgedMan1Text"] = "Pst! Hör mir zu!\fMan sagt, diese\nSPIELHALLE gehöre\vTEAM ROCKET!",
  ["_GameCornerMiddleAgedMan2INeedMoreCoinsText"] = "Mist! Ich habe\nnoch immer nicht\vgenug Münzen für\vdas POKéMON!",
