  ["_MrFujisHouseLittleGirlPokemonAreNiceToHugText"] = "POKéMON sind so\nputzig! Sie sind\vwunderbare\vSchmusetiere!",
  ["_MrFujisHouseLittleGirlThisIsMrFujisHouseText"] = "Das hier ist\nMR. FUJIS Haus.\fEr ist sehr\nfürsorglich!\fEr kümmert sich\num ausgesetzte\vund verwaiste\vPOKéMON!",
  ["_MrFujisHouseMrFujiHasMyFluteHelpedYouText"] = "MR. FUJI: War die\nFLÖTE schon von\vNutzen für Dich?",
  ["_MrFujisHouseMrFujiIThinkThisMayHelpYourQuestText"] = "MR.FUJI: {PLAYER}!\fDu kannst Deinen\nPOKéDEX nicht\vvollenden, wenn\vDu Deinen POKéMON\vnicht genügend\vLiebe und Respekt\ventgegenbringst.\fDies wird Dir bei\nDeinem Abenteuer\vhelfen.",
  ["_MrFujisHouseMrFujiPokeFluteExplanationText"] = "\fSchlafende\nPOKéMON wachen\vauf, wenn sie\vdas Spiel der\vPOKéFLÖTE hören!\fDu kannst damit\nalle schlafenden\vPOKéMON wecken!",
  ["_MrFujisHouseMrFujiPokeFluteNoRoomText"] = "Du hast keinen\nPlatz für weitere\vItems!",
  ["_MrFujisHouseMrFujiPokedexText"] = "GROSSES\nPOKéMON-\vGEWINNSPIEL!\fEs sind keine\nTeilnahmekarten\vmehr vorhanden!\fSie wurden alle\nabgeschickt!",
  ["_MrFujisHouseMrFujiReceivedPokeFluteText"] = "{PLAYER} erhält\neine {RAM:wStringBuffer}!",
  ["_MrFujisHouseNidorinoText"] = "NIDORINO:  Nido!",
  ["_MrFujisHousePsyduckText"] = "ENTON: Enton!",
  ["_MrFujisHouseSuperNerdMrFujiHadBeenPrayingText"] = "MR. FUJI hat oft\nfür TRAGOSSOS\vMutter gebetet.",
  ["_MrFujisHouseSuperNerdMrFujiIsntHereText"] = "MR. FUJI ist\nnicht zu Hause.\vWohin mag er\vgegangen sein?",
  ["_MrMimeDexEntry"] = "PANTIMOS verwirrt\nGegner durch sein\nMienenspiel.\fSie glauben, Dinge\nzu sehen, die gar\nnicht existieren.",
  ["_MrPsychicsHouseMrPsychicReceivedTM29Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_MrPsychicsHouseMrPsychicTM29ExplanationText"] = "TM29 ist\nPSYCHOKINESE!\fSie vermindert\ndie SPEZIAL-\vFÄHIGKEITEN des\vGegners.",
  ["_MrPsychicsHouseMrPsychicTM29NoRoomText"] = "Hey, Du kannst\nkeine Items mehr\vtragen!",
  ["_MrPsychicsHouseMrPsychicYouWantedThisText"] = "Warte! Sag\nkein Wort!\fDu suchst dies\nhier, oder?",
  ["_MtMoon1FBewareZubatSign"] = "VORSICHT!\nZUBAT ist ein\vBlutsauger!",
  ["_MtMoon1FCooltrainerF1AfterBattleText"] = "Wie kommt man\nhier bloß wieder\vheraus?",
  ["_MtMoon1FCooltrainerF1BattleText"] = "Wow, hier drinnen\nkann man sich\vleicht verlaufen!",
  ["_MtMoon1FCooltrainerF1EndBattleText"] = "Nein! Ich\nhabe verloren!",
  ["_MtMoon1FCooltrainerF2AfterBattleText"] = "Gerüchten zufolge\nsoll es hier sehr\vseltene Fossilien\vgeben.",
  ["_MtMoon1FCooltrainerF2BattleText"] = "Was gibt's? Meine\nKumpels müßten\vgleich hier sein.",
  ["_MtMoon1FCooltrainerF2EndBattleText"] = "Ich hab\nverloren?",
  ["_MtMoon1FHikerAfterBattleText"] = "Hier ist kein\nSpielplatz. Zieh\vLeine, Kleiner!",
  ["_MtMoon1FHikerBattleText"] = "Hilfe! Überfall!\nAch, Du bist ja\vnur ein Kind!",
  ["_MtMoon1FHikerEndBattleText"] = "Wow! Du\nhast mich total\vüberrumpelt!!!",
  ["_MtMoon1FSuperNerdAfterBattleText"] = "Ich muß stärkere\nPOKéMON fangen!",
  ["_MtMoon1FSuperNerdBattleText"] = "Hey! Schleich\nnicht so herum!",
  ["_MtMoon1FSuperNerdEndBattleText"] = "Meine\nPOKéMON bringen\ves nicht!",
  ["_MtMoon1FYoungster1AfterBattleText"] = "Ich bin hier, weil\ndie Mädchen auf\vharte Kerle wie\vmich stehen!",
  ["_MtMoon1FYoungster1BattleText"] = "Bist Du auch auf\nForschungsreise?",
  ["_MtMoon1FYoungster1EndBattleText"] = "So ein\nMist! Verloren!",
  ["_MtMoon1FYoungster2AfterBattleText"] = "Ohne Zweifel! Die\nTypen waren vom\vTEAM ROCKET!",
  ["_MtMoon1FYoungster2BattleText"] = "Wer da? Wohin man\nschaut: Überall\vnur zwielichtige\vGestalten!",
  ["_MtMoon1FYoungster2EndBattleText"] = "Du\nhast mich eiskalt\verwischt!",
  ["_MtMoon1FYoungster3AfterBattleText"] = "ZUBAT ist recht\nwiderspenstig, es\vkann im Kampf\vjedoch sehr\vnützlich sein!",
  ["_MtMoon1FYoungster3BattleText"] = "Du erreichst\nAZURIA CITY, wenn\vDu es durch diese\vHöhle schaffst!",
  ["_MtMoon1FYoungster3EndBattleText"] = "Ich\nhab verloren...",
  ["_MtMoonB1FUnusedText"] = "",
  ["_MtMoonB2FDomeFossilYouWantText"] = "Möchtest Du das\nDOMFOSSIL?",
  ["_MtMoonB2FHelixFossilYouWantText"] = "Möchtest Du das\nHELIXFOSSIL?",
  ["_MtMoonB2FReceivedFossilText"] = "{PLAYER} erhält\ndas {RAM:wStringBuffer}!",
  ["_MtMoonB2FRocket2AfterBattleText"] = "Verdammt! Wie\nerkläre ich das\vmeinen Partnern?",
  ["_MtMoonB2FRocket2BattleText"] = "Wir sind TEAM\nROCKET, die\vPOKéMON-Räuber!",
  ["_MtMoonB2FRocket2EndBattleText"] = "Ich\nhab's vermasselt!",
  ["_MtMoonB2FRocket3AfterBattleText"] = "Wenn Du ein Fossil\nhast, gib es her\vund verschwinde!",
  ["_MtMoonB2FRocket3BattleText"] = "Wir drehen hier\nein dickes Ding!\vMach Dich vom\vAcker!",
  ["_MtMoonB2FRocket3EndBattleText"] = "Du\nbist 'ne harte\vNuß, Kleiner!",
  ["_MtMoonB2FRocket4AfterBattleText"] = "Schon lange vor\nden Menschen\vhaben POKéMON\vhier gelebt...",
  ["_MtMoonB2FRocket4BattleText"] = "Geh Erwachsenen\nnicht auf den\vWecker, Du\vNervensäge!",
  ["_MtMoonB2FRocket4EndBattleText"] = "\nIch bin sauer!",
  ["_MtMoonB2FSuperNerdOkIllShareText"] = "Na gut!\nIch gebe Dir\veins ab!",
  ["_MtMoonB2FSuperNerdThenThisIsMineText"] = "OK, dann gehört\ndas hier mir!",
  ["_MtMoonB2FSuperNerdTheresAPokemonLabText"] = "Auf der fernen\nZINNOBERINSEL\vgibt es ein\vPOKéMON-Labor.\fDort versucht\nman, aus fossilem\vGen-Material\vPOKéMON zu\vschaffen.",
  ["_MtMoonB2FSuperNerdTheyreBothMineText"] = "Stop! Hände weg!\fWer zuerst kommt,\nmahlt zuerst!\fDie Fossilien\ngehören MIR!",
  ["_MtMoonB2FYouHaveNoRoomText"] = "Du kannst keinen\nGegenstand mehr\vtragen!",
  ["_MtMoonB2fSuperNerdEachTakeOneText"] = "Hey, nicht so\ngierig! Ich gebe\vDir ja eins ab!",
  ["_MtMoonJessieJamesText1"] = "Bleib auf der\nStelle stehen!",
  ["_MtMoonJessieJamesText2"] = "Das Fossil gehört\nTEAM ROCKET!\fGib lieber auf\nund bekämpfe uns\vnicht!",
  ["_MtMoonJessieJamesText3"] = "So\nein Balg hat\vuns besiegt?",
  ["_MtMoonJessieJamesText4"] = "TEAM ROCKET - so\nschnell wie das\vLicht...",
  ["_MtMoonPokecenterBenchGuyText"] = "Wenn Du keine\nweiteren POKéMON\vtragen kannst,\vsolltest Du\veinige via PC\vablegen!",
  ["_MtMoonPokecenterClipboardText"] = "",
  ["_MtMoonPokecenterGentlemanText"] = "TEAM ROCKET\nterrorisiert die\vEinwohner von\vAZURIA CITY!\fKein Tag vergeht\nohne Meldungen\vüber TEAM ROCKETS\vSchandtaten!",
  ["_MtMoonPokecenterMagikarpSalesmanIGotADealText"] = "MANN: Hallo!\nMöchtest Du ein\vGeschäft machen?\fIch gebe Dir\nein exzellentes\vKARPADOR für\vläppische ¥500!\vInteressiert?",
  ["_MtMoonPokecenterMagikarpSalesmanNoMoneyText"] = "Schade, Du hast\nnicht genug Geld!",
  ["_MtMoonPokecenterMagikarpSalesmanNoRefundsText"] = "MANN:\nDer Umtausch ist\vausgeschlossen!",
  ["_MtMoonPokecenterMagikarpSalesmanNoText"] = "Nein? Ich wollte\nDir doch einen\vGefallen tun!",
  ["_MtMoonPokecenterYoungsterText"] = "An meinem Gürtel\nhängen sechs\vPOKéBÄLLE.\fMan kann maximal\nsechs POKéMON\vmit sich führen.",
  ["_MukDexEntry"] = "Dieses POKéMON\nverbreitet einen\nso erbärmlichen\fGestank, daß es\nsich selbst nicht\nmehr riechen kann.",
  ["_MultiHitText"] = "Der Gegner wurde\n{NUM:wPlayerNumHits, 1, 1}mal getroffen!",
  ["_Museum1FGamblerText"] = "Dies ist ein\naußergewöhnliches\vFossil!",
  ["_Museum1FOldAmberText"] = "Das BERNSTEIN\nschimmert\vgoldbraun und\vist durchsichtig!",
  ["_Museum1FScientist1AmberIsFossilizedTreeSapText"] = "BERNSTEIN ist\nversteinertes\vBaumharz.",
  ["_Museum1FScientist1ComeAgainText"] = "Komm bald wieder!",
  ["_Museum1FScientist1DoYouKnowWhatAmberIsText"] = "Du hast hinter\ndem Tresen nichts\vzu suchen!\fNaja, egal!\nWeißt Du, was\vBERNSTEIN ist?",
  ["_Museum1FScientist1DontHaveEnoughMoneyText"] = "Du hast nicht\ngenug Geld.",
  ["_Museum1FScientist1GoToOtherSideText"] = "Gehe bitte auf\ndie andere Seite!",
  ["_Museum1FScientist1TakePlentyOfTimeText"] = "Nimm Dir Zeit und\nschaue alles an!",
  ["_Museum1FScientist1ThankYouText"] = "OK, das sind ¥50!\nVielen Dank!",
  ["_Museum1FScientist1TheresALabSomewhereText"] = "Es soll ein Labor\ngeben, in dem man\vversucht, aus\valtem BERNSTEIN\vURZEIT-POKéMON\vwiederauferstehen\vzu lassen!",
  ["_Museum1FScientist1WouldYouLikeToComeInText"] = "Für Kinder kostet\nder Eintritt ¥50!\fMöchtest Du\nhinein?",
  ["_Museum1FScientist2GetTheOldAmberCheckText"] = "Pst! Laß den\nALTBERNSTEIN\vuntersuchen!",
  ["_Museum1FScientist2ReceivedOldAmberText"] = "{PLAYER} erhält\neinen\vALTBERNSTEIN!",
  ["_Museum1FScientist2TakeThisToAPokemonLabText"] = "Pst! Ich glaube,\nin diesem Stück\vBERNSTEIN ist\vPOKéMON-DNA\venthalten!\fEs wäre grandios,\nwenn man daraus\vein POKéMON\vwiederauferstehen\vlassen könnte!\fDoch meine\nKollegen nehmen\vmich nicht ernst!\fKönntest Du\netwas für mich\verledigen?\fLaß das im\nPOKéMON-LABOR\vuntersuchen!",
  ["_Museum1FScientist2YouDontHaveSpaceText"] = "Du hast keinen\nPlatz für weitere\vItems!",
  ["_Museum1FScientist3Text"] = "Unser besonderer\nStolz sind zwei\vFossilien von\väußerst seltenen,\vprähistorischen\vPOKéMON!",
  ["_Museum2FBrunetteGirlText"] = "Ich hätte gerne\nein PIKACHU!\vEs ist so\vfurchtbar süß!\fMein Papa soll\nmir eines fangen!",
  ["_Museum2FGrampsText"] = "Der\n20. Juli 1969!\fDie erste\nMondlandung!\fFür die Fernseh-\nübertragung hatte\vich extra einen\vFarbfernseher\vgekauft!",
  ["_Museum2FHikerText"] = "Ja, ein PIKACHU!\nIch verspreche,\vich fange eins!",
  ["_Museum2FMoonStoneSignText"] = "Auf dem MONDBERG\ngefundenes\vMeteoritengestein\v(MONDSTEIN?)",
  ["_Museum2FPikachuText1"] = "Dein PIKACHU\nsieht noch wild\vaus! Gibst Du es\vmir für meine\vTochter?",
  ["_Museum2FPikachuText2"] = "Ich würde Dein\nPIKACHU gerne\vnehmen, aber es\vhängt zu sehr an\vDir...",
  ["_Museum2FScientistText"] = "Momentan haben\nwir eine\vRaumfahrt-\vAusstellung.",
  ["_Museum2FSpaceShuttleSignText"] = "SPACE SHUTTLE\nCOLUMBIA",
  ["_Museum2FYoungsterText"] = "MONDSTEIN?\fWas ist daran\nso einzigartig?",
  ["_MustRechargeText"] = "{USER}\nmuß sich wieder \vaufladen!",
  ["_NameRatersHouseNameRaterATrulyImpeccableNameText"] = "{RAM:wNameBuffer}!\nEin wirklich\vtadelloser Name!\fKümmere Dich gut\num {RAM:wNameBuffer}!",
  ["_NameRatersHouseNameRaterComeAnyTimeYouLikeText"] = "Komm vorbei, wann\nimmer Du magst!",
  ["_NameRatersHouseNameRaterGiveItANiceNameText"] = "Der Spitzname ist\n{RAM:wNameBuffer}, oder?\vEin schöner Name!\fGefällt er Dir\nnoch immer, oder\vmöchtest Du ihn\vändern?\fNamen ändern?",
  ["_NameRatersHouseNameRaterPokemonHasBeenRenamedText"] = "OK! Der neue Name\ndieses POKéMON\vist {RAM:wBuffer}!\fEin noch\nschönerer Name\vals zuvor!",
  ["_NameRatersHouseNameRaterWantMeToRateText"] = "Hallo! Ich bin\nder offizielle\vNAMEN-BEWERTER!\fSoll ich die\nSpitznamen Deiner\vPOKéMON bewerten?",
  ["_NameRatersHouseNameRaterWhatShouldWeNameItText"] = "Gut! Wie soll der\nneue Name lauten?",
  ["_NameRatersHouseNameRaterWhichPokemonText"] = "Von welchem\nPOKéMON soll ich\vden Spitznamen\vbeurteilen?",
  ["_NeedYourPokemonText"] = "OK. Wir benötigen\nDeine POKéMON.",
  ["_NewBadgeRequiredText"] = "Nein! Hier\nbenötigt man\veinen neuen\vORDEN!",
  ["_NewBicycleText"] = "Ein brandneues\nFAHRRAD!",
  ["_NidokingDexEntry"] = "Die Haut dieses\nPOKéMON ist so\nhart wie Stahl.\fMit seinen Hörnern\nkann es sogar\nDiamanten spalten.",
  ["_NidoqueenDexEntry"] = "Der Rücken dieses\nPOKéMON wird von\nharten Schuppen\fbedeckt. Die\nSchuppen wachsen\nkreisförmig.",
  ["_NidoranFDexEntry"] = "Dieses wilde\nPOKéMON vermeidet\nden Kampf.\fDas kleine Horn\nauf seinem Kopf\nenthält Gift.",
  ["_NidoranMDexEntry"] = "Die Ohren dieses\nPOKéMON sind\nsehr sensibel.\fDroht Gefahr, so\nattackiert es mit\nseinem Gifthorn.",
  ["_NidorinaDexEntry"] = "Während dieses\nPOKéMON schläft,\nbewegen sich die\fStacheln auf dem\nRücken mit jedem\nAtemzug.",
  ["_NidorinoDexEntry"] = "Die Hörner dieses\nPOKéMON sondern\nim Kampf ein sehr\fstarkes Gift ab,\nwenn sie den\nGegner treffen.",
  ["_NinetalesDexEntry"] = "Der Sage nach\nsind im Körper\ndieses POKéMON\fdie Seelen von\n9 edlen Zauberern\nvereinigt.",
  ["_NoCyclingAllowedHereText"] = "Das Radfahren ist\nhier verboten!",
  ["_NoEffectText"] = "Es hat keine\nWirkung!",
  ["_NoMonText"] = "Diese Box enthält\nkeine POKéMON!",
  ["_NoMoreRoomForItemText"] = "Du kannst keine\nweiteren Items\vtragen!",
  ["_NoMovesLeftText"] = "{RAM:wBattleMonNick} hat\nkeine Attacken\vmehr übrig!",
  ["_NoNibbleText"] = "Nicht einmal ein\nalter Stiefel hat\vangebissen!",
  ["_NoPokemonText"] = "Hier gibt es\nkeine POKéMON!",
  ["_NoRoomToStoreText"] = "Die\nLagerkapazität\vist erschöpft.",
  ["_NoRunningText"] = "Man kann aus\nTRAINER-KÄMPFEN\vnicht fliehen!",
  ["_NoSurfingHereText"] = "Hier kann nicht\nauf {RAM:wNameBuffer}\vgesurft werden!",
  ["_NoTrade1Text"] = "Oje! Wenn\ndas so ist...",
  ["_NoTrade2Text"] = "Wenn Du nicht\nmagst, kann man\vnichts machen!",
  ["_NoTrade3Text"] = "Schade!",
  ["_NoWillText"] = "Das POKéMON\nwurde besiegt!",
  ["_NotEnoughCoinsSlotMachineText"] = "Du hast nicht\ngenug Münzen!",
  ["_NotEnoughMemoryText"] = "Es ist zuwenig\nSpeicher frei!",
  ["_NotHealthyEnoughText"] = "Nicht genug\nKraftpunkte!",
  ["_NotThisTimeText"] = "Vielleicht beim\nnächsten Mal!",
  ["_NotVeryEffectiveText"] = "Die Attacke ist\nnicht effektiv...",
  ["_NothingHappenedText"] = "Nichts geschieht!",
  ["_NothingHereText"] = "Hier findet man\nnichts. Schade!",
  ["_NothingStoredText"] = "Hier lagern keine\nItems.",
  ["_NothingToCutText"] = "Hier kann\nman nichts\vzerschneiden!",
  ["_NothingToDepositText"] = "Du hast keine\nItems, die Du\vlagern könntest.",
  ["_NurseChanseyText"] = "CHANEIRA: Cha!\nChaneira!",
  ["_OHKOText"] = "K.O.-TREFFER!",
  ["_OKExclamationText"] = "OK!",
  ["_OakLabEmailText"] = "Im Briefkasten\nist eine E-Mail!\f...\fAn alle\nPOKéMON-TRAINER!\fDie TRAINER-ELITE\nder PKMN-LIGA\vwartet auf mutige\vHerausforderer!\fBringt Eure\nstärksten POKéMON\vmit und zeigt,\vwie gut Ihr seid!\fPKMN-LIGA-LEITUNG\nINDIGO-PLATEAU\fPS.: PROF. EICH,\nbitte melden Sie\vsich bei uns!\v...",
  ["_OakSpeechText1"] = "Hallo! Herzlich\nwillkommen in der\vWelt der POKéMON!\fMein Name ist\nEICH! Man nennt\vmich den POKéMON-\vPROFESSOR!",
  ["_OakSpeechText2A"] = "Diese Welt wird\nvon Wesen\vbewohnt, die man\vPOKéMON nennt!",
  ["_OakSpeechText2B"] = "\fFür manche Leute\nsind POKéMON\vHaustiere, andere\vtragen Kämpfe mit\vihnen aus.\fIch selbst...\f...habe mein\nHobby zum Beruf\vgemacht und\vstudiere POKéMON.",
  ["_OakSpeechText3"] = "{PLAYER}!\fEine unglaubliche\nReise in die Welt\vder POKéMON\verwartet Dich!\fEine Welt voller\nWunder, Abenteuer\vund Geheimnisse!\vKurz gesagt, ein\vTraum wird wahr!",
  ["_OaksAideComeBackText"] = "Ich habe\neine gute Idee.\fKomm wieder, wenn\nDu {NUM:hOaksAideRequirement, 1, 3} POKéMON\vbesitzt. Ich\vhebe Dir Dein\vGeschenk auf.",
  ["_OaksAideGotItemText"] = "{PLAYER} erhält\ndie {RAM:wOaksAideRewardItemName}!",
  ["_OaksAideHereYouGoText"] = "Super! Du hast\n{NUM:hOaksAideNumMonsOwned, 1, 3} verschiedene\vPOKéMON gefangen!\vEinfach klasse!\fHier, das hast\nDu Dir redlich\vverdient!",
  ["_OaksAideHiText"] = "Hallo! Erinnerst\nDu Dich? Ich bin\vPROF. EICHS\vGehilfe!\fWenn Du\nmindestens {NUM:hOaksAideRequirement, 1, 3}\vverschiedene\vPOKéMON gefangen\vhast, habe ich\vein Geschenk für\vDich: {RAM:wOaksAideRewardItemName}\fAlso, {PLAYER}, \nhast Du {NUM:hOaksAideRequirement, 1, 3}\vunterschiedliche\vPOKéMON gefangen?",
  ["_OaksAideNoRoomText"] = "Oh! Du hast\nmomentan keinen\vPlatz für den\v{RAM:wOaksAideRewardItemName}.",
  ["_OaksAideUhOhText"] = "Mal schauen...\nOh! Du hast erst\v{NUM:hOaksAideNumMonsOwned, 1, 3} verschiedene\vPOKéMON gefangen!\fDu benötigst {NUM:hOaksAideRequirement, 1, 3},\num das Geschenk\vzu erhalten.",
  ["_OaksLabGirlText"] = "PROF. EICH ist\nfür POKéMON\veine Kapazität!\fUnter POKéMON-\nTRAINERN genießt\ver ein sehr hohes\vAnsehen!",
  ["_OaksLabGivePokeballsExplanationText"] = "\fTaucht ein wildes\nPOKéMON auf,\vso kannst Du es \vfangen.\fWerfe einfach\neinen POKéBALL\nund versuche es!\fDoch Du wirst\noftmals keinen\vErfolg haben.\fEin gesundes\nPOKéMON entkommt\vschnell! Man muß\vschon etwas Glück\vhaben!",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "PROF. EICH:\nBesuche mich von\vZeit zu Zeit.\fEs interessiert\nmich, wie Du mit\vDeinem POKéDEX\vvoranschreitest.",
  ["_OaksLabOak1DeliverParcelText"] = "PROF. EICH:\nHallo, {PLAYER}!\fWie geht es\ndem POKéMON?\fEs scheint Dich\nsehr zu mögen!\fDu mußt als\nPOKéMON-TRAINER\vsehr talentiert\vsein!\fDu hast etwas\nfür mich?\f{PLAYER} übergibt\nPROF. EICH das\vPAKET.",
  ["_OaksLabOak1GoAheadItsYours"] = "EICH: Nimm es,\nes gehört Dir!",
  ["_OaksLabOak1HowIsYourPokedexComingText"] = "PROF. EICH:\nIch freue mich,\vDich zu sehen!\vWas macht Dein\vPOKéDEX? Zeig\vdoch mal her!",
  ["_OaksLabOak1ParcelThanksText"] = "\fAh! Auf diesen\nSPEZIAL-POKéBALL\vwarte ich schon\vlange! Danke, \v{PLAYER}!\fIch möchte Dich\nnoch bitten, mir\veinen Gefallen\vzu tun.",
  ["_OaksLabOak1PokemonAroundTheWorldText"] = "{PLAYER},\nüberall in dieser\vWelt erwarten\vDich POKéMON!",
  ["_OaksLabOak1ReceivedPokeballsText"] = "PROF. EICH:\nEs reicht nicht, \vPOKéMON zu sehen,\vum detaillierte\vInformationen\vüber sie zu\vsammeln!\fDu mußt sie\nfangen! Benutze\vdas hier, um\vwilde POKéMON\veinzufangen.\f{PLAYER} erhält\nfünf POKéBÄLLE!",
  ["_OaksLabOak1YouShouldTalkToIt"] = "EICH: Du solltest\nmit ihm sprechen\vund Dich um es\vkümmern.",
  ["_OaksLabOak1YourPokemonCanFightText"] = "PROF. EICH: Wenn\nDu auf ein wildes\vPOKéMON triffst,\vdann kann Dein\vPOKéMON dagegen\vkämpfen!\fGehe danach in\ndie nächste\vStadt!",
  ["_OaksLabOak2Text"] = "?",
  ["_OaksLabOakBePatientText"] = "EICH: Habe einen\nMoment Geduld,\v{RIVAL}. Ich gebe\vDir später eines.",
  ["_OaksLabOakChooseMonText"] = "PROF. EICH:\n{RIVAL}? Du bist\vfrüh dran...\fDu solltest doch\nerst später\vkommen...\fNaja, egal. Warte\neinen Moment.\fSiehst Du dort\nden Ball auf dem\vTisch liegen,\v{PLAYER}?\fDas ist ein\nPOKéBALL. Darin\vbefindet sich ein\vPOKéMON.\fIch schenke es\nDir, nimm es Dir\vruhig!",
  ["_OaksLabOakDontGoAwayYetText"] = "PROF. EICH:\nWarte noch einen\vMoment, bevor Du\vgehst!",
  ["_OaksLabOakGivesText"] = "EICH: {PLAYER},\nich habe noch ein\vPOKéMON gefangen!\fIch gebe es Dir.\nAllerdings ist es\vein ungezähmtes,\vwildes POKéMON.",
  ["_OaksLabOakGotPokedexText"] = "PROF. EICH:\n{PLAYER}! {RIVAL}!\vDiese beiden sind\vfür Euch!\f{PLAYER} erhält\neinen POKéDEX von\vPROF. EICH!",
  ["_OaksLabOakIHaveARequestText"] = "EICH: Ah, {RIVAL},\nDu kommst genau\vzur rechten Zeit.\fIch möchte Euch\num einen großen\vGefallen bitten.",
  ["_OaksLabOakMyInventionPokedexText"] = "Auf dem Tisch\ndort seht Ihr\veine Erfindung\vvon mir, den\vPOKéDEX!\fEr erfaßt\nautomatisch Daten\vüber POKéMON,\vdie man gefangen\voder gesehen hat!\fEr ist eine Art\nHi-Tech-Lexikon!",
  ["_OaksLabOakThatWasMyDreamText"] = "Ein Lexikon über\nalle POKéMON der\vWelt...\fDas war immer\nmein Traum!\fAber ich bin zu\nalt! Ich schaffe\ves nicht mehr!\fAlso bitte ich\nEuch, meinen\vTraum zu\vverwirklichen!\fMacht Euch auf\nden Weg, Jungs!\fDies ist eines\nder bedeutendsten\vProjekte in der\vGeschichte der\vPOKéMON!",
  ["_OaksLabPikachuDislikesPokeballsText1"] = "EICH: Wie bitte?",
  ["_OaksLabPikachuDislikesPokeballsText2"] = "EICH: Schau Dir\ndas an!\fEs ist seltsam,\naber Dein PIKACHU\vmag scheinbar\vkeine POKéBÄLLE.\fEs muß Dich\nso begleiten.\fDann ist es\nauch glücklich.\fDu kannst mit ihm\nsprechen und\vmerkst dann, ob\ves Dich mag.",
  ["_OaksLabPokedexText"] = "Es sieht wie ein\nLexikon aus! Aber\vdie Seiten sind\vunbeschrieben!",
  ["_OaksLabReceivedText"] = "{PLAYER} erhält\nein {RAM:wNameBuffer}!",
  ["_OaksLabRivalAmIGreatOrWhatText"] = "{RIVAL}: Ja! Ich\nbin der Größte!",
  ["_OaksLabRivalFedUpWithWaitingText"] = "{RIVAL}: Opa!\nIch will nicht\vlänger warten!",
  ["_OaksLabRivalGrampsIsntAroundText"] = "{RIVAL}: Hey,\n{PLAYER}! Opa\vist nicht hier!\fIch bin hierher\ngekommen, weil er\vmir ein POKéMON\vgeben wollte.",
  ["_OaksLabRivalGrampsText"] = "{RIVAL}: Opa!",
  ["_OaksLabRivalIPickedTheWrongPokemonText"] = "WAS?\nUnmöglich! Ich\vhabe mir das\vfalsche POKéMON\vausgesucht!",
  ["_OaksLabRivalIllGetABetterPokemonThanYou"] = "{RIVAL}: Pah!\nIch werde ein\vbesseres POKéMON\vals Du erhalten!",
  ["_OaksLabRivalIllTakeYouOnText"] = "{RIVAL}: Warte,\n{PLAYER}!\vLaß uns unsere\vPOKéMON testen!\fKomm schon!\nIch fordere Dich\vheraus!",
  ["_OaksLabRivalLeaveItAllToMeText"] = "{RIVAL}:\nAlles klar, Opa!\vÜberlaß es\vruhig mir!\f{PLAYER},  es tut\nmir leid, aber\vich brauche Deine\vHilfe nicht!\fIch hab's! Ich\nleihe mir von\vmeiner Schwester\veine KARTE!\fUnd Dir soll sie\nkeine geben,\v{PLAYER}! Hahaha!",
  ["_OaksLabRivalMyPokemonHasGrownStrongerText"] = "{RIVAL}: Opa,\nmein POKéMON ist\vstärker geworden!\vSchau es Dir an!",
  ["_OaksLabRivalMyPokemonLooksStrongerText"] = "{RIVAL}: Mein\nPOKéMON sieht\vviel stärker aus!",
  ["_OaksLabRivalSmellYouLaterText"] = "{RIVAL}: OK!\nIch werde mein\vPOKéMON\vtrainieren, damit\ves stärker wird!\f{PLAYER}! Opa!\nWir sehen uns\vspäter!",
  ["_OaksLabRivalTakesText1"] = "{RIVAL}: Nein!\n{PLAYER}, ich will\vdieses POKéMON!",
  ["_OaksLabRivalTakesText2"] = "{RIVAL} schnappt\nsich das POKéMON!",
  ["_OaksLabRivalTakesText3"] = "EICH: {RIVAL}!\nWas soll das?",
  ["_OaksLabRivalTakesText4"] = "{RIVAL}: Bitte,\nOpa! Ich möchte\vdieses POKéMON!",
  ["_OaksLabRivalTakesText5"] = "EICH: Aber...\nHmm. OK. Behalte\vdieses POKéMON.\vEs ist Deines.\fIch hätte Dir\nsowieso eines\vgegeben...\f{PLAYER}, komm zu\nmir herüber.",
  ["_OaksLabRivalWhatAboutMeText"] = "{RIVAL}: Halt!\nOpa! Und was ist\vmit mir?",
  ["_OaksLabScientistText"] = "Ich bin PROF.\nEICHS Gehilfe.\vIch studiere mit\vihm die POKéMON!",
  ["_OaksLabThatsAPokeball"] = "Das ist ein\nPOKéBALL. Darin\vbefindet sich ein\vPOKéMON!",
  ["_OddishDexEntry"] = "Wenn man versucht,\ndieses Unkraut-\nPOKéMON aus der\fErde zu ziehen,\ndann schreit es\nfürchterlich laut.",
  ["_OfficerJennyText1"] = "Ich habe ein\nSCHIGGY gefangen.\vAber dieses\vPOKéMON macht nur\vDummheiten!\fIch denke, ein\nguter Trainer\vsollte SCHIGGY\vrichtig erziehen\vkönnen.",
  ["_OfficerJennyText2"] = "Du trägst den\nDONNERORDEN!?\fDann bist Du ein\nguter Trainer!\fIch habe ein\nSCHIGGY gefangen.\vAber dieses\vPOKéMON macht nur\vDummheiten!\fWürdest Du Dich\num mein SCHIGGY\vkümmern?",
  ["_OfficerJennyText3"] = "OK, aber behandle\nmein SCHIGGY gut!",
  ["_OfficerJennyText4"] = "Oh... Was soll\nich nur machen?",
  ["_OfficerJennyText5"] = "Wie geht es\nSCHIGGY?",
  ["_OhFineThenText"] = "Dann ist ja alles\nklar.",
  ["_OlderFileWillBeErasedText"] = "Der bisherige\nSpielstand wird\vüberschrieben!\vOK?",
  ["_OmanyteDexEntry"] = "Dieses Urzeit-\nPOKéMON wurde aus\neinem Fossil\fwiederbelebt. Es\nbewegt sich mit\nseinen Tentakeln.",
  ["_OmastarDexEntry"] = "Dieses POKéMON\nverfügt über einen\nsehr scharfen\fSchnabel. Es ist\nbereits vor langer\nZeit ausgestorben.",
  ["_OnceReleasedText"] = "Ist es erstmal\nfreigelassen,\vkommt {RAM:wStringBuffer}\vnicht wieder\vzurück. OK?",
  ["_OneMoreGoSlotMachineText"] = "Noch eine\nRunde?",
  ["_OneTwoAndText"] = "1, 2, ",
  ["_OnixDexEntry"] = "Dieses POKéMON\ngräbt auf seiner\nSuche nach Futter\flange Tunnel, in\ndenen sich später\nDIGDAS einnisten.",
  ["_OopsYouDontHaveEnoughRoomText"] = "Ups! Du hast\nmomentan keinen\vPlatz dafür!",
  ["_OutOfCoinsSlotMachineText"] = "Mist!\nIch habe keine\vMünzen mehr!",
  ["_OutOfSafariBallsText"] = "DURCHSAGE: Gong!\fDu hast keine\nSAFARIBÄLLE mehr!",
  ["_PPIncreasedText"] = "Die AP von\n{RAM:wStringBuffer}\vsind gestiegen.",
  ["_PPMaxedOutText"] = "Die AP von\n{RAM:wStringBuffer} sind\vauf dem Maximum!",
  ["_PPRestoredText"] = "Die AP wurden\naufgefüllt!",
  ["_PalletTownFisherText"] = "Die Technik\nheutzutage ist\vunglaublich!\fMan kann sogar\nItems und POKéMON\vvia PC lagern und\vwieder abrufen!",
  ["_PalletTownGirlText"] = "Auch ich ziehe\nPOKéMON auf!\fWenn sie stark\nsind, können sie\vmich beschützen!",
  ["_PalletTownOakComeWithMe"] = "PROF. EICH:\nWilde POKéMON\vkönnen jederzeit\vauftauchen!\fDu brauchst eigene\nPOKéMON, um\vDich zu schützen.\fKomm, folge\nmir!",
  ["_PalletTownOakHeyWaitDontGoOutText"] = "EICH: Warte!\nGeh nicht raus!",
  ["_PalletTownOakThatWasCloseText"] = "PROF. EICH:\nDas war knapp!\fWilde POKéMON\nleben in hohem\vGras!",
  ["_PalletTownOakWhewText"] = "PROF. EICH: Puuh!",
  ["_PalletTownOaksLabSignText"] = "PROFESSOR EICH\nPOKéMON-LABOR",
  ["_PalletTownPlayersHouseSignText"] = "Haus von {PLAYER}",
  ["_PalletTownRivalsHouseSignText"] = "Haus von {RIVAL}",
  ["_PalletTownSignText"] = "ALABASTIA\nDich erwarten\vaufregende\vAbenteuer!",
  ["_ParalyzedMayNotAttackText"] = "{TARGET}\nist paralysiert!",
  ["_ParasDexEntry"] = "Dieses POKéMON\ngräbt sich in den\nBoden und frißt\fWurzeln. Die Pilze\nauf seinem Rücken\nsind Parasiten.",
  ["_ParasectDexEntry"] = "Der Pilz auf dem\nRücken entzieht\ndem Wirts-POKéMON\fEnergie. Er hat\ndie Kontrolle über\ndas POKéMON.",
  ["_ParlyzHealText"] = "Die Paralyse\nwurde aufgehoben!",
  ["_PartyMenuBattleText"] = "Welches POKéMON\nsoll antreten?",
  ["_PartyMenuItemUseText"] = "Welches POKéMON\nerhält das Item?",
  ["_PartyMenuNormalText"] = "Wähle ein POKéMON\naus!",
  ["_PartyMenuSwapMonText"] = "Mit wem soll das\nPOKéMON tauschen?",
  ["_PartyMenuUseTMText"] = "Wähle ein\nPOKéMON aus!",
  ["_PersianDexEntry"] = "Dieses prächtige\nPOKéMON trägt an\nder Stirn ein\fleuchtendes Juwel.\nEs hat die Eleganz\neiner Königin.",
  ["_PewterCityCooltrainerFText"] = "Gerüchten zufolge\nsollen die PIEPIS\vvom Mond stammen!\fNachdem der\nMONDSTEIN auf den\vMONDBERG fiel,\vsind sie erstmals\vaufgetaucht!",
  ["_PewterCityCooltrainerMText"] = "Hier gibt es nur\nwenige ernsthafte\vPOKéMON-Trainer!\fAber ROCKO, der\nARENALEITER von\vMARMORIA CITY,\vversteht sein\vGeschäft!",
  ["_PewterCityGymSignText"] = "MARMORIA CITY\nPKMN-ARENA\vARENALEITER:\vROCKO\fDer steinharte\nPOKéMON-Trainer!",
  ["_PewterCityMuseumSignText"] = "MARMORIA CITY\nWISSENSCHAFTS-\vMUSEUM",
  ["_PewterCityPokecenterGuyText"] = "Gähn!\fVon PUMMELUFFS\nGESANG werden\vPOKéMON ganz\vmüde...\fIch auch...\nSchnarch...",
  ["_PewterCityPoliceNoticeSignText"] = "ACHTUNG!\fDiebe haben\nPOKéMON-Fossilien\vvom MONDBERG\vgestohlen! Wenn\vSie sachdienliche\vHinweise haben,\vwenden Sie sich\vbitte an die\vPolizei in\vMARMORIA CITY!",
  ["_PewterCitySignText"] = "MARMORIA CITY\nDie steingraue\vStadt!",
  ["_PewterCitySuperNerd1DidYouCheckOutMuseumText"] = "Warst Du schon\nim MUSEUM?",
  ["_PewterCitySuperNerd1ItsRightHereText"] = "Es ist gleich da\ndrüben! Man muß\vzwar Eintritt\vbezahlen, aber\vdas ist es wert!",
  ["_PewterCitySuperNerd1WerentThoseFossilsAmazingText"] = "Waren die\nFossilien vom\vMONDBERG nicht\veinmalig?",
  ["_PewterCitySuperNerd1YouHaveToGoText"] = "Wirklich nicht?\nEs ist aber einen\vBesuch wert!",
  ["_PewterCitySuperNerd2DoYouKnowWhatImDoingText"] = "Pst! Weißt Du,\nwas ich hier\vmache?",
  ["_PewterCitySuperNerd2ImSprayingRepelText"] = "Ich versprühe\nSCHUTZ,  um\vPOKéMON von\vmeinem Garten\vfernzuhalten!",
  ["_PewterCitySuperNerd2ThatsRightText"] = "Stimmt! Es ist\nharte Arbeit!",
  ["_PewterCityTrainerTipsText"] = "TIPS FÜR TRAINER\fUnabhängig von\nder Dauer seines\vEinsatzes erhält\vjedes POKéMON\vfür die Teilnahme\van einem Kampf\vErfahrungspunkte, \vEP! ",
  ["_PewterCityYoungsterGoTakeOnBrockText"] = "Wenn Du genug\nMumm hast, dann\vversuche Dich an\vROCKO!",
  ["_PewterCityYoungsterYoureATrainerFollowMeText"] = "Du bist Trainer?\nROCKO ist ständig\vauf der Suche\vnach neuen\vHerausforderern!\vFolge mir!",
  ["_PewterGymBrockBoulderBadgeInfoText"] = "\fDas ist ein\noffizieller ORDEN\vder PKMN-LIGA!\fDie POKéMON\nder Person, die\vden ORDEN trägt,\vwerden stärker!\fVon nun an können\nDeine POKéMON\vjederzeit BLITZ\veinsetzen!",
  ["_PewterGymBrockPostBattleAdviceText"] = "Es gibt die\nverschiedensten\vTrainer auf der\vWelt!\fManche trainieren \nPOKéMON für\vKämpfe, andere\vhalten sie als\vKuscheltiere.\fIch aber möchte\nPOKéMON-Züchter\vwerden.\fWenn Du ein\nernsthafter\vPOKéMON-TRAINER\vwerden willst,\vdann teste Dein\vKönnen in der\vPKMN-ARENA von\vAZURIA CITY!",
  ["_PewterGymBrockPreBattleText"] = "Ich bin der\nARENALEITER von\vMARMORIA CITY,\vROCKO!\fMeine Devise ist\neine steinharte\vVerteidigung und\vfelsenfeste\vEntschlossenheit!\fDeshalb\ntrainiere ich\vSTEIN-POKéMON!\fWillst Du es noch\nimmer mit mir\vaufnehmen? OK!\vZeige mir, wie\vgut Du bist!",
  ["_PewterGymBrockReceivedBoulderBadgeText"] = "Ich habe\nDich falsch\veingeschätzt!\fNimm den\nFELSORDEN als\vZeichen meiner\vEhrerbietung!\f{PLAYER} erhält\nden FELSORDEN!",
  ["_PewterGymBrockWaitTakeThisText"] = "Es gibt die\nverschiedensten\vTrainer auf der\vWelt!\fDu scheinst ein\nsehr begabter\vPOKéMON-TRAINER\vzu sein!\fGehe in die\nPKMN-ARENA von\vAZURIA CITY und\vteste dort Dein\vKönnen!",
  ["_PewterGymCooltrainerMAfterBattleText"] = "Du bist ganz gut,\naber nicht so\vgut wie ROCKO!",
  ["_PewterGymCooltrainerMBattleText"] = "Bleib stehen wo\nDu bist, Kleiner!\fEs dauert noch\nLichtjahre, bis\vDu gegen ROCKO\vantreten kannst!",
  ["_PewterGymCooltrainerMEndBattleText"] = "Mist!\fLichtjahre messen\ndie Entfernung,\vnicht die Zeit!",
  ["_PewterGymGuideAdviceText"] = "Das POKéMON an\nder Spitze der\vPOKéMON-LISTE\vkämpft als\vErstes!\fWenn Du die\nReihenfolge der\vPOKéMON änderst,\vkönnten Kämpfe\vleichter werden!",
  ["_PewterGymGuideBeginAdviceText"] = "Alles klar! Dann\nkann es losgehen!",
  ["_PewterGymGuideFreeServiceText"] = "Der Tip ist\nkostenlos! Laß\vuns anfangen!",
  ["_PewterGymGuidePostBattleText"] = "Ganz wie ich es\nmir gedacht habe! \vAus Dir kann ein\vPOKéMON-CHAMPION\vwerden!",
  ["_PewterGymGuidePreAdviceText"] = "Hallo! Sieht aus,\nals hättest Du\vdas Zeug zu einem\vPOKéMON-CHAMPION!\fIch bin kein\nTrainer, aber ich\vkann Dir ein paar\vTips geben!\fLaß mich Dir den\nWeg zum Erfolg\vzeigen!",
  ["_PewterGymGuyText"] = "Alles klar! Laß\nuns beginnen!\fDein PIKACHU wird\nes hier nicht\vleicht haben!\fElektro-Attacken\nkönnen ROCKOS\vBODEN-POKéMON\vnichts anhaben.",
  ["_PewterGymReceivedTM34Text"] = "{PLAYER} erhält\nTM34!",
  ["_PewterGymTM34NoRoomText"] = "Du hast momentan\nkeinen Platz für\vweitere Items!",
  ["_PewterMartSuperNerdText"] = "Wenn man seine\nPOKéMON eifrig\vtrainiert, können\vselbst schwächere\vPOKéMON für\vÜberraschungen\vgut sein!",
  ["_PewterMartYoungsterText"] = "Ein zwielichtiger\nalter Mann hat\vmir dieses\vseltsame POKéMON\vangedreht!\fEs ist vollkommen\nschwach und hat\v¥500 gekostet!",
  ["_PewterNidoranHouseLittleBoyText"] = "NIDORAN, sitz!",
  ["_PewterNidoranHouseMiddleAgedManText"] = "Unser POKéMON ist\nein Außenseiter,\vdeshalb ist es\vschwer zu\verziehen!\fEin Außenseiter\nist ein POKéMON,\vdas man in einem\vTausch erhält.\fEs entwickelt\nsich rasch, doch\vim Kampf kann es\vvorkommen, daß es\vunerfahrenen\vTrainern nicht\vgehorcht!\fWenn wir doch nur\nein paar ORDEN\vhätten...",
  ["_PewterNidoranHouseNidoranText"] = "NIDORAN: Nidoran!",
  ["_PewterPokecenterGentlemanText"] = "Was!?\fTEAM ROCKET\nbefindet sich auf\vdem MONDBERG?\vDas muß ich\vsofort melden!\fVerschwinde!",
  ["_PewterPokecenterJigglypuffText"] = "PUMMELUFF: Puu!\nPu-uuu-ummeluff!",
  ["_PewterPokecenterText3"] = "POKéMON-CENTER\nsind echt klasse!\fDort können sie\nDeine POKéMON\vkomplett heilen!\fSie können sogar\nschwerwiegendere\vDinge, wie etwa\vVergiftungen,\vheilen.",
  ["_PewterSpeechHouseGamblerText"] = "Mit wachsender\nErfahrung lernen\vPOKéMON neue\vAttacken!\fManche Attacken\nkann ihnen jedoch\vnur ein Trainer\vbeibringen!",
  ["_PewterSpeechHouseYoungsterText"] = "POKéMON sind\neinfacher zu\vfangen, wenn sie\vverletzt sind\voder schlafen!\fTrotzdem\ngibt es keine\vErfolgsgarantie!",
  ["_PickUpPayDayMoneyText"] = "{PLAYER} sammelt\n¥{NUM:wTotalPayDayMoney, 3 | LEADING_ZEROES | LEFT_ALIGN} auf!",
  ["_PidgeotDexEntry"] = "Dieses POKéMON\nkann bis zu Mach 2\nschnell fliegen.\fSeine Klauen\ndienen ihm als\nexzellente Waffen.",
  ["_PidgeottoDexEntry"] = "Dieses kraftvolle\nPOKéMON wacht\nunermüdlich über\fsein Territorium\nund sucht ständig\nnach Beute.",
  ["_PidgeyDexEntry"] = "Ein sanftmütiges\nPOKéMON, welches\nlieber Sand zum\fSchutze auf-\nwirbelt, als\nzurückzuschlagen.",
  ["_PikachuDexEntry"] = "Der Schweif dieses\nPOKéMON dient als\nFrühwarnsystem.\fZieht man PIKACHU\nam Schweif, so\nbeißt es um sich.",
  ["_PikachuUnhappyText"] = "{RAM:wNameBuffer} sieht\nunglücklich aus!",
  ["_PinsirDexEntry"] = "Dieses POKéMON\nbevorzugt einen\nwarmen Lebensraum.\fPINSIR attackiert\nGegner mit seiner\nriesigen Schere.",
  ["_PlaySlotMachineText"] = "Ein einarmiger\nBandit! Möchtest\vDu spielen?",
  ["_PlayedFluteHadEffectText"] = "{PLAYER} spielt\ndie POKéFLÖTE.",
  ["_PlayedFluteNoEffectText"] = "Die POKéFLÖTE\nwurde gespielt!\fEine schöne\nMelodie!",
  ["_PlayerBlackedOutText"] = "{PLAYER} hat keine\neinsatzbereiten\vPOKéMON mehr!\f{PLAYER} fällt\nin Ohnmacht!",
  ["_PlayerBlackedOutText2"] = "Alle POKéMON von\n{PLAYER} wurden\vbesiegt!\f{PLAYER} fällt\nin Ohnmacht!",
  ["_PlayerMon1Text"] = "{RAM:wBattleMonNick}!",
  ["_PlayerMon2Text"] = "{RAM:wBattleMonNick} ",
  ["_PlayerMonFaintedText"] = "{RAM:wBattleMonNick}\nwurde besiegt!",
  ["_PoisonedText"] = "{TARGET}\nwurde vergiftet!",
  ["_PokeCenterSignText"] = "Erfrische Deine\nPOKéMON! \fPKMN-CENTER",
  ["_PokemartAnythingElseText"] = "Kann ich sonst\nirgendwie helfen?",
  ["_PokemartBoughtItemText"] = "Hier, bitte sehr!\nVielen Dank!",
  ["_PokemartBuyingGreetingText"] = "Schau Dich in\nRuhe um.",
  ["_PokemartGreetingText"] = "Hallo!\nKann ich Dir\vbehilflich sein?",
  ["_PokemartItemBagEmptyText"] = "Du hast nichts,\nwas Du verkaufen\vkönntest!",
  ["_PokemartItemBagFullText"] = "Du kannst keine\nweiteren Items\vmehr tragen.",
  ["_PokemartNotEnoughMoneyText"] = "Du hast nicht\ngenug Geld.",
  ["_PokemartTellBuyPriceText"] = "{RAM:wStringBuffer}?\nDas macht dann\v¥{NUM:hMoney, 3 | LEADING_ZEROES | LEFT_ALIGN}! OK?",
  ["_PokemartTellSellPriceText"] = "Ich gebe Dir\n¥{NUM:hMoney, 3 | LEADING_ZEROES | LEFT_ALIGN} dafür.",
  ["_PokemartThankYouText"] = "Vielen Dank!",
  ["_PokemartUnsellableItemText"] = "Das kann ich\nnicht gebrauchen.",
  ["_PokemonBooksText"] = "Wow! Unmengen\nBücher über\vPOKéMON!",
  ["_PokemonCenterFarewellText"] = "Komm jederzeit\nwieder vorbei!",
  ["_PokemonCenterWelcomeText"] = "Willkommen im\nPKMN-CENTER!\fWir heilen Deine\nPOKéMON und\vmachen sie wieder\vfit!",
  ["_PokemonFaintedText"] = "{RAM:wNameBuffer}\nwurde besiegt!",
  ["_PokemonFanClubBagFullText"] = "Du hast keinen\nPlatz für weitere\vItems!",
  ["_PokemonFanClubChairFinalText"] = "Hallo, {PLAYER}!\fSoll ich Dir von\nmeinen POKéMON\verzählen?\fNein? Schade!",
  ["_PokemonFanClubChairmanIntroText"] = "Ich bin der\nVorsitzende des\vPOKéMON-FANCLUBS!\fIch habe mehr als\n100 POKéMON\vgefangen!\fIch bin sehr\nkleinlich, wenn\ves um POKéMON\vgeht!\fAlso...\fBist Du\nhergekommen, um\vetwas über meine\vPOKéMON zu hören?",
  ["_PokemonFanClubChairmanStoryText"] = "Sehr schön!\nDann hör mir zu!\fAm liebsten mag\nich GALLOPA!\fEs ist... süß...\nschön... klug...\vund... aufregend!\vStimmst Du mir\vzu? Es... ist...\vmajestätisch...\vfreundlich...\vIch liebe es!\fWenn... es...\nschläft... warm\vund kuschelig...\vspektakulär...\vhinreißend...\vUps! Wie die\vZeit vergeht! Ich\vhalte Dich auf!\fDanke, daß Du mir\nzugehört hast!\vNimm dieses\vGeschenk von mir!",
  ["_PokemonFanClubClefairyFanBetterText"] = "Hmpf! Mein PIEPI\nist viel süßer\vals ihr POKéMON!",
  ["_PokemonFanClubClefairyFanNormalText"] = "Hat mein Piepi\nnicht einen\vwunderschönen\vSchweif?",
  ["_PokemonFanClubClefairyFanText"] = "Der Vorsitzende\nredet sehr gerne\vüber POKéMON!",
  ["_PokemonFanClubClefairyText"] = "PIEPI: Piepi!",
  ["_PokemonFanClubExplainBikeVoucherText"] = "\fDu erhältst dafür\nein FAHRRAD!\fSorge Dich nicht\num mich, ich kann\vmit meinem IBITAK\vFLIEGEN!\fIch brauche also\nkein FAHRRAD!\fIch hoffe, Du\nfährst gerne Rad!",
  ["_PokemonFanClubNoStoryText"] = "Oh. Komm wieder\nvorbei, wenn ich\vDir etwas\verzählen soll!",
  ["_PokemonFanClubReceivedBikeVoucherText"] = "{PLAYER} erhält\neinen {RAM:wStringBuffer}!",
  ["_PokemonFanClubReceptionistText"] = "Der Vorsitzende\nredet sehr gerne\vüber POKéMON!",
  ["_PokemonFanClubSeelFanBetterText"] = "Du meine Güte!\fMein JUROB ist\nviel hübscher!",
  ["_PokemonFanClubSeelFanNormalText"] = "Ich liebe mein\nJUROB!\fEs quiekt, wenn\nich es in den\vArm nehme!",
  ["_PokemonFanClubSeelFanText"] = "Ich werde\nden Drucker\vanschließen und\vein FOTO von\vJUROB ausdrucken!",
  ["_PokemonFanClubSeelText"] = "JUROB: Juuurob!",
  ["_PokemonFightingFitText"] = "Danke! Deine\nPOKéMON sind\vwieder topfit!",
  ["_PokemonMansion1FScientistAfterBattleText"] = "Ein Schlüssel?\nKeine Ahnung,\vwovon Du redest!",
  ["_PokemonMansion1FScientistBattleText"] = "Wer bist Du?\nHier hat niemand\vetwas zu suchen!",
  ["_PokemonMansion1FScientistEndBattleText"] = "Autsch!",
  ["_PokemonMansion1FSwitchNotPressedText"] = "Lieber nicht!",
  ["_PokemonMansion1FSwitchPressedText"] = "Wer würde es\nnicht tun?",
  ["_PokemonMansion1FSwitchText"] = "Ein versteckter\nSchalter!\fSchalter drücken?",
  ["_PokemonMansion2FDiary1Text"] = "TAGEBUCH:\n5. JULI\vDer Dschungel\vim Niemandsland.\fWir haben tief\nim Dschungel ein\vvöllig neues\vPOKéMON gefunden.",
  ["_PokemonMansion2FDiary2Text"] = "TAGEBUCH: \n10. JULI\fWir nennen das\nneuentdeckte\vPOKéMON MEW.",
  ["_PokemonMansion2FSuperNerdAfterBattleText"] = "Die Türen kannst\nDu mittels\vSchalter\vschließen oder\vöffnen!",
  ["_PokemonMansion2FSuperNerdBattleText"] = "Ich finde keinen\nWeg nach draußen!\vDer reinste\vIrrgarten!",
  ["_PokemonMansion2FSuperNerdEndBattleText"] = "Oh nein!\nMeine Beute!",
  ["_PokemonMansion2FSwitchNotPressedText"] = "Lieber nicht!",
  ["_PokemonMansion2FSwitchPressedText"] = "Wer würde es\nnicht tun?",
  ["_PokemonMansion2FSwitchText"] = "Ein versteckter\nSchalter!\fSchalter drücken?",
  ["_PokemonMansion3FDiaryText"] = "TAGEBUCH:\n6. FEBRUAR\fMEW hat ein\nJunges geboren!\fWir haben es\nMEWTU genannt.",
  ["_PokemonMansion3FScientistAfterBattleText"] = "Du kommst nicht\nweiter? Spring\veinfach da drüben\vherunter!",
  ["_PokemonMansion3FScientistBattleText"] = "Mein Mentor lebte\neinst hier...",
  ["_PokemonMansion3FScientistEndBattleText"] = "Wow!\nUnglaublich!",
  ["_PokemonMansion3FSuperNerdAfterBattleText"] = "Ich frage mich,\nwo mein Partner\vwieder steckt!!!",
  ["_PokemonMansion3FSuperNerdBattleText"] = "Dieser Ort hier\nist riesig!",
  ["_PokemonMansion3FSuperNerdEndBattleText"] = "Ayah!",
  ["_PokemonMansionB1FBurglarAfterBattleText"] = "Hier liegt viel\nnützliches Zeug\vherum!",
  ["_PokemonMansionB1FBurglarBattleText"] = "Wo bin ich hier\ngelandet?",
  ["_PokemonMansionB1FBurglarEndBattleText"] = "Autsch!",
  ["_PokemonMansionB1FDiaryText"] = "TAGEBUCH:\n1. SEPTEMBER\fMEWTU wird immer\nstärker.\fWir konnten die\nunkontrollierten\vWutausbrüche\vnicht eindämmen!",
  ["_PokemonMansionB1FScientistAfterBattleText"] = "Hier gefällt es\nmir! Man kann\vprima forschen!",
  ["_PokemonMansionB1FScientistBattleText"] = "Hier wäre der\nideale Platz für\vein Labor!",
  ["_PokemonMansionB1FScientistEndBattleText"] = "Was\nhabe ich nur\vfalsch gemacht?",
  ["_PokemonSellingGreetingText"] = "Was möchtest Du\nverkaufen?",
  ["_PokemonStuffText"] = "Wow! Jede Menge\nPOKéMON-\vGegenstände!",
  ["_PokemonText"] = "POKéMON!",
  ["_PokemonTower1FBaldingGuyText"] = "Ich bete für\nPIEPI...\fSchluchz!\nIch kann nicht\vaufhören zu\vweinen...",
  ["_PokemonTower1FChannelerText"] = "Ich bin eine\nEXORZISTIN!\vDie Geister hier\vstiften Unruhe!",
  ["_PokemonTower1FGirlText"] = "FUKANO...\nWarum hast Du\vmich verlassen?",
  ["_PokemonTower1FMiddleAgedWomanText"] = "Bist Du hier, um\nDein Mitgefühl\vauszudrücken? \vSei gesegnet!",
  ["_PokemonTower1FReceptionistText"] = "Der POKéMON-TURM\nwurde im Andenken\van verblichene\vPOKéMON\verrichtet.",
  ["_PokemonTower2FChannelerText"] = "Selbst wir können\ndie eigenwilligen\vGEISTER nicht\videntifizieren!\fMan benötigt das\nSILPH SCOPE, um\vsie zu erkennen!",
  ["_PokemonTower2FRivalDefeatedText"] = "Was?\nDu bist eine\vharte Nuß!\fIch bin es wohl\netwas zu locker\vangegangen!",
  ["_PokemonTower2FRivalHowsYourDexText"] = "Wie macht sich\nDein POKéDEX,\vKumpel? Ich habe\vkürzlich ein\vTRAGOSSO\vgefangen!\fAllerdings habe\nich noch kein\vKNOGGA!\fIch glaube, von\ndiesen POKéMON\vgibt es nur noch\vwenige. Also, ich\vhabe viel zu tun!\vIch muß weiter!\fBis später!",
  ["_PokemonTower2FRivalVictoryText"] = "{RIVAL}: Deine\nPOKéMON sind\vnicht in Form!\fTrainiere sie ein\nbißchen härter!",
  ["_PokemonTower2FRivalWhatBringsYouHereText"] = "{RIVAL}:\nHallo, {PLAYER}!\vWas machst Du\vdenn hier? Deine\vPOKéMON scheinen\vganz gut in Form\vzu sein!\fNaja, nach dem\nKampf wird das\vanders aussehen!",
  ["_PokemonTower3FChanneler1AfterBattleText"] = "Das SILPH SCOPE\nkann GEISTER\videntifizieren!",
  ["_PokemonTower3FChanneler1BattleText"] = "Buu... Huhu...\nHuhu... Buu..",
  ["_PokemonTower3FChanneler1EndBattleText"] = "Buu!\nIch wurde erlöst!",
  ["_PokemonTower3FChanneler2AfterBattleText"] = "Tut mir leid!\nIch war besessen!",
  ["_PokemonTower3FChanneler2BattleText"] = "Buhuhuhu...\nHui... Buuh!",
  ["_PokemonTower3FChanneler2EndBattleText"] = "Hmm?\nWas mache ich\vhier?",
  ["_PokemonTower3FChanneler3AfterBattleText"] = "Auch meine\nFreunde waren\vbesessen!",
  ["_PokemonTower3FChanneler3BattleText"] = "Verschwinde,\nböser Geist!",
  ["_PokemonTower3FChanneler3EndBattleText"] = "Puh!\nDer Geist ist\vverschwunden!",
  ["_PokemonTower4FChanneler1AfterBattleText"] = "Ich bin sicher,\nich träume das\valles nur...",
  ["_PokemonTower4FChanneler1BattleText"] = "Ein GEIST! Nein!\nAhhhhh!",
  ["_PokemonTower4FChanneler1EndBattleText"] = "Wohin\nist der GEIST\vgegangen?",
  ["_PokemonTower4FChanneler2AfterBattleText"] = "Wir können die\nIdentität der\vGEISTER nicht\vermitteln!",
  ["_PokemonTower4FChanneler2BattleText"] = "Ich verfluche\nDich! Buuuh!",
  ["_PokemonTower4FChanneler2EndBattleText"] = "Was\nist passiert?",
  ["_PokemonTower4FChanneler3AfterBattleText"] = "Mögen die\nverlorenen Seelen\vder POKéMON in\vFrieden ruhen...",
  ["_PokemonTower4FChanneler3BattleText"] = "Buuh... Buhuhu...\nLaß mich in Ruhe!",
  ["_PokemonTower4FChanneler3EndBattleText"] = "Wer?\nWas? Wo?",
  ["_PokemonTower5FChanneler1Text"] = "Komm her, mein\nJunge! Ich habe\vdiese Stelle mit\vweißer Magie\vversiegelt!\fDu kannst Dich\nhier ausruhen!",
  ["_PokemonTower5FChanneler2AfterBattleText"] = "Etwas muß von mir\nBesitz ergriffen\vhaben!",
  ["_PokemonTower5FChanneler2BattleText"] = "Gib... mir...\nDeine... Seele...",
  ["_PokemonTower5FChanneler2EndBattleText"] = "Puh!",
  ["_PokemonTower5FChanneler3AfterBattleText"] = "Ich war verhext!",
  ["_PokemonTower5FChanneler3BattleText"] = "Es... gibt...\nkein...\vEntkommen...",
  ["_PokemonTower5FChanneler3EndBattleText"] = "Welch\nein Alptraum!",
  ["_PokemonTower5FChanneler4AfterBattleText"] = "So langsam komme\nich wieder zu\vSinnen!",
  ["_PokemonTower5FChanneler4BattleText"] = "Zombies!",
  ["_PokemonTower5FChanneler4EndBattleText"] = "Was?",
  ["_PokemonTower5FChanneler5AfterBattleText"] = "Trotz meiner\nErfahrung bin\vich dem Bösen\vverfallen!",
  ["_PokemonTower5FChanneler5BattleText"] = "Buuh...\nBuhuhu...",
  ["_PokemonTower5FChanneler5EndBattleText"] = "Das\nwar knapp!",
  ["_PokemonTower5FPurifiedZoneText"] = "Du hast einen\ngeschützten\vBereich betreten!\f{PLAYER}s POKéMON\nwurden geheilt!",
  ["_PokemonTower6FBeGoneText"] = "Verschwindet...\nEindringlinge...",
  ["_PokemonTower6FChanneler1AfterBattleText"] = "Ich fühle mich\nso blutleer und\vschwach...",
  ["_PokemonTower6FChanneler1BattleText"] = "Ich... brauche...\nBlut...",
  ["_PokemonTower6FChanneler1EndBattleText"] = "\nWo bin ich?",
  ["_PokemonTower6FChanneler2AfterBattleText"] = "Es war ein böser\nGeist, der Besitz\vvon mir ergriffen\vhatte!",
  ["_PokemonTower6FChanneler2BattleText"] = "Buuh... Buhuhu!",
  ["_PokemonTower6FChanneler2EndBattleText"] = "\nIrgend etwas hat\vmich verlassen!",
  ["_PokemonTower6FChanneler3AfterBattleText"] = "Was geht hier\nvor?",
  ["_PokemonTower6FChanneler3BattleText"] = "Buh...\nBuh... Buhuhu...",
  ["_PokemonTower6FChanneler3EndBattleText"] = "Buuh!",
  ["_PokemonTower6FGhostWasCubonesMotherText"] = "Der GEIST war die\nrastlose Seele\vvon TRAGOSSOS\vMutter!",
  ["_PokemonTower6FSoulWasCalmedText"] = "Ihre Seele hat\nFrieden gefunden.\fSie ist in\ndas Jenseits\veingekehrt...",
  ["_PokemonTower7FMrFujiRescueText"] = "MR. FUJI: Was? Du\nkommst, um mich\vzu retten?\fVielen Dank!\nAber ich bin\vfreiwillig hier.\fIch kam her, um\ndie umherirrende\vSeele von\vTRAGOSSOS Mutter\vzu beruhigen!\fKNOGGAS Seele\nkann nun endlich\vin Frieden in die\vewigen Jagdgründe \veinkehren.\fTrotzdem danke\nich Dir für Deine\vSorge um mich!\fFolge mir in das\nPKMN-CLUBHAUS am\vFuße des Turms.",
  ["_PokemonTowerJessieJamesText1"] = "Bleib stehen!",
  ["_PokemonTowerJessieJamesText2"] = "Der alte Knacker\nwollte sich\vbeschweren!\vDa mußten wir\vihm die Leviten\vlesen!\fUnd jetzt mach\nDich vom Acker!\vOder Du bekommst\v'ne Menge Ärger!",
  ["_PokemonTowerJessieJamesText3"] = "Dafür\nwirst Du büßen!",
  ["_PokemonTowerJessieJamesText4"] = "TEAM ROCKET - so\nschnell wie das\vLicht...",
  ["_PoliwagDexEntry"] = "Dieses POKéMON\nkann sehr schlecht\nlaufen. Sein\fBauchmuster ist\nunterschiedlich,\nje nach Region.",
  ["_PoliwhirlDexEntry"] = "Das Spiralmuster\nauf QUAPUTZIs\nBauch hypnotisiert\fim Kampf Gegner\nund ermöglicht\nihm so die Flucht.",
  ["_PoliwrathDexEntry"] = "Dieses POKéMON\nist ein meister-\nhafter Schwimmer.\fSeine Techniken\nschlagen selbst\nOlympiasieger.",
  ["_PonytaDexEntry"] = "Dieses POKéMON\nkann unglaublich\nhoch springen.\fEs absorbiert die\nWucht der Landung\nmit seinen Hufen.",
  ["_PoofText"] = "schwupp!",
  ["_PorygonDexEntry"] = "PORYGON kann\nangeblich in den\nWeltraum fliegen.\fBislang ist dies\naber noch keinem\nExemplar gelungen.",
  ["_PotionText"] = "{RAM:wNameBuffer} erhält\n{NUM:wHPBarHPDifference, 2, 3} Kraftpunkte!",
  ["_PowerPlantVoltorbBattleText"] = "Bzzz!",
  ["_PowerPlantZapdosBattleText"] = "Zapdos!",
  ["_PrimeapeDexEntry"] = "In ganz seltenen\nFällen beruhigt\nsich dieses sehr\fjähzornige POKéMON\nund ist für einen\nMoment friedlich.",
  ["_PsyduckDexEntry"] = "Dieses POKéMON\nplagen chronische\nKopfschmerzen.\fEs verfügt über\nPSI-Kräfte, die es\nselten einsetzt.",
  ["_PushStartText"] = "Drücke START,\num das MENÜ\vaufzurufen!",
  ["_RaichuDexEntry"] = "Dieses lebhafte \nPOKéMON erzeugt\nin seinem Körper\fElektrizität.\nEs leuchtet auch\nim Dunkeln.",
  ["_RaisePPWhichTechniqueText"] = "Für welche\nAttacke sollen\vdie AP erhöht\vwerden?",
  ["_RanAwayScaredText"] = "{TARGET}\nläuft davon!",
  ["_RanFromBattleText"] = "{USER}\nist geflohen!",
  ["_RapidashDexEntry"] = "Dieses POKéMON\nkann schnell wie\nder Blitz laufen.\fEs verfolgt alle\nObjekte, die sich\nschnell bewegen.",
  ["_RareCandyText"] = "{RAM:wNameBuffer}\nerreicht\v{NUM:wCurEnemyLevel, 1, 3}!",
  ["_RaticateDexEntry"] = "Die Hinterbeine\ndieses POKéMON\nverfügen über\fSchwimmhäute.\nSo kann es in\nFlüssen jagen.",
  ["_RattataDexEntry"] = "Dieses POKéMON\nnagt alles und\njeden an. Es\flebt in großen\nRudeln von bis zu\nvierzig POKéMON.",
  ["_RedBedroomSNESText"] = "{PLAYER} spielt\nSUPER NINTENDO!\v...OK! Die Reise\vkann beginnen!",
  ["_RedsHouse1FMomLookingGreatText"] = "MUTTER: Sehr gut!\nDu und Deine\vPOKéMON sehen\vgroßartig aus!\vAchte auf Dich!",
  ["_RedsHouse1FMomWakeUpText"] = "MUTTER: Richtig.\nIrgendwann gehen\valle Jungen fort,\vum ein Abenteuer\vzu erleben!\fPROF. EICH von\nnebenan hat nach\vDir gefragt.",
  ["_RedsHouse1FMomYouShouldRestText"] = "MUTTER: {PLAYER}!\nWenn Du zu hart\vzu Deinen POKéMON\vbist, werden sie\vnicht zutraulich!\fDu solltest eine\nkurze Pause\veinlegen.",
  ["_RedsHouse1FTVStandByMeMovieText"] = "Im Fernsehen\nläuft ein Film.\vVier Jungen\vlaufen ein\vBahngleis\ventlang!\fDen Film kenne\nich schon! Ich\vmache mich besser\vauf den Weg!",
  ["_RedsHouse1FTVWrongSideText"] = "Ups,\nfalsche Richtung!",
  ["_ReflectGainedArmorText"] = "{USER}\nerhält Panzer!",
  ["_RefusingText"] = "{RAM:wNameBuffer}\nweigert sich!",
  ["_RegainedHealthText"] = "{USER}\nerholt sich!",
  ["_ReleaseWhichMonText"] = "Welches POKéMON\nsoll freigelassen\vwerden?",
  ["_RepelWoreOffText"] = "Der SCHUTZ wirkt\nnicht mehr.",
  ["_RequireCoinCaseText"] = "Du benötigst\neinen MÜNZKORB!",
  ["_RestorePPWhichTechniqueText"] = "Für welche\nAttacke sollen\vdie AP erneuert\vwerden?",
  ["_ReviveText"] = "{RAM:wNameBuffer}\nist wieder fit!",
  ["_RhydonDexEntry"] = "Dieses POKéMON\nläuft auf seinen\nHinterbeinen.\fSeine stahlharte\nHaut widersteht\nsogar heißer Lava.",
  ["_RhyhornDexEntry"] = "RIHORN steigert\nsich so in einen\nKampf hinein,\fdaß es kämpft\nbis es ermattet\neinschläft.",
  ["_Rival1WinText"] = "{RIVAL}: Ja! Ich\nbin der Beste!",
  ["_RivalDefeatedText"] = "NEIN!\nDas kann nicht\vwahr sein! Meine\vbesten POKéMON\vsind geschlagen!\fMein Siegeszug\nist schon vorbei?\fNach all den\nAnstrengungen,\vLIGA-CHAMPION\vzu werden?\fDas ist nicht\nfair!",
  ["_RivalVictoryText"] = "Haha! Ich\nhabe GEWONNEN!\fIch bin einfach \nzu gut für Dich, \v{PLAYER}!\fImmerhin hast\nDu es bis hierher\vgeschafft! Ich\vhätte aber mehr\vvon Dir erwartet,\v{RIVAL}!\fVielleicht beim\nnächsten mal, Du\vKämpfer! Hahaha!",
  ["_RockTunnel1FCooltrainerF1AfterBattleText"] = "Ich habe hier im\nTunnel ein\vMASCHOCK gesehen!",
  ["_RockTunnel1FCooltrainerF1BattleText"] = "Huch! Komm mir\nim Dunkeln bloß\vnicht zu nahe!",
  ["_RockTunnel1FCooltrainerF1EndBattleText"] = "Es\nwar zu dunkel!",
  ["_RockTunnel1FCooltrainerF2AfterBattleText"] = "Dabei sahst Du so\nsüß und harmlos\vaus!",
  ["_RockTunnel1FCooltrainerF2BattleText"] = "Ich bin wegen der\nPOKéMON hierher\vgekommen!",
  ["_RockTunnel1FCooltrainerF2EndBattleText"] = "\nAlle meine\vPOKéMON wurden\vbesiegt!",
  ["_RockTunnel1FCooltrainerF3AfterBattleText"] = "Puh! Ich bin ganz\nnaßgeschwitzt!",
  ["_RockTunnel1FCooltrainerF3BattleText"] = "Du  besitzt\nPOKéMON!\vLaß uns kämpfen!",
  ["_RockTunnel1FCooltrainerF3EndBattleText"] = "\nDu bist ein\vharter Brocken!",
  ["_RockTunnel1FHiker1AfterBattleText"] = "Nimm Dich vor\nONIX in acht! Es\vquetscht Dich wie\veine Zitrone aus!",
  ["_RockTunnel1FHiker1BattleText"] = "Dieser Tunnel ist\nverdammt lang!",
  ["_RockTunnel1FHiker1EndBattleText"] = "Oha! Du\nhast gewonnen!",
  ["_RockTunnel1FHiker2AfterBattleText"] = "Diesen Umweg muß\nich nur wegen des\vauf der Route 12\vschlafenden\vPOKéMON machen.",
  ["_RockTunnel1FHiker2BattleText"] = "Könnte es sein,\ndaß ich mich\vverlaufen habe?",
  ["_RockTunnel1FHiker2EndBattleText"] = "Sachte!\nWo bin ich?\vWo geht es nach\vdraußen?",
  ["_RockTunnel1FHiker3AfterBattleText"] = "Du hast Talent!\nDu kannst kein\vMöchtegern sein!",
  ["_RockTunnel1FHiker3BattleText"] = "Ein Möchtegern\nwie Du sollte\vetwas mehr\vRespekt zeigen!",
  ["_RockTunnel1FHiker3EndBattleText"] = "\nIch gebe auf!",
  ["_RockTunnel1FSignText"] = "FELSTUNNEL\nAZURIA CITY -\vLAVANDIA",
  ["_RockTunnel1FSuperNerdAfterBattleText"] = "Unterwegs werde\nich mir ein ZUBAT\vfangen!",
  ["_RockTunnel1FSuperNerdBattleText"] = "Meine POKéMON\nwollen kämpfen!\vLos geht's!",
  ["_RockTunnel1FSuperNerdEndBattleText"] = "\nGAME OVER!",
  ["_RockTunnelB1FCooltrainerF1AfterBattleText"] = "Ich will nach\nHause!",
  ["_RockTunnelB1FCooltrainerF1BattleText"] = "Wanderer nehmen\nZweige, um ihren\vWeg zu markieren.",
  ["_RockTunnelB1FCooltrainerF1EndBattleText"] = "\nIch habe mein\vBestes gegeben!",
  ["_RockTunnelB1FCooltrainerF2AfterBattleText"] = "Ich mag nur\nkleine POKéMON,\vdie großen jagen\vmir Angst ein!",
  ["_RockTunnelB1FCooltrainerF2BattleText"] = "Ich komme nicht\noft hierher. Aber\vich will kämpfen!",
  ["_RockTunnelB1FCooltrainerF2EndBattleText"] = "Oh!\nIch hab verloren!",
  ["_RockTunnelB1FHiker1AfterBattleText"] = "Ich trainiere\nlieber meine\vMuskeln als\vmein Gehirn!!!",
  ["_RockTunnelB1FHiker1BattleText"] = "Haha! Kannst Du\nmich besiegen?",
  ["_RockTunnelB1FHiker1EndBattleText"] = "Hups!\nDas war zuviel\vdes Guten!",
  ["_RockTunnelB1FHiker2AfterBattleText"] = "In den Bergen\nfindet man viele\vSTEIN-POKéMON.",
  ["_RockTunnelB1FHiker2BattleText"] = "Mein POKéMON\nwird Dich das\vFürchten lehren!",
  ["_RockTunnelB1FHiker2EndBattleText"] = "\nIch gebe auf! Du\vbist besser!",
  ["_RockTunnelB1FHiker3AfterBattleText"] = "Ich werde mit\nmeinen POKéMON\vtrainieren!",
  ["_RockTunnelB1FHiker3BattleText"] = "Zeig mir, was Du\ndrauf hast!",
  ["_RockTunnelB1FHiker3EndBattleText"] = "Du\nbist gut!",
  ["_RockTunnelB1FSuperNerd1AfterBattleText"] = "Gibst Du mir den\nPOKéDEX, wenn\ver fertig ist?",
  ["_RockTunnelB1FSuperNerd1BattleText"] = "Du besitzt einen\nPOKéDEX? Cool!\fIch möchte auch\neinen haben!",
  ["_RockTunnelB1FSuperNerd1EndBattleText"] = "Ach,\nich bin ja so\vneidisch!!!",
  ["_RockTunnelB1FSuperNerd2AfterBattleText"] = "Spaßvögel\nverkleiden sich\vgerne als POKéMON.",
  ["_RockTunnelB1FSuperNerd2BattleText"] = "Möchtest Du etwas\nüber Spaßvögel\verfahren?",
  ["_RockTunnelB1FSuperNerd2EndBattleText"] = "\nSo weit, so gut.",
  ["_RockTunnelB1FSuperNerd3AfterBattleText"] = "Ich liebe die\nKunst,\vnicht den Kampf!",
  ["_RockTunnelB1FSuperNerd3BattleText"] = "Zuhause zeichne\nich gern POKéMON.",
  ["_RockTunnelB1FSuperNerd3EndBattleText"] = "Ich\nbin erschöpft!",
  ["_RockTunnelPokecenterFisherText"] = "Ich habe für\nein nutzloses\vNUGGET 5000¥\vbekommen!",
  ["_RockTunnelPokecenterGentlemanText"] = "Ihr Element macht\nmanche POKéMON\vanderen gegenüber\vstärker bzw.\vschwächer!",
  ["_RockTunnelPokecenterGuyText"] = "Ich habe gehört,\ndaß in LAVANDIA\vböse GEISTER\vspuken!",
  ["_RocketHide3AfterBattleText3"] = "Geh ruhig weiter!\nDu benötigst den\vLIFTÖFFNER, und\vder fehlt Dir!",
  ["_RocketHideout3BattleText"] = "Wir hörten schon,\ndaß Du im\vAnmarsch bist!",
  ["_RocketHideout3EndBattleText3"] = "Was?\nVerloren?",
  ["_RocketHideoutB1FRocket1AfterBattleText"] = "Willst Du Dich\nmit TEAM ROCKET\vanlegen?",
  ["_RocketHideoutB1FRocket1BattleText"] = "Wie kommst Du\nhierher, Kleiner?",
  ["_RocketHideoutB1FRocket1EndBattleText"] = "Ah!\nGeschlagen!",
  ["_RocketHideoutB1FRocket2AfterBattleText"] = "Unsere Rache\nwird grauenvoll,\vDu Lausebengel!",
  ["_RocketHideoutB1FRocket2BattleText"] = "Du hast Mut, hier\nhereinzuplatzen!",
  ["_RocketHideoutB1FRocket2EndBattleText"] = "\nMist! Versagt!",
  ["_RocketHideoutB1FRocket3AfterBattleText"] = "SILPH SCOPE?\nIch weiß nicht,\vwovon Du redest!",
  ["_RocketHideoutB1FRocket3BattleText"] = "Alarm!\nEindringlinge!",
  ["_RocketHideoutB1FRocket3EndBattleText"] = "Ich\nkonnte ihn nicht\vstoppen!!!",
  ["_RocketHideoutB1FRocket4AfterBattleText"] = "OK, OK, ich packe\naus! Nimm den\vAufzug zum BOSS!",
  ["_RocketHideoutB1FRocket4BattleText"] = "Was hast Du hier\nverloren?",
  ["_RocketHideoutB1FRocket4EndBattleText"] = "Das\nkann nicht sein!",
  ["_RocketHideoutB1FRocket5AfterBattleText"] = "Ups, die Tür ist\naufgegangen!",
  ["_RocketHideoutB1FRocket5BattleText"] = "Was hast Du\nhier verloren?",
  ["_RocketHideoutB1FRocket5EndBattleText"] = "\nWas ist passiert?",
  ["_RocketHideoutB2FRocketAfterBattleText"] = "Das TEAM ROCKET-\nHauptquartier hat\v4 Untergeschosse.\vDu findest den\vBOSS niemals!!!",
  ["_RocketHideoutB2FRocketBattleText"] = "Der BOSS sagt,\ndas SILPH SCOPE\vmacht Geister\vsichtbar!",
  ["_RocketHideoutB2FRocketEndBattleText"] = "\nIch ergebe mich!",
  ["_RocketHideoutB3FRocket1AfterBattleText"] = "Das SILPH SCOPE?\nDas Gerät, das\vder BOSS geraubt\vhat? Das ist hier\virgendwo...",
  ["_RocketHideoutB3FRocket1BattleText"] = "Halte Dich aus\nTEAM ROCKETS\vAngelegenheiten!",
  ["_RocketHideoutB3FRocket1EndBattleText"] = "Uff!\nIch bin am Boden!",
  ["_RocketHideoutB4FGiovanniHopeWeMeetAgainText"] = "Offensichtlich\ntrainierst Du\vDeine POKéMON\vsehr sorgfältig!\fTrotzdem würdest\nDu meine Ziele\vund Beweggründe\vnie verstehen...\fDieses Mal lasse\nich Dich noch von\vdannen ziehen...\fDoch wir werden\nuns wiedersehen!",
  ["_RocketHideoutB4FGiovanniImpressedYouGotHereText"] = "Ich bin schwer\nbeeindruckt. Du\vbist tatsächlich\vweit gekommen!\fTEAM ROCKET\nfinanziert mit\vPOKéMON seine\vfinsteren Pläne!\fIch bin hier der\nBoss, GIOVANNI!\fMach Dich bereit,\nHöllenqualen zu\verleiden, Wicht!",
  ["_RocketHideoutB4FGiovanniWhatCannotBeText"] = "NEIN!\nIch habe kläglich\vversagt!",
  ["_RocketHideoutB4FRocketAfterBattleText"] = "Mist! Ich habe\nden LIFTÖFFNER\vverloren!",
  ["_RocketHideoutB4FRocketBattleText"] = "Ich werde Dir\nden LIFTÖFFNER\vniemals geben!",
  ["_RocketHideoutB4FRocketEndBattleText"] = "\nOh nein!",
  ["_RocketHideoutElevatorAppearsToNeedKeyText"] = "Hmm, hier\nbraucht man einen\vSchlüssel!",
  ["_RocketHideoutJessieJamesText1"] = "Keinen Schritt\nweiter!",
  ["_RocketHideoutJessieJamesText2"] = "Du hast uns am\nMONDBERG ganz\vschön gedemütigt!\fAber Rache ist\nsüß, Du Rotznase!",
  ["_RocketHideoutJessieJamesText3"] = "So\nein Hohlkopf!",
  ["_RocketHideoutJessieJamesText4"] = "TEAM ROCKET,\nschnell wie das\vLicht...",
  ["_RoseText"] = "nimmt zu!",
  ["_Route10CooltrainerF1AfterBattleText"] = "Ich habe einige\nPOKéMANIACS\vin dieser Gegend\vgesehen.",
  ["_Route10CooltrainerF1BattleText"] = "Jedes Mal, wenn\nich in einer\vPKMN-ARENA\vgekämpft habe, \vwurde ich\vbesiegt!",
  ["_Route10CooltrainerF1EndBattleText"] = "\nNein! Nicht\vschon wieder!",
  ["_Route10CooltrainerF2AfterBattleText"] = "Viele POKéMON\nin dieser Gegend\vsind grob!\fIch wünschte,\neines wäre rosa\vund trüge ein\vBlumenmuster!",
  ["_Route10CooltrainerF2BattleText"] = "Ich\nbin nicht fit!",
  ["_Route10CooltrainerF2EndBattleText"] = "Ich\nfühle mich vom\vvielen Wandern\verschöpft...",
  ["_Route10Hiker1AfterBattleText"] = "Schnief...\nDiese verdammte\vErkältung!",
  ["_Route10Hiker1BattleText"] = "Ha-ha-ha-ha!",
  ["_Route10Hiker1EndBattleText"] = "Ha-ha!\nHaha-ha-tschi!",
  ["_Route10Hiker2AfterBattleText"] = "Ich habe von\nBergluft die Nase\vgestrichen voll!",
  ["_Route10Hiker2BattleText"] = "Ahh! Die Bergluft\nist so wunderbar\verfrischend!",
  ["_Route10Hiker2EndBattleText"] = "Ich\nkann wieder\vklar denken!",
  ["_Route10PowerPlantSignText"] = "KRAFTWERK",
  ["_Route10RockTunnelSignText"] = "FELSTUNNEL",
  ["_Route10SuperNerd1AfterBattleText"] = "Zu Hause habe ich\nnoch mehr seltene\vPOKéMON!",
  ["_Route10SuperNerd1BattleText"] = "Bist Du auch ein\nPOKéMANIAC?\vMöchtest Du meine\vSammlung sehen?",
  ["_Route10SuperNerd1EndBattleText"] = "Naja,\nmacht nichts!",
  ["_Route10SuperNerd2AfterBattleText"] = "Ich nehme Dir\nübel, daß Du mich\vbesiegt hast!",
  ["_Route10SuperNerd2BattleText"] = "Hey Du, möchtest\nDu meine POKéMON\vsehen?",
  ["_Route10SuperNerd2EndBattleText"] = "Nein!\nMeine POKéMON!",
  ["_Route11DiglettsCaveSignText"] = "DIGDAS HÖHLE",
  ["_Route11Gambler1AfterBattleText"] = "Das ganze\nLeben ist ein\vGlücksspiel!",
  ["_Route11Gambler1BattleText"] = "Versuche Dein\nGlück gegen mich!",
  ["_Route11Gambler1EndBattleText"] = "\nDas Glück hat\vmich verlassen!",
  ["_Route11Gambler2AfterBattleText"] = "Feiglinge haben\nin der Welt der\vPOKéMON keine\vChance!",
  ["_Route11Gambler2BattleText"] = "Wettkämpfe! Ich\nkann ihnen nicht\vwiderstehen!",
  ["_Route11Gambler2EndBattleText"] = "Immerhin\nhatte ich eine\vChance!",
  ["_Route11Gambler3AfterBattleText"] = "Das war purer\nZufall! Nichts\vals Glück!",
  ["_Route11Gambler3BattleText"] = "Haha! Bisher habe\nich noch nie\vverloren!",
  ["_Route11Gambler3EndBattleText"] = "Es gibt\nimmer ein erstes\vMal...",
  ["_Route11Gambler4AfterBattleText"] = "Das war nichts\nals Glück.\vPurer Zufall!",
  ["_Route11Gambler4BattleText"] = "Ich habe noch nie\ngewonnen...",
  ["_Route11Gambler4EndBattleText"] = "Das habe\nich kommen sehen!",
  ["_Route11Gate1FGuardText"] = "Je mehr POKéMON\nman fängt, desto\vschwieriger wird\ves, ihnen allen\vSpitznamen zu\vgeben!\fIn LAVANDIA\nlebt ein Mann,\vder Spitznamen\vvon POKéMON\vbewertet.\fEr nimmt auch\nNamensänderungen\vvor!",
  ["_Route11Gate2FLeftBinocularsNoSnorlaxText"] = "Du schaust durch\ndas Fernrohr.\fDu hast eine\nwunderschöne\vAussicht!",
  ["_Route11Gate2FLeftBinocularsSnorlaxText"] = "Du schaust durch\ndas Fernrohr.\fMitten auf dem\nWeg schläft ein\vgroßes POKéMON!",
  ["_Route11Gate2FOaksAideItemfinderDescriptionText"] = "Auf dem Boden\nliegen oft Items,\vdie man nicht\vsehen kann.\fDer DETEKTOR\nspürt Items in\vDeiner Nähe auf!\fAllerdings ortet\ner nicht die\vexakte Position!\vDu mußt Dich\vgut umschauen!",
  ["_Route11Gate2FRightBinocularsText"] = "Du schaust durch\ndas Fernrohr.\fDer einzige Weg\nvon AZURIA CITY\vnach LAVANDIA\vführt durch den\vFELSTUNNEL.",
  ["_Route11SuperNerd1AfterBattleText"] = "Schone die\nUmwelt und spare\vEnergie!",
  ["_Route11SuperNerd1BattleText"] = "Vorsicht!\nIch verlege hier\vgerade Kabel!",
  ["_Route11SuperNerd1EndBattleText"] = "\nDas war ein\vStromschlag!",
  ["_Route11SuperNerd2AfterBattleText"] = "Ich mache mich\nbesser wieder an\vdie Arbeit.",
  ["_Route11SuperNerd2BattleText"] = "Nimm Dich vor\nHochspannung\vin acht!",
  ["_Route11SuperNerd2EndBattleText"] = "Au!\nDer Funke ist\vübergesprungen!",
  ["_Route11Youngster1AfterBattleText"] = "Immerhin habe ich\nes versucht!\vIch schäme mich\vnicht!",
  ["_Route11Youngster1BattleText"] = "Hast Du Lust, mit\nmir zu kämpfen?",
  ["_Route11Youngster1EndBattleText"] = "Hä?\nDas ist gemein!",
  ["_Route11Youngster2AfterBattleText5"] = "Was willst Du\nnoch? Laß mich\vendlich allein!",
  ["_Route11Youngster2BattleText"] = "Ich habe gerade\nerst angefangen,\vPOKéMON zu\vtrainieren!",
  ["_Route11Youngster2EndBattleText"] = "Mist!\nIch hasse\vschwache POKéMON!",
  ["_Route11Youngster3AfterBattleText"] = "Aus den Bergen\nsteigt manchmal\vein dickes\vPOKéMON herab.\fEs ist sehr\nstark! Versuche\ves zu fangen!",
  ["_Route11Youngster3BattleText"] = "In meiner Klasse\nbin ich der\vBeste!",
  ["_Route11Youngster3EndBattleText"] = "Ich muß\nmeine POKéMON\vmehr trainieren!",
  ["_Route11Youngster4AfterBattleText"] = "Ich muß ein\npaar Stärkere\vfangen!",
  ["_Route11Youngster4BattleText"] = "Meine POKéMON\nmüßten bereit\vsein!",
  ["_Route11Youngster4EndBattleText"] = "Das\nwar schwach!",
  ["_Route12CooltrainerMAfterBattleText"] = "Wenn ich einen\nMONDSTEIN hätte,\vkönnten sich\vmeine POKéMON\vweiterentwickeln!",
  ["_Route12CooltrainerMBattleText"] = "Besitzt Du einen\nMONDSTEIN?",
  ["_Route12CooltrainerMEndBattleText"] = "Aua!",
  ["_Route12Fisher1AfterBattleText"] = "Irgendwann werde\nich den großen\vFang machen!",
  ["_Route12Fisher1BattleText"] = "Cool! Mir ist\netwas ins Netz\vgegangen!",
  ["_Route12Fisher1EndBattleText"] = "Mist!\nBloß ein kleiner\vFisch!",
  ["_Route12Fisher2AfterBattleText"] = "Hätte ich eine\nbessere Angel,\vwürde ich bessere\vPOKéMON fangen!",
  ["_Route12Fisher2BattleText"] = "Nur mit der Ruhe!\nAls Angler muß\vman geduldig\vsein!",
  ["_Route12Fisher2EndBattleText"] = "Der ist\nmir entwischt!",
  ["_Route12Fisher3AfterBattleText"] = "Von POKéMON\nverstehst Du sehr\vviel, doch ich\vbin der bessere\vAngler!",
  ["_Route12Fisher3BattleText"] = "Der ANGELKÖNIG\ngegen das\vPOKéMON-KIND!",
  ["_Route12Fisher3EndBattleText"] = "Das war\nspitze!",
  ["_Route12Fisher4AfterBattleText"] = "OK, mit der Zeit\ngewöhnt man sich\vdaran, zu\vverlieren!",
  ["_Route12Fisher4BattleText"] = "Eigentlich würde\nich lieber\varbeiten...",
  ["_Route12Fisher4EndBattleText"] = "Das war\nwahrlich kein\vZuckerschlecken!",
  ["_Route12Fisher5AfterBattleText"] = "Ich fange immer\nKARPADORS. Doch\vsie sind so\vschwach!",
  ["_Route12Fisher5BattleText"] = "Man weiß nie, was\nder nächste Fang\vsein wird!",
  ["_Route12Fisher5EndBattleText"] = "Ich hab\nverloren!",
  ["_Route12Gate1FGuardText"] = "Oberhalb der\nTreppe ist ein\vAusguck!",
  ["_Route12Gate2FBrunetteGirlReceivedTM39Text"] = "{PLAYER} erhält\nTM39!",
  ["_Route12Gate2FBrunetteGirlTM39ExplanationText"] = "TM39 ist\nSTERNSCHAUER.\fSTERNSCHAUER ist\neine treffsichere\vTechnik, die in\vwichtigen Kämpfen\vvon großem Nutzen\vsein kann!",
  ["_Route12Gate2FBrunetteGirlTM39NoRoomText"] = "Oh, Du kannst es\nim Moment nicht\vtragen.",
  ["_Route12Gate2FBrunetteGirlYouCanHaveThisText"] = "Meine POKéMON\nwurden im\vPOKéMON-TURM zur\vletzten Ruhe\vgebettet.\fIch gebe Dir\ndiese TM. Ich\vbenötige sie\vnicht länger...",
  ["_Route12Gate2FLeftBinocularsText"] = "Du schaust durch\ndas Fernrohr.\fDu siehst einen\nangelnden Mann!",
  ["_Route12Gate2FRightBinocularsText"] = "Du schaust durch\ndas Fernrohr.\fDu siehst den\nPOKéMON-TURM!",
  ["_Route12SignText"] = "ROUTE 12, NORDEN:\nLAVANDIA.",
  ["_Route12SnorlaxCalmedDownText"] = "RELAXO hat sich\nwieder beruhigt!\vEs gähnt und\vläuft in die\vBerge zurück!",
  ["_Route12SnorlaxText"] = "Ein schlafendes\nPOKéMON versperrt\vden Weg!",
  ["_Route12SnorlaxWokeUpText"] = "RELAXO ist\naufgewacht!\fEs ist brummig\nund greift\vverschlafen an!",
  ["_Route12SportFishingSignText"] = "SPORTANGEL-ZONE",
  ["_Route12SuperNerdAfterBattleText"] = "Wasser leitet\nElektrizität.\vGreife WASSER-\vPOKéMON mit\vElektro-Attacken\van!",
  ["_Route12SuperNerdBattleText"] = "Elektrizität ist\nmeine Stärke!",
  ["_Route12SuperNerdEndBattleText"] = "\nStromkreis\vunterbrochen!",
  ["_Route12SuperRodHouseFishingGuruDoYouLikeToFishText"] = "Mein Bruder ist\nder PROFI-ANGLER!\fIch liebe den\nAngelsport!\fMöchtest Du auch\nangeln?",
  ["_Route12SuperRodHouseFishingGuruFishingWayOfLifeText"] = "\fAngeln ist nicht\nnur ein Sport, es\vist eine Kunst!\fNun ziehe los,\num den großen\vFang zu landen!",
  ["_Route12SuperRodHouseFishingGuruNoRoomText"] = "Oh nein!\fIch habe ein\nGeschenk für\vDich! Aber Du\vkannst nichts\vmehr tragen!",
  ["_Route12SuperRodHouseFishingGuruReceivedSuperRodText"] = "Cool! Du bist mir\nsympathisch!\fNimm das hier und\ngenieße das\vAnglerleben!\f{PLAYER} erhält\neine {RAM:wStringBuffer}!",
  ["_Route12SuperRodHouseFishingGuruThatsDisappointingText"] = "Oh! Das ist so\nenttäuschend...",
  ["_Route12SuperRodHouseFishingGuruTryFishingText"] = "Hallo,\n{PLAYER}!\fBenutze die\nSUPERANGEL in\vallen Gewässern.\vDu kannst die\vverschiedensten\vPOKéMON damit\vfangen!\fGehe angeln, wann\nimmer die Zeit es\verlaubt!",
  ["_Route13Beauty1AfterBattleText"] = "Wenn es männliche\nund weibliche\vPOKéMON gäbe, \vwelche wären wohl\vstärker?",
  ["_Route13Beauty1BattleText"] = "Natürlich werde\nich mit Dir\vspielen!",
  ["_Route13Beauty1EndBattleText"] = "Oh!\nDu kleiner\vWüstling, Du!",
  ["_Route13Beauty2AfterBattleText"] = "Ich habe keine\nAhnung von\vPOKéMON. Aber\vmanche finde ich\vwirklich cool!",
  ["_Route13Beauty2BattleText"] = "Laß Deine\nPOKéMON gegen\vmeine antreten!",
  ["_Route13Beauty2EndBattleText"] = "Das\nwar schon alles?",
  ["_Route13BikerAfterBattleText"] = "Hau bloß ab!",
  ["_Route13BikerBattleText"] = "Was schaust Du so\ndumm aus der\vWäsche?",
  ["_Route13BikerEndBattleText"] = "Zack!\nGetriebeschaden!",
  ["_Route13CooltrainerF1AfterBattleText"] = "Ich werde fleißig\nüben, damit\vich ein guter\vTrainer werde!",
  ["_Route13CooltrainerF1BattleText"] = "Man sagt, für ein\nKind würde ich\vgut kämpfen!",
  ["_Route13CooltrainerF1EndBattleText"] = "Oh!\nIch hab verloren!",
  ["_Route13CooltrainerF2AfterBattleText"] = "Du hast diese\nORDEN im Kampf\vgegen ARENALEITER\vgewonnen, oder?",
  ["_Route13CooltrainerF2BattleText"] = "Wow! Deine ORDEN\nsind supercool!",
  ["_Route13CooltrainerF2EndBattleText"] = "\nDas hat nicht\vganz gereicht!",
  ["_Route13CooltrainerF3AfterBattleText"] = "POKéMON müssen\nviel kämpfen,\vdamit sie stark\vwerden!",
  ["_Route13CooltrainerF3BattleText"] = "Meine niedlichen\nPOKéMON möchten\vDich gern\vkennenlernen.",
  ["_Route13CooltrainerF3EndBattleText"] = "\nWow! Du hast\vmit Leichtigkeit\vgewonnen!",
  ["_Route13CooltrainerF4AfterBattleText"] = "Mit dem CARBON\nhabe ich die\vINITIATIVE meiner\vPOKéMON erhöht.",
  ["_Route13CooltrainerF4BattleText"] = "Ich habe in einer\nHöhle CARBON\vgefunden!",
  ["_Route13CooltrainerF4EndBattleText"] = "Ich\nhab's vermasselt!",
  ["_Route13CooltrainerM1AfterBattleText"] = "Meine POKéMON\nsind fröhlich,\vobwohl sie\vverloren haben!",
  ["_Route13CooltrainerM1BattleText"] = "Meine\nVOGEL-POKéMON\vwollen kämpfen!",
  ["_Route13CooltrainerM1EndBattleText"] = "\nMein Vogel-Team\vhat verloren?",
  ["_Route13CooltrainerM2AfterBattleText"] = "Ich bin besiegt!\nIch werde nach\vHause fliegen!",
  ["_Route13CooltrainerM2BattleText"] = "Bin unterwegs\nund habe\vRückenwind...",
  ["_Route13CooltrainerM2EndBattleText"] = "Der\nWind dreht sich!",
  ["_Route13CooltrainerM3AfterBattleText"] = "Ach, wenn ich\ndoch wie TAUBSI\vund TAUBOGA\vfliegen könnte...",
  ["_Route13CooltrainerM3BattleText"] = "Meine VOGEL-\nPOKéMON begleiten\vmich immer!",
  ["_Route13CooltrainerM3EndBattleText"] = "Die\nLuft ist raus!",
  ["_Route13SignText"] = "ROUTE 13\nNORDEN:\vSTILLE BRÜCKE",
  ["_Route13TrainerTips1Text"] = "TIPS FÜR TRAINER\fSchaue links\nneben dem\vPfosten!",
  ["_Route13TrainerTips2Text"] = "TIPS FÜR TRAINER\fDrücke SELECT, um\ndie Positionen\vvon Items im Menü\vzu tauschen.",
  ["_Route14Biker1AfterBattleText"] = "Was, was, was?\nWas willst Du?",
  ["_Route14Biker1BattleText"] = "Los, los! Laß uns\nkämpfen. Auf in\vden Kampf! Los!",
  ["_Route14Biker1EndBattleText"] = "Arrg!\nHau bloß ab!",
  ["_Route14Biker2AfterBattleText"] = "Es ist ganz schön\nmühselig, POKéMON\vzu trainieren!",
  ["_Route14Biker2BattleText"] = "Sehr gut! Ich\nbrauche einen\vZeitvertreib!",
  ["_Route14Biker2EndBattleText"] = "Du hast\nmich besiegt?\vOh Mann!",
  ["_Route14Biker3AfterBattleText"] = "Cool! Deine\nPOKéMON sind\vwirklich stark!\fMacht geht vor\nRecht! Du hast\ves begriffen!",
  ["_Route14Biker3BattleText"] = "Wir kommen öfter\nher, weil es hier\vso unglaublich\vviel Platz gibt!",
  ["_Route14Biker3EndBattleText"] = "Kurz\nund schmerzlos!",
  ["_Route14Biker4AfterBattleText"] = "Du gegen mich!\nDu weißt, wer\vgewinnt!",
  ["_Route14Biker4BattleText"] = "Ein POKéMON-\nKAMPF? Cool!\vLeg los, Kumpel!",
  ["_Route14Biker4EndBattleText"] = "Voll\nerwischt!",
  ["_Route14CooltrainerM1AfterBattleText"] = "Eine durch eine\nVM erlernte\vAttacke können\vPOKéMON niemals\vwieder vergessen!",
  ["_Route14CooltrainerM1BattleText"] = "Damit POKéMON\nstarke Attacken\verlernen, muß man\vTM einsetzen!",
  ["_Route14CooltrainerM1EndBattleText"] = "Ich\nwar zu schlecht!",
  ["_Route14CooltrainerM2AfterBattleText"] = "Sie müssen\nstärkere Attacken\vlernen!",
  ["_Route14CooltrainerM2BattleText"] = "Meine VOGEL-\nPOKéMON sind\vgut auf Kämpfe\vvorbereitet!",
  ["_Route14CooltrainerM2EndBattleText"] = "\nSie waren nicht\vstark genug...",
  ["_Route14CooltrainerM3AfterBattleText"] = "Bringe POKéMON\nihrem Element\ventsprechende\vAttacken bei, um\vihre volle Stärke\vauszunutzen!",
  ["_Route14CooltrainerM3BattleText"] = "In PRISMANIA CITY\nkann man TM\vkaufen.\vVM besitzen\vallerdings nur\vwenige Personen.",
  ["_Route14CooltrainerM3EndBattleText"] = "Ohh!\nSo ein Mist!",
  ["_Route14CooltrainerM4AfterBattleText"] = "Meine\nLeidenschaft sind\vVOGEL-POKéMON!",
  ["_Route14CooltrainerM4BattleText"] = "Hast Du einem\nVOGEL-POKéMON\vschon das FLIEGEN\vbeigebracht?",
  ["_Route14CooltrainerM4EndBattleText"] = "\nWar das eine\vBruchlandung!",
  ["_Route14CooltrainerM5AfterBattleText"] = "Die 3 legendären\nPOKéMON sind\vgroße Raubvögel.",
  ["_Route14CooltrainerM5BattleText"] = "Hast Du schon von\nden legendären\vPOKéMON gehört?",
  ["_Route14CooltrainerM5EndBattleText"] = "Warum\nhab ich verloren?",
  ["_Route14CooltrainerM6AfterBattleText"] = "Längerfristig ist\nes egal, ob man\vgewinnt oder\vverliert!",
  ["_Route14CooltrainerM6BattleText"] = "Ich will nicht\nunbedingt, aber\vlaß uns dennoch\vkämpfen!",
  ["_Route14CooltrainerM6EndBattleText"] = "Ich\nwußte, ich würde\vverlieren!",
  ["_Route14SignText"] = "ROUTE 14, WESTEN:\nFUCHSANIA CITY",
  ["_Route15Beauty1AfterBattleText"] = "OK, Du hast mich\nbesiegt. Es macht\vmir nichts aus!",
  ["_Route15Beauty1BattleText"] = "Du bist ein\ngewitzter Kerl!",
  ["_Route15Beauty1EndBattleText"] = "\nUnd Du siehst\vso süß aus!",
  ["_Route15Beauty2AfterBattleText"] = "Ich verbringe\nzu Hause sehr\vviel Zeit mit\vmeinen POKéMON!",
  ["_Route15Beauty2BattleText"] = "Ich trainiere\nPOKéMON, weil ich\valleine lebe!",
  ["_Route15Beauty2EndBattleText"] = "So\nhabe ich es\vmir aber nicht\vvorgestellt!",
  ["_Route15Biker1AfterBattleText"] = "Man lebt nur\neinmal! Daher bin\vich ein Bandit!\vTEAM ROCKET ist\vcool!",
  ["_Route15Biker1BattleText"] = "Hey, Kleiner!\nLaß uns kämpfen!",
  ["_Route15Biker1EndBattleText"] = "Warum\nhab ich verloren?",
  ["_Route15Biker2AfterBattleText"] = "Vergiß die Sache\nmit dem Geld, das\vwar ein Scherz!",
  ["_Route15Biker2BattleText"] = "Her mit Deinen\nMoneten! Wenn Du\vverlierst, gibst\vDu mir Dein Geld!",
  ["_Route15Biker2EndBattleText"] = "Das darf\nnicht wahr sein!",
  ["_Route15CooltrainerF1AfterBattleText"] = "Man kann den\nSpitznamen eines\vPOKéMON, das man\vgetauscht hat,\vnicht ändern.\fNur der Original-\nTrainer kann den\vNamen verändern.",
  ["_Route15CooltrainerF1BattleText"] = "Wunderbar! Jetzt\nkann ich gleich\vausprobieren, wie\vgut die POKéMON\vsind, die ich\vgetauscht habe!",
  ["_Route15CooltrainerF1EndBattleText"] = "\nNicht gut genug!",
  ["_Route15CooltrainerF2AfterBattleText"] = "Ich habe Angst\nvor BIKERN, sie\vsind so häßlich\vund brutal!",
  ["_Route15CooltrainerF2BattleText"] = "Du siehst\nlammfromm aus!\vDann habe ich\veine Chance!",
  ["_Route15CooltrainerF2EndBattleText"] = "Du\nbist ein Wolf im\vSchafspelz!",
  ["_Route15CooltrainerF3AfterBattleText"] = "Ich tausche mit\nmeinen Freunden\vPOKéMON!",
  ["_Route15CooltrainerF3BattleText"] = "POKéMON zu\ntauschen ist\vwirklich cool!",
  ["_Route15CooltrainerF3EndBattleText"] = "Ich\nsagte tauschen!",
  ["_Route15CooltrainerF4AfterBattleText"] = "Ich muß ein wenig\nmit schwächeren\vTrainern üben...",
  ["_Route15CooltrainerF4BattleText"] = "Möchtest Du mit\nmeinen POKéMON\vspielen?",
  ["_Route15CooltrainerF4EndBattleText"] = "Ich\nwar zu ungestüm!",
  ["_Route15CooltrainerM1AfterBattleText"] = "Vielleicht bin\nich keine\vKämpfernatur...",
  ["_Route15CooltrainerM1BattleText"] = "Wenn ich pfeife,\nkann ich\vVOGEL-POKéMON\vherbeirufen!",
  ["_Route15CooltrainerM1EndBattleText"] = "Au!\nDas ist tragisch!",
  ["_Route15CooltrainerM2AfterBattleText"] = "Wußtest Du, daß\nmanche Attacken,\vwie ERDBEBEN,\vkeine Wirkung auf\vVögel haben?",
  ["_Route15CooltrainerM2BattleText"] = "Hmm? Meine Vögel\nerschaudern?\fDu mußt wirklich\nsehr gut sein!",
  ["_Route15CooltrainerM2EndBattleText"] = "Ich\nlag also richtig!",
  ["_Route15Gate1FGuardText"] = "Arbeitest Du an\neinem POKéDEX?\fPROF. EICHS\nGehilfe ist\vkürzlich hier\vvorbeigekommen!",
  ["_Route15Gate2FBinocularsText"] = "Du schaust durch\ndas Fernrohr.\fHmm, das sieht\nwie eine kleine\vInsel aus!",
  ["_Route15Gate2FOaksAideExpAllText"] = "Mit dem EP-TEILER\nbekommen alle\vPOKéMON, die Du\vmit Dir führst,\vnach einem Kampf\vEP.\fDie EP werden\nnach dem Kampf\vunter den POKéMON\vaufgeteilt.\fLege den\nEP-TEILER via PC\vab, wenn Du ihn\vnicht benutzen\vmöchtest.",
  ["_Route15SignText"] = "ROUTE 15, WESTEN:\nFUCHSANIA CITY",
  ["_Route15UpstairsBinocularsText"] = "Du schaust durch\ndas Fernrohr...\fEin großer Vogel\nfliegt anmutig\vaufs Meer hinaus.",
  ["_Route16Biker1AfterBattleText"] = "Wir lungern hier\nherum! Wie sieht\ves bei Dir aus?",
  ["_Route16Biker1BattleText"] = "Was willst Du?",
  ["_Route16Biker1EndBattleText"] = "Wage ja\nnicht zu lachen!",
  ["_Route16Biker2AfterBattleText"] = "Naja, vergiß es!\nWer braucht schon\vein FAHRRAD?",
  ["_Route16Biker2BattleText"] = "Du besitzt ein\nschönes FAHRRAD!\vHer damit!",
  ["_Route16Biker2EndBattleText"] = "K.O.!",
  ["_Route16Biker3AfterBattleText"] = "Ich hasse es, zu\nverlieren! Mach,\vdaß Du wegkommst!",
  ["_Route16Biker3BattleText"] = "Laß uns spielen,\nHasenfuß!",
  ["_Route16Biker3EndBattleText"] = "Du\nkleine Ratte!",
  ["_Route16Biker4AfterBattleText"] = "Mann kann über\neine Küstenstraße\vvon ORANIA CITY\vnach FUCHSANIA\vCITY gelangen.",
  ["_Route16Biker4EndBattleText"] = "Rumms!\nÜberrumpelt!",
  ["_Route16Biker5AfterBattleText"] = "Ich mag wilde\nPOKéMON!\fSie strotzen nur\nso vor Kraft!",
  ["_Route16Biker5BattleText"] = "Ich bin furchtbar\ngemein und\verfolgssüchtig!",
  ["_Route16Biker5EndBattleText"] = "Nein,\nnein, nein!",
  ["_Route16Biker6AfterBattleText"] = "Ich liebe es,\nandere mit meinen\vbissigen POKéMON\vzu schikanieren!",
  ["_Route16Biker6BattleText"] = "Ja, sicher! Ich\nmache Dir Platz!",
  ["_Route16Biker6EndBattleText"] = "Treib\nmich nicht in den\vWahnsinn!",
  ["_Route16CyclingRoadSignText"] = "RADWEG\nGute Abfahrt!",
