  ["_Route19Swimmer4EndBattleText"] = "Nein!\nEin traumatisches\vErlebnis!",
  ["_Route19Swimmer5AfterBattleText"] = "Bis zu den\nSEESCHAUMINSELN\vist es noch ein\vweiter Weg!",
  ["_Route19Swimmer5BattleText"] = "Gibst Du mir das\nPOKéMON, auf\vdem Du stehst,\vwenn ich gewinne?",
  ["_Route19Swimmer5EndBattleText"] = "Oh! Ich\nhabe verloren!",
