  ["_Route20CooltrainerMAfterBattleText"] = "Kann ich mit\nmeinen VOGEL-\vPOKéMON noch\vzurückfliegen?",
  ["_Route20CooltrainerMBattleText"] = "Meine\nVOGEL-POKéMON\vhaben mich\vhierher getragen!",
  ["_Route20CooltrainerMEndBattleText"] = "\nOh nein!",
