  ["_Route20Swimmer5BattleText"] = "Schau Dir meinen\ngestählten Körper\vruhig an!",
  ["_Route20Swimmer5EndBattleText"] = "\nWaschlappen!",
  ["_Route20Swimmer6AfterBattleText"] = "Es dürfte Spaß\nmachen, auf einem\vPOKéMON zu\vsurfen!",
