  ["_Route22Rival1DefeatedText"] = "Oh nein!\nSoviel Glück wie\vDu kann man\vnicht haben!",
  ["_Route22Rival1VictoryText"] = "{RIVAL}: Was?\nWarum ich zwei\vPOKéMON besitze?\fDumme Frage!\nFang Dir lieber\vselbst noch ein\vpaar!",
  ["_Route22Rival2DefeatedText"] = "Was!?\fIch war zu\nunvorsichtig!",
  ["_Route22Rival2VictoryText"] = "{RIVAL}: Hahaha!\n{PLAYER}! War das\vetwa alles? Du\vbist nicht einmal\vannähernd so gut\vwie ich, Kumpel!\fTrainiere lieber\nnoch ein bißchen,\vDu Verlierer!",
  ["_Route22RivalAfterBattleText1"] = "In der PKMN-LIGA\ngibt es viele\vstarke Trainer!\fIch muß einen Weg\nfinden, an ihnen\vvorbeizukommen.\fDu solltest\naufhören zu\vbummeln und Dich\vin Bewegung\vsetzen!",
  ["_Route22RivalAfterBattleText2"] = "Das war ein gutes\nAufwärmtraining!\vIch bin gut auf\vdie PKMN-LIGA\vvorbereitet!\f{PLAYER}, auch\nwenn Du gewonnen\vhast, mußt Du\vmehr trainieren!\fIch glaube, Du\nbist Dir dessen\vbewußt! Bis dann!",
  ["_Route22RivalBeforeBattleText1"] = "{RIVAL}: Hey!\n{PLAYER}!\fBist Du auf\ndem Weg zur\vPKMN-LIGA?\fVergiß es!\nWahrscheinlich\vbesitzt Du nicht\veinmal einen\vORDEN!\fDie Wache wird\nDich gar nicht\verst durchlassen!\fAch, sind\nDeine POKéMON\veigentlich\vstärker geworden?",
  ["_Route22RivalBeforeBattleText2"] = "{RIVAL}: Was?!\n{PLAYER}!\fWas für eine\nÜberraschung!\fDu bist also auch\nauf dem Weg zur\vPKMN-LIGA, oder?\fDu besitzt auch\nalle ORDEN?\vDas ist cool!\f{PLAYER},  ich\nwerde mich für\vdie PKMN-LIGA\vaufwärmen, indem\vich Dich besiege!\fAlso, los geht's!",
  ["_Route23GoRightAheadText"] = "\fOK, Du darfst\npassieren!",
  ["_Route23OhThatIsTheBadgeText"] = "Du darfst nur\npassieren, wenn\vDu bereits den\v{RAM:wNameBuffer}\vbesitzt!\fWunderbar!\nDu trägst den\v{RAM:wNameBuffer}!",
  ["_Route23VictoryRoadGateSignText"] = "SIEGESSTRASSE\n- PKMN-LIGA",
  ["_Route23YouDontHaveTheBadgeYetText"] = "Du darfst nur\nmit dem\v{RAM:wNameBuffer}\vpassieren!\fDu besitzt den\n{RAM:wNameBuffer} noch\vnicht!\fNur wer ihn\nträgt, darf in\vdie PKMN-LIGA!",
  ["_Route24CooltrainerF1AfterBattleText"] = "Ich habe alles\ngegeben, ich\vschäme mich\vnicht!",
  ["_Route24CooltrainerF1BattleText"] = "Ich bin Nr. 4!\nWirst Du müde?",
  ["_Route24CooltrainerF1EndBattleText"] = "Ich habe\nauch verloren!",
  ["_Route24CooltrainerF2AfterBattleText"] = "Ich habe alles\ngegeben, ich\vschäme mich\vnicht!",
  ["_Route24CooltrainerF2BattleText"] = "Ich bin Nr. 2!\nNun wird es\vernst!",
  ["_Route24CooltrainerF2EndBattleText"] = "Wie konnte\nich verlieren?",
  ["_Route24CooltrainerM1DefeatedText"] = "Wah!\nDu bist gut!",
  ["_Route24CooltrainerM1JoinTeamRocketText"] = "Möchtest Du auch\nMitglied des\vTEAM ROCKET\vwerden?\fUnsere\nGruppierung\vbenutzt POKéMON\vfür teuflische\vZwecke!\fMöchtest Du\nbeitreten?\fWirklich nicht?\fKomm schon,\nwerde Mitglied!\fIch empfehle Dir,\nein Mitglied zu\vwerden!\fIch glaube, ich\nsollte ein wenig\vÜberzeugungs-\varbeit leisten!\fDieses Angebot\nkannst Du nicht\vablehnen!",
  ["_Route24CooltrainerM1NoRoomText"] = "Du hast keinen\nPlatz für weitere\vItems!",
  ["_Route24CooltrainerM1ReceivedNuggetText"] = "{PLAYER} erhält\neinen {RAM:wStringBuffer}!",
  ["_Route24CooltrainerM1YouBeatOurContestText"] = "Herzlichen\nGlückwunsch!\vDu hast alle fünf\vTrainer besiegt!",
  ["_Route24CooltrainerM1YouCouldBecomeATopLeaderText"] = "Bei Deinem Können\nwürdest Du im\vTEAM ROCKET\vleicht die rechte\vHand vom Boss!",
  ["_Route24CooltrainerM1YouJustEarnedAPrizeText"] = "\fDu hast einen\ngroßartigen Preis\vgewonnen!",
  ["_Route24CooltrainerM2AfterBattleText"] = "Ich habe mich\nversteckt, weil\vmir die Leute auf\vder Brücke Angst\vgemacht haben!",
  ["_Route24CooltrainerM2BattleText"] = "Ich habe Deine\nVorstellung aus\vdem Gras heraus\vbeobachtet!",
  ["_Route24CooltrainerM2EndBattleText"] = "Ich\nhabe wohl doch\vnichts gesehen!",
  ["_Route24CooltrainerM3AfterBattleText"] = "Ich habe alles\ngegeben, ich\vschäme mich\vnicht!",
  ["_Route24CooltrainerM3BattleText"] = "Ich bin Nr. 5!\nIch mache Dich\vfertig!",
  ["_Route24CooltrainerM3EndBattleText"] = "Das\nwar zuviel des\vGuten!",
  ["_Route24DamianText1"] = "Ich kann einfach\nkeine POKéMON\vtrainieren.\fIch habe mich\nnicht gut genug\vum mein GLUMANDA\vgekümmert...\fVersprich mir,\ngut für GLUMANDA\vzu sorgen, dann\vgebe ich es Dir.",
  ["_Route24DamianText2"] = "Kümmere Dich gut\num GLUMANDA!",
  ["_Route24DamianText3"] = "Oh... Dann lasse\nich es besser\vfrei.",
  ["_Route24DamianText4"] = "Wie geht es\nGLUMANDA?",
  ["_Route24Youngster1AfterBattleText"] = "Ich habe alles\ngegeben, ich\vschäme mich\vnicht!",
  ["_Route24Youngster1BattleText"] = "Hier kommt Nr. 3!\nIch mache Dir das\vLeben schwer!",
  ["_Route24Youngster1EndBattleText"] = "Ah!\nEiskalt erwischt!",
  ["_Route24Youngster2AfterBattleText"] = "Ich habe alles\ngegeben, ich\vschäme mich\vnicht!",
  ["_Route24Youngster2BattleText"] = "Das hier ist die\nNUGGET-BRÜCKE!\vWenn Du uns fünf\vTrainer besiegst, \verhältst Du einen\vwertvollen Preis!\fWillst Du Dein\nGlück versuchen?",
  ["_Route24Youngster2EndBattleText"] = "Wow!\nDu bist gut!",
  ["_Route25BillSignText"] = "KÜSTENHAUS\nHier wohnt BILL!",
  ["_Route25CooltrainerF1AfterBattleText"] = "Ach, wäre mein\nFreund doch auch\vso toll wie Du!",
  ["_Route25CooltrainerF1BattleText"] = "Hallo! Mein\nFreund ist cool!",
  ["_Route25CooltrainerF1EndBattleText"] = "Ich war\nnicht in Form!",
  ["_Route25CooltrainerF2AfterBattleText"] = "Du warst auf dem\nMONDBERG? Hast\vDu ein PIEPI\vgefunden?",
  ["_Route25CooltrainerF2BattleText"] = "Meine Freundin\nhat so ein süßes\vPOKéMON! Ich\vbin furchtbar\vneidisch!",
  ["_Route25CooltrainerF2EndBattleText"] = "Ich bin\nnicht neidisch!",
  ["_Route25CooltrainerMAfterBattleText"] = "Naja, meine\nFreundin wird\vmich aufheitern!",
  ["_Route25CooltrainerMBattleText"] = "Ich bin richtig\ncool! Ich habe\veine Freundin!",
  ["_Route25CooltrainerMEndBattleText"] = "Ach,\nso ein Mist...",
  ["_Route25Hiker1AfterBattleText"] = "Mist!\nMich hat ein\vZUBAT gebissen!",
  ["_Route25Hiker1BattleText"] = "Ich komme gerade\nvom MONDBERG!\vMeine POKéMON\vsind in Bestform!",
  ["_Route25Hiker1EndBattleText"] = "Du hast\ngut gekämpft!",
  ["_Route25Hiker2AfterBattleText"] = "Dieser Sammler\nbesitzt viele\vseltene POKéMON.",
  ["_Route25Hiker2BattleText"] = "Ich bin auf dem\nWeg zu einem\vPOKéMON-Sammler!",
  ["_Route25Hiker2EndBattleText"] = "Du hast\nmich besiegt.",
  ["_Route25Hiker3AfterBattleText"] = "Der Pfad dort\nunten ist eine\vAbkürzung nach\vAZURIA CITY.",
  ["_Route25Hiker3BattleText"] = "Du möchtest zu\nBILL? Aber erst\vwird gekämpft!",
  ["_Route25Hiker3EndBattleText"] = "Du hast\nviel Erfahrung!",
  ["_Route25Youngster1AfterBattleText"] = "Jedes POKéMON hat\nseine Schwächen!\vMan sollte daher\vunterschiedliche\vPOKéMON\vtrainieren.",
  ["_Route25Youngster1BattleText"] = "Die Trainer der\nGegend kommen\vzum Üben hierher!",
  ["_Route25Youngster1EndBattleText"] = "Du bist\nrichtig gut!",
  ["_Route25Youngster2AfterBattleText"] = "Auf der M.S. ANNE\nhabe ich Trainer\vaus aller Welt\vgesehen!",
  ["_Route25Youngster2BattleText"] = "Ich habe in\nORANIA CITY mit\vmeinem Vater auf\vder M.S. ANNE\veine Party\vbesucht!",
  ["_Route25Youngster2EndBattleText"] = "Ich bin\nDir nicht böse!",
  ["_Route25Youngster3AfterBattleText"] = "Wenn eines Deiner\nPOKéMON verwirrt\vist oder schläft,\vwechsle es aus!",
  ["_Route25Youngster3BattleText"] = "Ich wußte, daß\nich gegen Dich\vkämpfen würde!",
  ["_Route25Youngster3EndBattleText"] = "Ich\nwußte auch, daß\vich verlieren\vwürde!",
  ["_Route2DiglettsCaveSignText"] = "DIGDAS HÖHLE",
  ["_Route2GateOaksAideFlashExplanationText"] = "Mit der VM BLITZ\nkann man selbst\vdie dunkelsten\vHöhlen erhellen.",
  ["_Route2GateYoungsterText"] = "Sobald eines\nDeiner POKéMON\vBLITZ erlernt\vhat, kannst\vDu Dich in den\vFELSTUNNEL wagen!",
  ["_Route2SignText"] = "ROUTE 2\nVERTANIA CITY -\vMARMORIA CITY",
  ["_Route2TradeHouseScientistText"] = "Auch wenn ein\nPOKéMON\vausscheidet,\vkann es weiter\vSpezial-Techniken\vwie zum Beispiel\vden ZERSCHNEIDER\vanwenden!",
  ["_Route3CooltrainerF1AfterBattleText"] = "Hör auf, Leute\nanzustarren! Dann\vmußt Du auch\vnicht kämpfen!",
  ["_Route3CooltrainerF1BattleText"] = "Was starrst Du\nmich so an?",
  ["_Route3CooltrainerF1EndBattleText"] = "Du bist\ngefährlich!",
  ["_Route3CooltrainerF2AfterBattleText"] = "Vermeide Kämpfe,\nindem Du anderen\vTrainern aus dem\vWeg gehst!",
  ["_Route3CooltrainerF2BattleText"] = "Warum schaust\nDu mich so\vfasziniert an?",
  ["_Route3CooltrainerF2EndBattleText"] = "Bleib\nimmer nett!",
  ["_Route3CooltrainerF3AfterBattleText"] = "Die ROUTE 4 liegt\nam Fuße des\vMONDBERGES.",
  ["_Route3CooltrainerF3BattleText"] = "Huch! Sollen das\netwa Annäherungs-\vversuche sein?",
  ["_Route3CooltrainerF3EndBattleText"] = "\nBleib mir fern!",
  ["_Route3SignText"] = "ROUTE 3\nZUM MONDBERG",
  ["_Route3Text1"] = "Puh! Ich muß\neine Pause\vmachen!\fDer Weg durch den\nTunnel aus AZURIA\vCITY ist sehr\vbeschwerlich!",
  ["_Route3Youngster1AfterBattleText"] = "Neben den POKéMON\nhier im Wald gibt\ves noch Unmengen\vanderer POKéMON\vzu entdecken!",
  ["_Route3Youngster1BattleText"] = "Hey! Ich kenne\nDich aus dem\vVERTANIA-WALD!",
  ["_Route3Youngster1EndBattleText"] = "Du\nhast mich wieder\vbesiegt!",
  ["_Route3Youngster2AfterBattleText"] = "Du kannst POKéMON\nvia PC in Boxen\vablegen. Jede BOX\vfasst 20 POKéMON!",
  ["_Route3Youngster2BattleText"] = "Überall sind\nBrennesseln! Und\vich trage Shorts!\vSo ein MIST!",
  ["_Route3Youngster2EndBattleText"] = "Wäre\nich heute doch\vnur daheim\vgeblieben!",
  ["_Route3Youngster3AfterBattleText"] = "Wenn auf dem PC\neine POKéMON-BOX\vvoll ist, wechsle\veinfach zu einer\vanderen BOX!",
  ["_Route3Youngster3BattleText"] = "Bist Du auch ein\nTrainer? Laß uns\vkämpfen!",
  ["_Route3Youngster3EndBattleText"] = "Mit\ndiesen POKéMON\vhätte ich auch\vleicht gewonnen!",
  ["_Route3Youngster4AfterBattleText"] = "Man sollte nicht\nalles machen, was\vder große Bruder\vverlangt! Hehe!",
  ["_Route3Youngster4BattleText"] = "Hehe! Ich habe\nmeinem Bruder\vgesagt, er soll\vShorts anziehen!",
  ["_Route3Youngster4EndBattleText"] = "Nein!\nVerloren!",
  ["_Route3Youngster5AfterBattleText"] = "Die POKéMON eines\nTrainers sind\vstärker als\vwildlebende!",
  ["_Route3Youngster5BattleText"] = "Meine neuen\nPOKéMON wollen\vkämpfen!",
  ["_Route3Youngster5EndBattleText"] = "Du\nhast meine\vPOKéMON besiegt!",
  ["_Route4CooltrainerF1Text"] = "Aua! Ich bin über\nein KLEINSTEIN\vgestolpert, ein\vSTEIN-POKéMON!",
  ["_Route4CooltrainerF2AfterBattleText"] = "Es dürfte hier\nkeine PILZ-\vPOKéMON mehr\vgeben.\fIch glaube, ich\nhabe alle\vgefangen.",
  ["_Route4CooltrainerF2BattleText"] = "Ich bin hier, um\nPILZ-POKéMON\vzu fangen!",
  ["_Route4CooltrainerF2EndBattleText"] = "Ach,\nPILZ-POKéMON\vsind ja so süß!",
  ["_Route4MtMoonSignText"] = "MONDBERG\nTunneleingang",
  ["_Route4SignText"] = "ROUTE 4\nMONDBERG -\vAZURIA CITY",
  ["_Route5UndergroundPathSignText"] = "TUNNELPFAD\nAZURIA CITY -\vORANIA CITY",
  ["_Route6CooltrainerF1AfterBattleText"] = "Jetzt verstehe\nich, daß man den\vSieg nicht vorher\vberechnen kann!",
  ["_Route6CooltrainerF1BattleText"] = "Ich trainiere für\nmeinen Liebsten!\vStör mich nicht!",
  ["_Route6CooltrainerF1EndBattleText"] = "Das\nist unmöglich...",
  ["_Route6CooltrainerF2AfterBattleText"] = "Verrätst Du mir\nDein Geheimnis?\vIch möchte auch\vstärker werden!",
  ["_Route6CooltrainerF2BattleText"] = "Kämpfen? Meinst\nDu mich? Na gut!",
  ["_Route6CooltrainerF2EndBattleText"] = "\nDas hat nicht\vganz geklappt!",
  ["_Route6CooltrainerM1AfterBattleText"] = "Meine Liebste\nwird mich\vverlassen!",
  ["_Route6CooltrainerM1BattleText"] = "Das mache ich\nalles aus Liebe!\vLaß mich allein!",
  ["_Route6CooltrainerM1EndBattleText"] = "Das\nkann nicht sein!",
  ["_Route6CooltrainerM2AfterBattleText"] = "Zu meiner eigenen\nSicherheit sollte\vich mehr POKéMON\vbei mir tragen!",
  ["_Route6CooltrainerM2BattleText"] = "Hörte ich da\njemanden vom\vKämpfen sprechen?",
  ["_Route6CooltrainerM2EndBattleText"] = "Hmm,\nich hätte es\vbesser überhört!",
  ["_Route6UndergroundPathSignText"] = "TUNNELPFAD\nAZURIA CITY -\vORANIA CITY",
  ["_Route6Youngster1AfterBattleText"] = "Ich gehe in den\nVERTANIA-WALD\vzurück. Dort gibt\ves mehr Käfer!",
  ["_Route6Youngster1BattleText"] = "Man findet hier\ndraußen nicht\vviele Käfer...",
  ["_Route6Youngster1EndBattleText"] = "\nDu beliebst zu\vscherzen, oder?",
  ["_Route6Youngster2AfterBattleText"] = "Sind meine\nPOKéMON zu\vschwach, oder bin\vich etwa nicht\vgut genug?",
  ["_Route6Youngster2BattleText"] = "Dich habe ich\nnoch nie gesehen!\vBist Du ein guter\vTrainer?",
  ["_Route6Youngster2EndBattleText"] = "Du\nbist ein zu guter\vTrainer!",
  ["_Route7UndergroundPathSignText"] = "TUNNELPFAD\nPRISMANIA CITY -\vLAVANDIA",
  ["_Route8CooltrainerF1AfterBattleText"] = "Wenn POKéMON\nsich entwickeln,\vwerden sie groß\vund häßlich! Sie\vsollten klein und\vsüß bleiben!",
  ["_Route8CooltrainerF1BattleText"] = "Ich mag alle\nNIDORAN sehr\vgerne! Deshalb\vsammle ich sie!",
  ["_Route8CooltrainerF1EndBattleText"] = "Warum?\nWarum nur?",
  ["_Route8CooltrainerF2AfterBattleText"] = "Aber TAUBSI und\nRATTFRATZ sind\vauch niedlich!",
  ["_Route8CooltrainerF2BattleText"] = "MAUZI ist so süß!\nMiau, miauz!",
  ["_Route8CooltrainerF2EndBattleText"] = "Miau!",
  ["_Route8CooltrainerF3AfterBattleText"] = "Der Wachtposten\nvon SAFFRONIA\vCITY ist so\vgemein! Er läßt\vuns nicht in die\vStadt!",
  ["_Route8CooltrainerF3BattleText"] = "Es muß ziemlich\nblöd aussehen,\vwie wir hier\vherumstehen!",
  ["_Route8CooltrainerF3EndBattleText"] = "Schau, was\nDu getan hast!",
  ["_Route8CooltrainerF4AfterBattleText"] = "Ich habe gehört,\nPIEPI entwickelt\vsich, wenn man\vihm einen\vMONDSTEIN gibt.",
  ["_Route8CooltrainerF4BattleText"] = "Welches POKéMON\nist süß, pummelig\vund kuschlig?",
  ["_Route8CooltrainerF4EndBattleText"] = "Hör auf!\fSei nicht so\ngemein zu PIEPI!",
  ["_Route8Gambler1AfterBattleText"] = "Man kann nicht\nimmer gewinnen!",
  ["_Route8Gambler1BattleText"] = "OK! Die Spiele\nmögen beginnen!",
  ["_Route8Gambler1EndBattleText"] = "\nKnapp vorbei ist\vauch daneben!",
  ["_Route8Gambler2AfterBattleText"] = "Glücksspiele und\ndas Training von\vPOKéMON haben\veines gemeinsam:\vMan kann nicht\vdamit aufhören!",
  ["_Route8Gambler2BattleText"] = "Ich bin ein weit\nherumgekommener\vGlücksspieler!",
  ["_Route8Gambler2EndBattleText"] = "\nDen Jackpot habe\vich noch nicht\vgeknackt...",
  ["_Route8SuperNerd1AfterBattleText"] = "Meine schulischen\nLeistungen sind\vbesser!",
  ["_Route8SuperNerd1BattleText"] = "Du weißt viel\nüber POKéMON!\vDoch wie sieht es\vmit Chemie aus?",
  ["_Route8SuperNerd1EndBattleText"] = "Au! Eine\nKernschmelze!",
  ["_Route8SuperNerd2AfterBattleText"] = "SLEIMA kämpft als\nerstes... und...\vund... dann...",
  ["_Route8SuperNerd2BattleText"] = "Um zu gewinnen,\nbenötigst Du eine\vgute Strategie!",
  ["_Route8SuperNerd2EndBattleText"] = "Ich habe\nverloren! Das ist\vnicht logisch!",
  ["_Route8SuperNerd3AfterBattleText"] = "Wir sitzen hier\nfest, weil\vSAFFRONIA CITY\vabgeriegelt wird.",
  ["_Route8SuperNerd3BattleText"] = "Die Schule macht\nSpaß! POKéMON zu\vtrainieren aber\vauch!",
  ["_Route8SuperNerd3EndBattleText"] = "OK, ich\ngehe lieber zur\vSchule!",
  ["_Route8UndergroundSignText"] = "TUNNELPFAD\nPRISMANIA CITY -\vLAVANDIA",
  ["_Route9AJAfterBattleText"] = "Ich werde meine\n100-Siege-Tour\vmit SANDAN neu\vbeginnen!",
  ["_Route9AJBattleText"] = "Ich werde einmal\nder weltbeste\vPOKéMON-Trainer!",
  ["_Route9AJEndBattleText"] = "Mein\nSANDAN wurde\vbesiegt?",
  ["_Route9CooltrainerF1AfterBattleText"] = "Du benötigst eine\nLichtquelle, um\vden Tunnel zu\vdurchqueren!",
  ["_Route9CooltrainerF1BattleText"] = "Du trägst POKéMON\nbei Dir! Laß uns\vkämpfen!",
  ["_Route9CooltrainerF1EndBattleText"] = "Du\nhast gewonnen!",
  ["_Route9CooltrainerF2AfterBattleText"] = "Du hast sehr viel\nTalent! Viel\vGlück auf Deinem\vweiteren Weg!",
  ["_Route9CooltrainerF2BattleText"] = "Trau Dich ruhig,\nmit mir zu\vkämpfen!",
  ["_Route9CooltrainerF2EndBattleText"] = "Das\nwar zuviel des\vGuten!",
  ["_Route9CooltrainerM2AfterBattleText"] = "Möchtest Du auch\nden FELSTUNNEL\vdurchqueren?",
  ["_Route9CooltrainerM2BattleText"] = "Ich gehe durch\nden FELSTUNNEL\vnach LAVANDIA...",
  ["_Route9CooltrainerM2EndBattleText"] = "\nMit Dir habe ich\vmich übernommen!",
  ["_Route9Hiker1AfterBattleText"] = "Deine Knie haben\nganz schön\vgeschlackert,\voder?",
  ["_Route9Hiker1BattleText"] = "Endlich\nkommt jemand!\vMir war richtig\vlangweilig!",
  ["_Route9Hiker1EndBattleText"] = "War das\netwa schon alles?\fOh! Ich habe kein\neinsatzbereites\vPOKéMON übrig!",
  ["_Route9Hiker2AfterBattleText"] = "Haha! Kinder\nsollten kleine\vRabauken sein!",
  ["_Route9Hiker2BattleText"] = "Du hast\nkeine Chance, Du\vkleiner Rabauke!",
  ["_Route9Hiker2EndBattleText"] = "Was ist\npassiert?",
  ["_Route9Hiker3AfterBattleText"] = "Haha!\nIch bin eine\vechte Frohnatur!",
  ["_Route9Hiker3BattleText"] = "Haha! Wie wär's\nmit einem Kampf?",
  ["_Route9Hiker3EndBattleText"] = "Haha!\nEin fairer Kampf!",
  ["_Route9SignText"] = "ROUTE 9\nAZURIA CITY -\vFELSTUNNEL",
  ["_Route9Youngster1AfterBattleText"] = "Ich sollte lieber\nein paar Stärkere\vsammeln...",
  ["_Route9Youngster1BattleText"] = "Ich stehe jeden\nTag früh auf, um\vmeine POKéMON\vin ihrem Kokon zu\vpflegen!",
  ["_Route9Youngster1EndBattleText"] = "WAS?\fDas war nichts\nals reine Zeit-\vverschwendung!",
  ["_Route9Youngster2AfterBattleText"] = "Wer keine Käfer\nmag, den mag ich\vauch nicht!",
  ["_Route9Youngster2BattleText"] = "Du hast keine\nChance gegen\vmeine KÄFER-\vPOKéMON!",
  ["_Route9Youngster2EndBattleText"] = "\nMeine\vKÄFER-POKéMON...",
  ["_RunAwayText"] = "Schnell weg!",
  ["_SSAnne1FRoomsCooltrainerFAfterBattleText"] = "So behandelt man\nkeine POKéMON\vvon Weltklasse!\fIch verlange eine\nKur in einem \vPKMN-CENTER für\vmeine POKéMON!!!",
  ["_SSAnne1FRoomsCooltrainerFBattleText"] = "Auf meinen Reisen\num die Welt habe\vich unzählige\vPOKéMON gefangen!",
  ["_SSAnne1FRoomsCooltrainerFEndBattleText"] = "Nein!\nIch habe die\vganze Welt für\vdiese POKéMON\vbereist!",
  ["_SSAnne1FRoomsGentleman1AfterBattleText"] = "Sei immer nett zu\nDeinen POKéMON!",
  ["_SSAnne1FRoomsGentleman1BattleText"] = "Ich mache immer\nallein Urlaub!\fNur meine POKéMON\nbegleiten mich!",
  ["_SSAnne1FRoomsGentleman1EndBattleText"] = "Oh\nweh, verloren!",
  ["_SSAnne1FRoomsGentleman2AfterBattleText"] = "Ich will meine\nRuhe haben!\fVerschwinde!",
  ["_SSAnne1FRoomsGentleman2BattleText"] = "Du Rotznase! Was\nfällt Dir ein?",
  ["_SSAnne1FRoomsGentleman2EndBattleText"] = "Mist!\nDu bist ganz\vschön gut!",
  ["_SSAnne1FRoomsGentleman3Text"] = "Pst! Ich bin\nein Geheimagent!\fIch verfolge\nTEAM ROCKET! Pst!",
  ["_SSAnne1FRoomsGirl1Text"] = "Steward, ich\nhätte gern ein\vStückchen Torte!",
  ["_SSAnne1FRoomsGirl2Text"] = "Wir machen eine\ngroße Weltreise!",
  ["_SSAnne1FRoomsLittleGirlText"] = "Ich reise immer\nmit KNUDDELUFF!",
  ["_SSAnne1FRoomsMiddleAgedManText"] = "Ach, so eine\nKreuzfahrt ist\vwundervoll!",
  ["_SSAnne1FRoomsWigglytuffText"] = "KNUDDELUFF: \nKnuddel!",
  ["_SSAnne1FRoomsYoungsterAfterBattleText"] = "Laß uns Freunde\nwerden, OK?\fDann können wir\nPOKéMON tauschen!",
  ["_SSAnne1FRoomsYoungsterBattleText"] = "Ich bin total in\nPOKéMON vernarrt!\vDu auch?",
  ["_SSAnne1FRoomsYoungsterEndBattleText"] = "Wow!\nDu bist cool!",
  ["_SSAnne1FSailorText"] = "Viele Passagiere\nsind hyperaktiv!\fSie langweilen\nsich und sehnen\vsich nach einem\vKampf!",
  ["_SSAnne1FWaiterText"] = "Moin, moin, Du\nLandradde! Ich\vbin der Steward\vauf diesem Kahn!\fRuf mich einfach,\nwenn Du einen\vWunsch hast!\fVerdammich,\ngesprächig bist\vDu aber nicht!",
  ["_SSAnne2FRivalCutMasterText"] = "{RIVAL}: Es soll\nangeblich ein\vgroßer Meister im\vUmgang mit dem\vZERSCHNEIDER an\vBord sein.\fAber da war nur\nein seekranker\valter Mann!\fDer ZERSCHNEIDER\nist äußerst\vnützlich!\fDu solltest den\nalten Mann mal\vbesuchen! Ciao!",
  ["_SSAnne2FRivalDefeatedText"] = "Mist!\fNaja, wenigstens\ntrainierst Du\vDeine POKéMON!",
  ["_SSAnne2FRivalText"] = "{RIVAL}: Sieh an!\n{PLAYER}!\fIch wußte, ich\nwürde Dich hier\vtreffen!\f{PLAYER}, hat man\nDich tatsächlich\veingeladen?\fWie kommst Du\nmit Deinem\vPOKéDEX voran?\fIch habe bereits\n40 verschiedene\vPOKéMON gefangen!\fEs gibt eine\nriesige Vielfalt\van POKéMON!\fVersuch Dein\nGlück in hohem\vGras!",
  ["_SSAnne2FRivalVictoryText"] = "{PLAYER}! Bist Du\netwa seekrank?\fDu solltest Dich\nin Form bringen, \vKumpel!",
  ["_SSAnne2FRoomsBeautyText"] = "Viele Leute werden\nleicht seekrank!",
  ["_SSAnne2FRoomsBrunetteGirlText"] = "Der KAPITÄN war\nkreidebleich! Er\vsah schlecht aus!",
  ["_SSAnne2FRoomsCooltrainerFAfterBattleText"] = "Ich bewundere die\nStärke Deiner\vPOKéMON!",
  ["_SSAnne2FRoomsCooltrainerFBattleText"] = "Wo warst Du, als\ndie Party lief?",
  ["_SSAnne2FRoomsCooltrainerFEndBattleText"] = "Mach mal\nlangsam!!!",
  ["_SSAnne2FRoomsFisherAfterBattleText"] = "Eine Party?\fDie dürfte längst\nvorbei sein. Du\vbist spät dran!",
  ["_SSAnne2FRoomsFisherBattleText"] = "Schau Dir an, was\nich an Land\vgezogen habe!",
  ["_SSAnne2FRoomsFisherEndBattleText"] = "OK!\nDas war's für\vmich! Tschüß!!!",
  ["_SSAnne2FRoomsGentleman1AfterBattleText"] = "Vor 15 Jahren\nhätte ich mit\vlinks gewonnen...",
  ["_SSAnne2FRoomsGentleman1BattleText"] = "Im Wettstreit mit\nder Jugend bleib\vich jung!",
  ["_SSAnne2FRoomsGentleman1EndBattleText"] = "Ahhh!\nDa fühlt man sich\vgleich jünger!",
  ["_SSAnne2FRoomsGentleman2AfterBattleText"] = "Ich mag POKéMON,\ndie stark und\vselten sind!",
  ["_SSAnne2FRoomsGentleman2BattleText"] = "Was magst Du\nlieber? Starke\voder seltene\vPOKéMON?",
  ["_SSAnne2FRoomsGentleman2EndBattleText"] = "Ich\nziehe meinen\vHut vor Dir!",
  ["_SSAnne2FRoomsGentleman3Text"] = "Auf all meinen\nReisen habe ich\vnie ein solch\vverschlafenes\vPOKéMON gesehen!\fEs sieht ungefähr\nso aus...",
  ["_SSAnne2FRoomsGentleman4Text"] = "Ich habe schon\nLeute auf POKéMON\vübers Wasser\vsurfen sehen!",
  ["_SSAnne2FRoomsGentleman5Text"] = "Hast Du die\nSAFARI-ZONE in\vFUCHSANIA CITY\vschon besucht?\fEs gibt dort sehr\nseltene POKéMON!",
  ["_SSAnne2FRoomsGrampsText"] = "POKéMON können\nBüsche mit dem\vZERSCHNEIDER\vkleinhacken.",
  ["_SSAnne2FRoomsLittleBoyText"] = "Mein Vater war\nmit mir in der\vSAFARI-ZONE! Es\vwar aufregend!",
  ["_SSAnne2FWaiterText"] = "Dieses luxuriöse\nTraumschiff fährt\vexklusiv für\vTrainer zur See!\fIn jedem Hafen\nbesuchen uns\vausschließlich\vgeladene Trainer!",
  ["_SSAnne3FSailorText"] = "Der KAPITÄN ist\nein Meister des\vSchwertkampfes!\fEr unterrichtet\nsogar POKéMON im\vUmgang mit dem\vZERSCHNEIDER!",
  ["_SSAnneB1FRoomsFisherAfterBattleText"] = "Ich hätte Dich\nfast mit auf\vmeine Angeltour\vgenommen!",
  ["_SSAnneB1FRoomsFisherBattleText"] = "Warte doch mal!\nLaß uns plaudern!\fIch besitze nur\nWasser-POKéMON!",
  ["_SSAnneB1FRoomsFisherEndBattleText"] = "Mist!\nDas war nichts!",
  ["_SSAnneB1FRoomsMachokeText"] = "MACHOLLO: Macho!\nMachollo!",
  ["_SSAnneB1FRoomsSailor1AfterBattleText"] = "Willst Du Seemann\nwerden, Kleiner?",
  ["_SSAnneB1FRoomsSailor1BattleText"] = "Du weißt, wir\nSeeleute lieben\ves zu kämpfen!",
  ["_SSAnneB1FRoomsSailor1EndBattleText"] = "JA! Was\nfür ein Kampf!!!",
  ["_SSAnneB1FRoomsSailor2AfterBattleText"] = "Hast Du schon den\nPROFI-ANGLER in\vORANIA CITY\vbesucht?",
  ["_SSAnneB1FRoomsSailor2BattleText"] = "Mein Ruf als\nSeebär steht auf\vdem Spiel!!!",
  ["_SSAnneB1FRoomsSailor2EndBattleText"] = "\nKiel unter! Das\vwar's für mich!",
  ["_SSAnneB1FRoomsSailor3AfterBattleText"] = "Seeleute fangen\nihre POKéMON auf\vhoher See!",
  ["_SSAnneB1FRoomsSailor3BattleText"] = "Auch Seeleute\nbesitzen POKéMON!",
  ["_SSAnneB1FRoomsSailor3EndBattleText"] = "\nDas war eine\vreife Leistung!",
  ["_SSAnneB1FRoomsSailor4AfterBattleText"] = "Wasser-POKéMON\nleben unter\vWasser! Du\fbenötigst eine\nANGEL!",
  ["_SSAnneB1FRoomsSailor4BattleText"] = "Ich war früher\ngenau so aufge-\vdreht wie Du!",
  ["_SSAnneB1FRoomsSailor4EndBattleText"] = "Oh nein!\nVerloren!",
  ["_SSAnneB1FRoomsSailor5AfterBattleText"] = "Manchmal treiben\nQuallen an das\vSchiff. Der Koch\vfängt sie dann...",
  ["_SSAnneB1FRoomsSailor5BattleText"] = "Der Verlierer\nwird kielgeholt!\vLos geht's!",
  ["_SSAnneB1FRoomsSailor5EndBattleText"] = "Argh!\nVon einem\vKind besiegt...",
  ["_SSAnneB1FRoomsSuperNerdText"] = "Mein MACHOLLO\nist superstark!!!\fMit seiner STÄRKE\nkann es sogar\vFelsen bewegen!",
  ["_SSAnneBowCooltrainerMText"] = "Brrr, ich fühle\nmich elend...\fAn der frischen\nLuft fühle ich\vmich besser...",
  ["_SSAnneBowSailor1Text"] = "Puh! Ich werde\ndas Deck wohl nie\vsauber bekommen!",
  ["_SSAnneBowSailor2AfterBattleText"] = "Hast Du eine\nAhnung, wie viele\vunterschiedliche\vPOKéMON es gibt?",
  ["_SSAnneBowSailor2BattleText"] = "Hey!\fWie wär's mit\neinem Tänzchen?",
  ["_SSAnneBowSailor2EndBattleText"] = "Ich bin\nbeeindruckt!",
  ["_SSAnneBowSailor3AfterBattleText"] = "Mein Vater sagt,\nes gäbe 100\vverschiedene \vPOKéMON. Ich\vdenke, es gibt\vmehr...",
  ["_SSAnneBowSailor3BattleText"] = "Ahoi, Seemann!\nBist Du seekrank?",
  ["_SSAnneBowSailor3EndBattleText"] = "Du hast\nGlück gehabt!",
  ["_SSAnneBowSuperNerdText"] = "Sperrstunde! Die\nParty ist vorbei!\fDas Schiff sticht\nbald in See!",
  ["_SSAnneCaptainsRoomCaptainHM01NoRoomText"] = "Oh, nein! Du hast\nkeinen Platz für\vweitere Items!",
  ["_SSAnneCaptainsRoomCaptainIFeelMuchBetterText"] = "KAPITÄN: Ahhhhh!\nIch danke Dir!\fEs geht mir schon\nviel besser...\fMöchtest Du den\nUmgang mit dem\vZERSCHNEIDER\vlernen?\fIch könnte es Dir\nbeibringen, aber\vmir ist so übel.\fIch hab's! Nimm\neinfach das hier!\fDamit bringst Du\nDeinen POKéMON\vden Umgang mit\vdem ZERSCHNEIDER\vganz leicht bei!",
  ["_SSAnneCaptainsRoomCaptainNotSickAnymoreText"] = "KAPITÄN: Super!\fEndlich bin ich\nnicht mehr krank!\vEs kann losgehen!",
  ["_SSAnneCaptainsRoomCaptainReceivedHM01Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_SSAnneCaptainsRoomRubCaptainsBackText"] = "KAPITÄN: Urps...\nEs geht mir gar\vnicht gut! Urps!\f{PLAYER} massiert\ndem KAPITÄN den\vRücken!\fRubbel...\nSchrubb...",
  ["_SSAnneCaptainsRoomSeasickBookText"] = "1000 natürliche\nHausmittel gegen\vSeekrankheit...\vDer KAPITÄN liest\vdieses Buch!",
  ["_SSAnneCaptainsRoomTrashText"] = "Buäh! Manche\nDinge macht man\vbesser nicht...",
  ["_SSAnneKitchenCook1Text"] = "Aus dem Weg, Du\nLeichtmatrose!\fWir sind schwer\nbeschäftigt!",
  ["_SSAnneKitchenCook2Text"] = "Ich habe einen\nseltsamen Ball im\vMüll gesehen...",
  ["_SSAnneKitchenCook3Text"] = "Es gibt zuviel zu\ntun, nie kann ich\vmich ausruhen!",
  ["_SSAnneKitchenCook4Text"] = "Was hab ich nur\nverbrochen?\fIch muß immer\nnur Kartoffeln\vschälen...",
  ["_SSAnneKitchenCook5Text"] = "Hast Du schon von\nRELAXO gehört?\fEs schläft und\nfrißt den ganzen\vTag lang!",
  ["_SSAnneKitchenCook6Text"] = "Schnief... \n...Schnief...\fImmer muß ich\ndie Zwiebeln\vschälen...",
  ["_SSAnneKitchenCook7MainCourseIsText"] = "Ich bin der Chef\nde cuisine! \fDer Hauptgang ist",
  ["_SSTicketNoRoomText"] = "Hey Kumpel, Du\nträgst zuviel\vmit Dir herum!",
  ["_SSTicketReceivedText"] = "{PLAYER} erhält\nein {RAM:wStringBuffer}!",
  ["_SafariZoneAngryText"] = "Das wilde\n{RAM:wEnemyMonNick} ist\vwütend!",
  ["_SafariZoneCenterRestHouseGirlText"] = "SARAH: Wo ist\nbloß mein Freund\vERIK hingegangen?",
  ["_SafariZoneCenterRestHouseScientistText"] = "Wenn ich POKéMON\nfange, verschenke\vich sie, wenn ich\vwieder zu Hause\vbin!",
  ["_SafariZoneCenterRestHouseSignText"] = "RASTHAUS",
  ["_SafariZoneCenterTrainerTipsSignText"] = "Drücke START, um\nnachzusehen,\vwieviel Zeit Du\vnoch übrig hast!",
  ["_SafariZoneEastRestHouseRockerText"] = "Ich habe ein\nCHANEIRA\vgefangen!\fDie Mühe hat\nsich gelohnt!",
  ["_SafariZoneEastRestHouseScientistText"] = "Wie viele hast Du\ngefangen? Ich bin\vtotal erschöpft!",
  ["_SafariZoneEastRestHouseSignText"] = "RASTHAUS",
  ["_SafariZoneEastRestHouseSilphWorkerMText"] = "Was für ein Spaß!\nAber jetzt bin\vich hundemüde...",
  ["_SafariZoneEastSignText"] = "ZENTRUM\nNORDEN: AREAL 2",
  ["_SafariZoneEastTrainerTipsText"] = "TIPS FÜR TRAINER\fDie verbleibende\nZeit verstreicht\vnur, wenn Du\vläufst!",
  ["_SafariZoneEatingText"] = "Das wilde\n{RAM:wEnemyMonNick} frißt!",
  ["_SafariZoneGateSafariZoneWorker1CallYouOnThePAText"] = "\fWir rufen Dich\nüber LAUTSPRECHER\vaus, wenn Deine\vFangzeit\vabgelaufen oder\vDein Vorrat an\vSAFARI-BÄLLEN\verschöpft ist!",
  ["_SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText"] = "War die Jagd\nerfolgreich?\vBesuche uns bald\vwieder!",
  ["_SafariZoneGateSafariZoneWorker1GoodLuckText"] = "Viel Glück!",
  ["_SafariZoneGateSafariZoneWorker1LeavingEarlyText"] = "Hast Du keine\nLust mehr?",
  ["_SafariZoneGateSafariZoneWorker1NotEnoughMoneyText"] = "Ups! Du hast\nnicht genug Geld!",
  ["_SafariZoneGateSafariZoneWorker1PleaseComeAgainText"] = "OK! Besuche\nuns bald wieder!",
  ["_SafariZoneGateSafariZoneWorker1ReturnSafariBallsText"] = "Gib bitte die\nrestlichen\vSAFARI-BÄLLE\vzurück.",
  ["_SafariZoneGateSafariZoneWorker1Text"] = "Willkommen in\nder SAFARI-ZONE!",
  ["_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText"] = "Das kostet\n¥500!\fWir verwenden\nhier spezielle\vPOKéBÄLLE.\f{PLAYER} erhält\n30 SAFARI-BÄLLE!",
  ["_SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText"] = "Für nur ¥500\ndarfst Du im Park\vso viele POKéMON\vfangen, wie Du\vmöchtest!\fMöchtest Du auf\ndie Jagd gehen?",
  ["_SafariZoneGateSafariZoneWorker2FirstTimeHereText"] = "Hi! Bist Du zum\nersten Mal hier?",
  ["_SafariZoneGateSafariZoneWorker2SafariZoneExplanationText"] = "Die SAFARI-ZONE\nbesteht aus vier\vAbschnitten.\fIn jedem\nAbschnitt findet\vman verschiedene\vPOKéMON.\vVersuche, sie mit\vSAFARI-BÄLLEN zu\vfangen.\fWenn Du keine\nSAFARI-BÄLLE mehr\vhast oder wenn\vdie Zeit \vabgelaufen ist,\vendet das Spiel!\fBevor Du Dich auf\ndie Jagd begibst,\vsolltest Du Raum\vfür neue POKéMON\vschaffen und eine\vfreie POKéMON-BOX\vanwählen!",
  ["_SafariZoneGateSafariZoneWorker2YoureARegularHereText"] = "Hey, Du bist ein\nStammkunde!",
  ["_SafariZoneLowCostText1"] = "\fOK, dann bezahl\nsoviel wie Du\vkannst.",
  ["_SafariZoneLowCostText2"] = "Allerdings kann\nich Dir dann\vnicht alle\v30 BÄLLE geben.",
  ["_SafariZoneLowCostText3"] = "\fDu bist ganz\nschön hartnäckig!\fOK, dieses Mal\nlasse ich Dich\vumsonst hinein!",
  ["_SafariZoneLowCostText4"] = "",
  ["_SafariZoneLowCostText5"] = "Tut mir leid,\naber Du mußt\vEintritt zahlen!",
  ["_SafariZoneLowCostText6"] = "Du darfst nicht\nhinein, ohne zu\vbezahlen!",
  ["_SafariZoneLowCostText7"] = "Ohne Geld darfst\nDu nicht hinein!",
  ["_SafariZoneLowCostText8"] = "Kein Geld,\nkein Zutritt!\vVerstanden?",
  ["_SafariZoneNorthRestHouseGentlemanText"] = "Mein EVOLI hat\nsich zu FLAMARA\ventwickelt!\fAber bei einem\nFreund hat sich\vEVOLI zu AQUANA\ventwickelt!",
  ["_SafariZoneNorthRestHouseSafariZoneWorkerText"] = "Gehe in die\nSAFARI-ZONE!\fDu kannst dort\neinen Preis\vgewinnen!",
  ["_SafariZoneNorthRestHouseScientistText"] = "Alle Items,\ndie Du findest,\vgehören Dir!\fAber Dir wird die\nZeit davonlaufen,\vwenn Du alle auf\veinmal einsammeln\vmöchtest!",
  ["_SafariZoneNorthRestHouseSignText"] = "RASTHAUS",
  ["_SafariZoneNorthSignText"] = "AREAL 2",
  ["_SafariZoneNorthTrainerTips1Text"] = "TIPS FÜR TRAINER\fBis zum GEHEIMEN\nHAUS ist es nicht\vmehr weit weg!",
  ["_SafariZoneNorthTrainerTips2Text"] = "TIPS FÜR TRAINER\fPOKéMON\nverstecken sich\vin hohem Gras!\fLaufe durch das\nhohe Gras und\vscheuche sie auf!",
  ["_SafariZoneNorthTrainerTips3Text"] = "TIPS FÜR TRAINER\fFinde das\nVERSTECKTE HAUS.\vDann gewinnst Du\veine VM!",
  ["_SafariZoneSecretHouseFishingGuruHM03ExplanationText"] = "VM03 ist SURFER!\fLernt ein POKéMON\ndiese Technik,\vdann kann es Dich\vüber das Wasser\vtransportieren!\fDas BESTE ist\naber, daß Du\vdiese VM benutzen\vkannst, so oft Du\vmöchtest!\fIst das nicht\nirre? Du bist ein\vGlückspilz!",
  ["_SafariZoneSecretHouseFishingGuruHM03NoRoomText"] = "Oh! Du kannst\nkeine weiteren\vItems tragen!",
  ["_SafariZoneSecretHouseFishingGuruReceivedHM03Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_SafariZoneSecretHouseFishingGuruYouHaveWonText"] = "Ah! Endlich!\fDu bist der\nErste, der das\vVERSTECKTE HAUS\vgefunden hat!\fIch dachte schon,\nniemand würde den\vgroßen Preis\vjemals gewinnen!\fGlückwunsch! Du\nhast gewonnen!",
  ["_SafariZoneWestFindWardensTeethSignText"] = "BELOHNUNG!\fWer die GOLDZÄHNE\ndes Parkwächters\vder SAFARI-ZONE\vfindet, erhält\veine Belohnung!\fFinder melden\nsich bitte beim\vParkwächter!",
  ["_SafariZoneWestRestHouseCooltrainerMText"] = "Wenn Du ihnen\nKÖDER zuwirfst,\vsind die POKéMON\vleichter zu\vfangen!",
  ["_SafariZoneWestRestHouseScientistText"] = "Wenn Du STEINE\nauf POKéMON\vwirfst, fliehen\vsie meist. Aber\vsie sind dann\vleichter zu\vfangen!",
  ["_SafariZoneWestRestHouseSignText"] = "RASTHAUS",
  ["_SafariZoneWestRestHouseSilphWorkerFText"] = "Ich habe lange\ngesucht, aber\vkeine neuen\vPOKéMON gefunden.",
  ["_SafariZoneWestSignText"] = "AREAL 3\nOSTEN: ZENTRUM",
  ["_SafariZoneWestTrainerTipsText"] = "TIPS FÜR TRAINER\fErforsche die\nSAFARI-ZONE!\fFinde das\nVERSTECKTE HAUS!",
  ["_SaffronCityFightingDojoSignText"] = "KAMPF-DOJO",
  ["_SaffronCityGentlemanText"] = "Ich flog mit\nmeinem TAUBOSS\vhierher, nachdem\vich von der\vSILPH CO.\vgelesen habe!\fIst schon alles\nvorbei? Na toll, \vdann habe ich\vwohl das Beste\vverpaßt!",
  ["_SaffronCityGymSignText"] = "SAFFRONIA CITY\nPKMN-ARENA\vARENALEITERIN: \vSABRINA\fDie Herrin der\nPSYCHO-POKéMON!",
  ["_SaffronCityMrPsychicsHouseSignText"] = "PSYCHOLOGEN-HAUS",
  ["_SaffronCityPidgeotText"] = "TAUBOSS: Tauboss!",
  ["_SaffronCityPokecenterGuyText1"] = "Ich wünschte, die\nTOP VIER kämen\vund stampften\vTEAM ROCKET\vin den Boden!",
  ["_SaffronCityPokecenterGuyText2"] = "TEAM ROCKET\nist geflohen! Wir\vkönnen wieder aus\vdem Haus gehen!",
  ["_SaffronCityRockerText"] = "Der BOSS des\nTEAM ROCKET ist\vaus dem Gebäude\vder SILPH CO.\vgeflohen!",
  ["_SaffronCityRocket1Text"] = "Was willst Du\nhier? Hau ab!",
  ["_SaffronCityRocket2Text"] = "Der BOSS hat\nversprochen, daß\vwir diese Stadt\veinnehmen werden.",
  ["_SaffronCityRocket3Text"] = "Mach Dich vom\nAcker!",
  ["_SaffronCityRocket4Text"] = "SAFFRONIA CITY\ngehört TEAM\vROCKET!",
  ["_SaffronCityRocket5Text"] = "Ich fühle mich\nwunderbar, wenn\vich böse bin!",
  ["_SaffronCityRocket6Text"] = "Au! Paß auf, wo\nDu läufst!",
  ["_SaffronCityRocket7Text"] = "Wenn wir erst die\nSILPH CO. unter\vKontrolle haben,\vkönnen wir in der\vganzen Welt mit\vPOKéMON handeln!",
  ["_SaffronCityRocket8Text"] = "Ich bin der\nWächter.\fVerdächtige\nKinder lasse ich\vnicht herein!",
  ["_SaffronCityRocket9Text"] = "...\nSchnarch...\fHa! Er hält\nein Nickerchen!",
  ["_SaffronCityScientistText"] = "Du hast TEAM\nROCKET besiegt?\vUnglaublich!!!",
  ["_SaffronCitySignText"] = "SAFFRONIA CITY\nDie goldglänzende\vHandelsstadt!",
  ["_SaffronCitySilphCoLatestProductSignText"] = "Das neueste\nProdukt der\vSILPH CO.!\fVerkaufsstart:\nDemnächst!",
  ["_SaffronCitySilphCoSignText"] = "SILPH CO.\nBÜROGEBÄUDE",
  ["_SaffronCitySilphWorkerFText"] = "Nun kommen auch\nwieder Touristen\vnach SAFFRONIA\vCITY!",
  ["_SaffronCitySilphWorkerMText"] = "Hurra! TEAM\nROCKET ist fort!\vJetzt fühlt man\vsich auf der\vStraße wieder\vsicher!",
  ["_SaffronCityTrainerTips1Text"] = "TIPS FÜR TRAINER\fHYPERHEILER\nkuriert alle\vVerletzungen.\fEr ist teuer,\ndafür aber\vsehr praktisch.",
  ["_SaffronCityTrainerTips2Text"] = "TIPS FÜR TRAINER\fDer SUPERBALL\nerhöht die\vFangquote.\fProbiere ihn bei\nPOKéMON aus, die\vschwer zu fangen\vsind!",
  ["_SaffronGateGuardGeeImThirstyText"] = "Ich schiebe hier\nWache.\vOhhh... Ich bin\vso durstig...\fHalt! Stop!\fDer Durchgang\nist gesperrt!",
  ["_SaffronGateGuardImParchedText"] = "Ich bin dem\nVerdursten\vnahe...\vWas? Das Getränk\vist für mich?\vVielen Dank!",
  ["_SaffronGateGuardThanksForTheDrinkText"] = "Hallo! Danke für\ndie Erfrischung!",
  ["_SaffronGateGuardYouCanGoOnThroughText"] = "\fGluck, gluck!\nRülps...\vEntschuldigung!\vWenn Du nach\vSAFFRONIA CITY\vmöchtest, darfst\vDu passieren!\vIch werde den\vanderen Wachen\vetwas abgeben!",
  ["_SaffronGymChanneler1AfterBattleText"] = "Sind zwei Gegner\ngleich stark, so\vwird der\ventschlossenere\vKämpfer gewinnen!\fWenn Du SABRINA\nschlagen willst,\vkonzentriere Dich\vauf den Sieg!",
  ["_SaffronGymChanneler1BattleText"] = "SABRINA ist\njünger als ich.\vTrotzdem habe ich\vRespekt vor ihr!",
  ["_SaffronGymChanneler1EndBattleText"] = "\nIch bin nicht\vgut genug!",
  ["_SaffronGymChanneler2AfterBattleText"] = "Meine POKéMON\nmüssen stärkere\vAttacken lernen!",
  ["_SaffronGymChanneler2BattleText"] = "POKéMON\npassen sich ihrem\vTrainer an.\fDeine POKéMON\nmüssen demnach\vsehr zäh sein!",
  ["_SaffronGymChanneler2EndBattleText"] = "Ich\nwußte es!",
  ["_SaffronGymChanneler3AfterBattleText"] = "Ich ahnte, daß es\npassieren würde!",
  ["_SaffronGymChanneler3BattleText"] = "Du gegen mich!\nUnsere POKéMON\vsollen kämpfen!",
  ["_SaffronGymChanneler3EndBattleText"] = "\nIch habe nun\vdoch verloren!",
  ["_SaffronGymGuideBeatSabrinaText"] = "PSYCHOKINESE?\fWenn ich sie\nhätte, würde ich\vin der Spielhalle\vreich werden!",
  ["_SaffronGymGuideChampInMakingText"] = "Hey! Warte, Du\nChampion in spe!\fDie POKéMON von\nSABRINA benutzen\vPSYCHOKINESE\vanstelle von\vphysischen\vKräften!\fKAMPF-POKéMON\nsind PSYCHOKINESE\vnicht gewachsen!\fSie haben nicht\neinmal den Hauch\veiner Chance!",
  ["_SaffronGymSabrinaMarshBadgeInfoText"] = "Der SUMPFORDEN\nläßt POKéMON bis\vLevel 70 Deinen\vBefehlen folgen!\fStärkere POKéMON\nkönnten sich Dir\vwidersetzen und\vDeine Befehle\vignorieren!\fAchte darauf, daß\nDu Deine POKéMON\vjederzeit unter\vKontrolle hast!\fWarte! Nimm noch\ndiese TM von mir!",
  ["_SaffronGymSabrinaPostBattleAdviceText"] = "Theoretisch\nkönnte jeder die\vPSYCHOKINESE\verlernen. Viele\vwissen es nur\vnicht!",
  ["_SaffronGymSabrinaReceivedMarshBadgeText"] = "Ich bin\nerschüttert!\vAber verloren ist\vverloren.\fIch muß gestehen,\nich habe mich\vnicht allzusehr\vangestrengt!\fIch schenke Dir\nden SUMPFORDEN!",
  ["_SaffronGymSabrinaReceivedTM46Text"] = "{PLAYER} erhält\nTM46!",
  ["_SaffronGymSabrinaTM46NoRoomText"] = "Dein Rucksack\nist zu voll!",
  ["_SaffronGymSabrinaText"] = "Eine Vision hat\nmir Deine Ankunft\vvorausgesagt!\fIch beherrsche\ndie PSYCHOKINESE,\vseit ich ein Kind \vgewesen bin.\fZunächst habe ich\ngelernt, mit\vPSYCHOKINESE\vLöffel\vzu verbiegen.\fIch verabscheue\nden Kampf!\vAber wenn Du es\vwünschst, beweise\vich Dir meine\vKräfte!",
  ["_SaffronGymYoungster1AfterBattleText"] = "PSYCHO-POKéMON\nfürchten sich nur\vvor Käfern!",
  ["_SaffronGymYoungster1BattleText"] = "Machen Dir unsere\nPSYKRÄFTE Angst?",
  ["_SaffronGymYoungster1EndBattleText"] = "Ich\nglaube es nicht:\vIch hab verloren!",
  ["_SaffronGymYoungster2AfterBattleText"] = "SABRINA hat den\nKARATE-MEISTER in\vder ARENA nebenan\vbesiegt!",
  ["_SaffronGymYoungster2BattleText"] = "Du weißt, daß man\nmit Stärke allein\vnicht weit kommt,\voder?",
  ["_SaffronGymYoungster2EndBattleText"] = "Das \nist unfassbar!",
  ["_SaffronGymYoungster3AfterBattleText"] = "In SAFFRONIA CITY\ngab es zwei\vPKMN-ARENEN.\fAllerdings hat\nder KAMPF-DOJO\vden Status als\vPKMN-ARENA\vverloren, weil\vwir die Trainer\vbesiegt haben!",
  ["_SaffronGymYoungster3BattleText"] = "Obwohl SABRINA\nnoch jung ist,\vist sie unsere\vARENALEITERIN!\fWir lassen Dich\nnicht einfach so\vzu ihr gehen!",
  ["_SaffronGymYoungster3EndBattleText"] = "Ich habe\ndie Konzentration\vverloren!",
  ["_SaffronGymYoungster4AfterBattleText"] = "Ich habe Deine\nGedanken gelesen!",
  ["_SaffronGymYoungster4BattleText"] = "Die POKéMON in\nder ARENA von\vSAFFRONIA CITY\vsind für ihre\vübernatürlichen\vKräfte bekannt!\fIch weiß, daß Du\nSABRINA heraus-\vfordern möchtest!",
  ["_SaffronGymYoungster4EndBattleText"] = "Arrrgh!",
  ["_SaffronMartCooltrainerFText"] = "BELEBER ist zwar\nteuer, aber\vbesiegte POKéMON\vwerden damit\vwieder fit!",
  ["_SaffronMartSuperNerdText"] = "TOP-SCHUTZ hält\nschwache POKéMON\vlänger von Dir\vfern als\vSUPERSCHUTZ!",
  ["_SaffronPidgeyHouseBrunetteGirlText"] = "...vielen Dank\nfür Deinen Brief!\vBis bald...\fHey! Lies meinen\nBrief nicht!",
  ["_SaffronPidgeyHousePaperText"] = "Ich habe ein\nAP-PLUS geschenkt\vbekommen!\fEs erhöht die\nANGRIFFSPUNKTE\veiner Attacke!",
  ["_SaffronPidgeyHousePidgeyText"] = "TAUBSI: Taubsi!",
  ["_SaffronPidgeyHouseYoungsterText"] = "Ich mag die\nNACHAHMERIN!\vIch kaufe ihr\veine POKéPUPPE!",
  ["_SaffronPokecenterBeautyText"] = "Der Zeitpunkt\nder Entwicklung\vist von POKéMON\vzu POKéMON\vunterschiedlich.",
  ["_SaffronPokecenterGentlemanText"] = "Die SILPH CO. ist\nsehr bekannt.\vDeshalb wurde\vTEAM ROCKET auf\vsie aufmerksam!",
  ["_SandshrewDexEntry"] = "Der Körper dieses\nPOKéMON ist sehr\ntrocken.\fIn kalten Nächten\nwird sein Körper\nvon Tau überzogen.",
  ["_SandslashDexEntry"] = "Dieses POKéMON\ngreift Gegner mit\nseinen scharfen\fKlauen an. Bricht\neine Klaue ab, so\nwächst sie nach.",
  ["_SaveOptionText"] = "Im MENÜ kannst Du\nunter SICHERN\vDeinen Spielstand\vabspeichern.",
  ["_SavingEnergyText"] = "{USER}\nsammelt Kräfte!",
  ["_SavingText"] = "Speichern...",
  ["_ScaredText"] = "{RAM:wBattleMonNick} kann\nsich vor Angst\vnicht bewegen!",
  ["_ScytherDexEntry"] = "SICHLOR lebt im\ndichten Unterholz.\nFlink wie ein\fNinja greift es\nmit seinen sichel-\nförmigen Armen an.",
  ["_SeadraDexEntry"] = "Die Rückenflossen\ndieses POKéMON\nsondern Gift ab.\fIm Schlaf klammert\nsich SEEMON an\nKorallen fest.",
  ["_SeafoamIslandsB4FArticunoBattleText"] = "Arktos!",
  ["_SeafoamIslandsB4FBouldersSignText"] = "Felsen könnten\ndie Strömung\vvielleicht\vumlenken!",
  ["_SeafoamIslandsB4FDangerSignText"] = "VORSICHT!\nGEFÄHRLICHE\vSTRÖMUNG!",
  ["_SeakingDexEntry"] = "Dieses POKéMON\nschafft sich einen\nUnterschlupf,\findem es mit\nseinem Horn Steine\naushöhlt.",
  ["_SeelDexEntry"] = "Dieses POKéMON\nbevorzugt eiskalte\nLebensräume und\fschwimmt mit Vor-\nliebe in -10 Grad\nkaltem Wasser.",
  ["_SentToBoxText"] = "Es ist nicht\ngenug Platz für\vdas POKéMON!\v{RAM:wBoxMonNicks} wurde\vmittels PC in\vPOKéMON-BOX {RAM:wStringBuffer}\vtransferiert!",
  ["_ShallWeHealYourPokemonText"] = "Sollen wir Deine\nPOKéMON heilen?",
  ["_ShellderDexEntry"] = "Die Schale dieses\nPOKéMON hält allen\nAttacken stand.\fWenn sie geöffnet\nist, wird MUSCHAS\nverwundbar.",
  ["_ShroudedInMistText"] = "{USER}\nist eingenebelt!",
  ["_SilphCo10FGiovanniILostAgainText"] = "Arrgh!\nWieder verloren!",
  ["_SilphCo10FRocketAfterBattleText"] = "Netter Versuch!\nDer Sitzungssaal\vbefindet sich\vaber noch ein\vStockwerk höher!",
  ["_SilphCo10FRocketBattleText"] = "Willkommen im\n9. Stock! Es ist\vnett, daß Du mal\vvorbeischaust!",
  ["_SilphCo10FRocketEndBattleText"] = "Ich\nbin geschockt!",
  ["_SilphCo10FScientistAfterBattleText"] = "Freut es Dich,\nmich besiegt zu\vhaben? Mann, hau\vendlich ab!",
  ["_SilphCo10FScientistBattleText"] = "Genug von Deinen\ndummen Spielchen!",
  ["_SilphCo10FScientistEndBattleText"] = "Meine\nReserven sind\verschöpft!",
  ["_SilphCo10FSilphWorkerFImScaredText"] = "Hilfe!\nIch habe Angst!",
  ["_SilphCo10FSilphWorkerFQuietAboutMyCryingText"] = "Verrate bitte\nniemandem, daß\vich geweint habe!",
  ["_SilphCo11FBeautyText"] = "SEKRETÄRIN: Wir\ndanken Dir für\vDeinen Heldenmut!\fDu hast uns alle\ngerettet! Danke!",
  ["_SilphCo11FGiovanniText"] = "Ah, {PLAYER}!\nSo trifft man\vsich wieder!\fIch führe gerade\näußerst wichtige\vVerhandlungen mit\vdem PRÄSIDENTEN.\fHalte Dich ein\nfür allemal aus\vden Geschäften\vErwachsener\vheraus!\fOder Du lernst\neine Welt voller\vSchmerzen kennen!",
  ["_SilphCo11FGiovanniYouRuinedOurPlansText"] = "Verdammter Mist!\nDu hast unsere\vÜbernahme der\vSILPH CO. \vvereitelt!\fAber TEAM ROCKET\nwird niemals\vaufgeben!\f{PLAYER}! Vergiß\nnicht, daß alle\vPOKéMON nur zum\vNutzen des TEAM\vROCKET da sind!\fIch muß gehen,\naber meine Zeit\vwird kommen!",
  ["_SilphCo11FRocket2AfterBattleText"] = "Die POKéMON von\nunserem BOSS\vwerden Dich\vfertig machen! ",
  ["_SilphCo11FRocket2BattleText"] = "Stop! Hast Du\neinen Termin\vbeim BOSS?",
  ["_SilphCo11FRocket2EndBattleText"] = "OK!\nDu darfst durch!",
  ["_SilphCo11FSilphPresidentMasterBallDescriptionText"] = "PRÄSIDENT: Man\nkann ihn nirgends\vkaufen!\fEs ist der\nstreng geheime\vPrototyp des\vMEISTERBALLS!\fDu kannst mit ihm\nJEDES POKéMON\vBEIM 1. VERSUCH\vEINFANGEN!\fWäge jedoch\nsorgfältig ab,\vwann Du ihn\veinsetzt!",
  ["_SilphCo11FSilphPresidentNoRoomText"] = "Du hast keinen\nPlatz mehr!",
  ["_SilphCo11FSilphPresidentReceivedMasterBallText"] = "{PLAYER} erhält\neinen {RAM:wStringBuffer}!",
  ["_SilphCo11FSilphPresidentText"] = "PRÄSIDENT: Ich\ndanke Dir für\vdie Rettung der\vSILPH CO.\fIch werde niemals\nvergessen, wie Du\vuns trotz größter\vGefahren tapfer\vgerettet hast!\fWie kann ich Dir\nbloß meinen Dank\vaussprechen?\fIch bin reich,\nich könnte Dir\valles geben!\fAber vielleicht\nist das hier eher\vetwas für Dich!",
  ["_SilphCo1FLinkReceptionistText"] = "Willkommen!\fDer PRÄSIDENT\nbefindet sich\vim 10. Stock im\vKonferenzraum!",
  ["_SilphCo2FRocket1AfterBattleText"] = "Die\ndiamantförmigen\vFelder sind\vTeleporter!\fEine Art Hi-Tech-\nTransportsystem!",
  ["_SilphCo2FRocket1BattleText"] = "Hey, Du hast hier\nnichts verloren!",
  ["_SilphCo2FRocket1EndBattleText"] = "\nDas ist hart!\vVerloren!",
  ["_SilphCo2FRocket2AfterBattleText"] = "Die SILPH CO. und\nTEAM ROCKET\vwerden demnächst\vfusionieren!",
  ["_SilphCo2FRocket2BattleText"] = "Hey Kleiner! Was\nmachst Du hier?",
  ["_SilphCo2FRocket2EndBattleText"] = "Ich\nbin ein Versager!",
  ["_SilphCo2FScientist1AfterBattleText"] = "Ich bin ein Spion\nund infiltriere\vdie SILPH CO.!",
  ["_SilphCo2FScientist1BattleText"] = "Hilfe! Ich bin\nein Mitarbeiter\vder SILPH CO.!",
  ["_SilphCo2FScientist1EndBattleText"] = "Woher\nwußtest Du, daß\vich zum TEAM\vROCKET gehöre?",
  ["_SilphCo2FScientist2AfterBattleText"] = "Aber findest Du\nauch durch dieses\vLabyrinth?",
  ["_SilphCo2FScientist2BattleText"] = "Hau ab! Du hast\nkeinen Zutritt!",
  ["_SilphCo2FScientist2EndBattleText"] = "\nNicht schlecht,\vHerr Specht!",
  ["_SilphCo2FSilphWorkerFReceivedTM36Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_SilphCo2FSilphWorkerFTM36ExplanationText"] = "TM36 ist die\nFINALE-ATTACKE!\fEine verheerende\nAttacke! Aber das\vPOKéMON, das\vsie ausführt,\vscheidet aus!!!",
  ["_SilphCo2FSilphWorkerFTM36NoRoomText"] = "Du kannst nicht\nmehr tragen!!!",
  ["_SilphCo3FRocketAfterBattleText"] = "Ein Tip? Du\nbrauchst einen\vTÜRÖFFNER!",
  ["_SilphCo3FRocketBattleText"] = "Hör endlich auf,\nuns zu nerven!",
  ["_SilphCo3FRocketEndBattleText"] = "\nIch gebe auf!",
  ["_SilphCo3FScientistAfterBattleText"] = "Mist...\fTEAM ROCKET hätte\nmich für meine\vHilfe die POKéMON\vstudieren lassen!",
  ["_SilphCo3FScientistBattleText"] = "Ich arbeite für\nTEAM ROCKET, die\vSILPH CO. zahlt\vmir zu wenig!!!",
  ["_SilphCo3FScientistEndBattleText"] = "Du hast\nmich erwischt!",
  ["_SilphCo3FSilphWorkerMWhatShouldIDoText"] = "Ich arbeite für\ndie SILPH CO.!\vWas soll ich bloß\vmachen?",
  ["_SilphCo3FSilphWorkerMYouSavedUsText"] = "{PLAYER}! Du hast\nuns mit Hilfe\vDeiner POKéMON\vgerettet!",
  ["_SilphCo4FRocket1AfterBattleText"] = "Auf diesen Moment\nhat der Boss sehr\vlange gewartet!",
  ["_SilphCo4FRocket1BattleText"] = "TEAM ROCKET\nhat die Kontrolle\vüber SILPH CO. \vübernommen!!!",
  ["_SilphCo4FRocket1EndBattleText"] = "\nArrgh!",
  ["_SilphCo4FRocket2AfterBattleText"] = "Ich muß den BOSS\nim 10. Stock\vwarnen!",
  ["_SilphCo4FRocket2BattleText"] = "Eindringling\ngesichtet!",
  ["_SilphCo4FRocket2EndBattleText"] = "Wer\noder was bist Du?",
  ["_SilphCo4FScientistAfterBattleText"] = "Die Türen sind\nelektronisch\vverriegelt! Ohne\vTÜRÖFFNER kommt\vman nicht durch!",
  ["_SilphCo4FScientistBattleText"] = "Mein POKéMON\nerwartet Dich!!!",
  ["_SilphCo4FScientistEndBattleText"] = "Du\nschwächliches\vPOKéMON! Mist!",
  ["_SilphCo4FSilphWorkerMImHidingText"] = "Pst! Siehst Du\nnicht, daß ich\vmich verstecke?",
  ["_SilphCo4FSilphWorkerMTeamRocketIsGoneText"] = "TEAM ROCKET ist\nverschwunden?",
  ["_SilphCo5FPokemonReport1Text"] = "Ein ARTIKEL über\nPOKéMON!\fPORYGON!\nPKMN-LABOR ZEUGT\vVIRTUELLES\vPOKéMON!",
  ["_SilphCo5FPokemonReport2Text"] = "Eine Studie über\nPOKéMON!\fEs gibt mehr als\n160 POKéMON-\vKampftechniken!",
  ["_SilphCo5FPokemonReport3Text"] = "Ein Report über \nPOKéMON!\fVier POKéMON\nentwickeln sich\vnur beim Tausch\vüber Link-Kabel\vweiter!",
  ["_SilphCo5FRockerAfterBattleText"] = "Es ist ein weiter\nWeg zum BOSS! Du\vbist hier erst im\v4.Stock!",
  ["_SilphCo5FRockerBattleText"] = "Waaas? Wer hat\ndenn das Kind\vreingelassen?",
  ["_SilphCo5FRockerEndBattleText"] = "Nein!\nDas Kind hat\vmich besiegt!",
  ["_SilphCo5FRocket1AfterBattleText"] = "Es war sehr dumm,\nsich mit TEAM\vROCKET anzulegen!",
  ["_SilphCo5FRocket1BattleText"] = "Ich hörte, ein\nKind läuft im\vGebäude herum...",
  ["_SilphCo5FRocket1EndBattleText"] = "\nSchluß! Aus!",
  ["_SilphCo5FRocket2AfterBattleText"] = "Da fällt mir ein,\nSMOGON entwickelt\vsich zu SMOGMOG!",
  ["_SilphCo5FRocket2BattleText"] = "Zolle TEAM ROCKET\ngefälligst etwas\vmehr Respekt!!!",
  ["_SilphCo5FRocket2EndBattleText"] = "\nHust... Hust...",
  ["_SilphCo5FScientistAfterBattleText"] = "Unsere neueste\nEntwicklung ist\vein BALL, der\valles fängt!",
  ["_SilphCo5FScientistBattleText"] = "Wir entwickeln in\ndiesen Labors\vneue POKébälle!",
  ["_SilphCo5FScientistEndBattleText"] = "Finito!\nDas war's!",
  ["_SilphCo5FSilphWorkerMThatsYouRightText"] = "Ein Eindringling\nmischt TEAM\vROCKET auf... Das\vbist Du, oder?",
  ["_SilphCo5FSilphWorkerMYoureOurHeroText"] = "TEAM ROCKET\nist geflüchtet!\vDu bist ein Held!",
  ["_SilphCo6FRocket1AfterBattleText"] = "Egal! Meine\nBrüder werden\vmich rächen!",
  ["_SilphCo6FRocket1BattleText"] = "Ich bin einer der\nvier berüchtigten\vROCKET-BRÜDER!",
  ["_SilphCo6FRocket1EndBattleText"] = "Nein!\nIch bin raus!",
  ["_SilphCo6FRocket2AfterBattleText"] = "Wenn Du ehrlich\nund rechtschaffen\vbist, bekämpfst\vDu das Böse!",
  ["_SilphCo6FRocket2BattleText"] = "Du wagst es,\nDich TEAM ROCKET\vzu widersetzen?",
  ["_SilphCo6FRocket2EndBattleText"] = "Du\nelender Verräter!",
  ["_SilphCo6FScientistAfterBattleText"] = "TIKSI? Das\nliegt tief im\vNiemandsland!",
  ["_SilphCo6FScientistBattleText"] = "Dieser verdammte\nPRÄSIDENT!\fWarum will er\nausgerechnet\vmich nach TIKSI\vschicken?",
  ["_SilphCo6FScientistEndBattleText"] = "Mist!",
  ["_SilphCo6FSilphWorkerF1HaveToMarryHimText"] = "Ich glaube, ich\nwerde ihn aus\vMitleid heiraten!",
  ["_SilphCo6FSilphWorkerF1SuchACowardText"] = "Schau ihn Dir an,\nden Feigling!",
  ["_SilphCo6FSilphWorkerF2TeamRocketConquerWorldText"] = "TEAM ROCKET\nbenutzt die\vPOKéMON bei dem\vVersuch, die Welt\vzu erobern!",
  ["_SilphCo6FSilphWorkerF2TeamRocketRanText"] = "Du hast TEAM\nROCKET besiegt!",
  ["_SilphCo6FSilphWorkerM1BackToWorkText"] = "OK, die Arbeit\nruft! Los geht's!",
  ["_SilphCo6FSilphWorkerM1TookOverTheBuildingText"] = "TEAM ROCKET\nhat die Kontrolle\vüber das Gebäude\vübernommen!",
  ["_SilphCo6FSilphWorkerM3TargetedSilphText"] = "Sie müssen es\nwegen unserer\vPOKéMON-Produkte\vauf die SILPH CO.\vabgesehen haben!",
  ["_SilphCo6FSilphWorkerM3WorkForSilphText"] = "Wir würden uns\nsehr freuen, wenn\vDu später einmal\vfür die SILPH CO.\varbeiten würdest!",
  ["_SilphCo6FSilphWorkerMHelpMePleaseText"] = "Oje, ojemine!\nBitte hilf mir!",
  ["_SilphCo6FSilphWorkerMWeGotEngagedText"] = "Wir sind\nverlobt!",
  ["_SilphCo7FRivalDefeatedText"] = "Mann!\nDu bist so\vgut, daß Du gegen\vden ROCKET BOSS\vantreten kannst!",
  ["_SilphCo7FRivalGoodLuckToYouText"] = "Also, {PLAYER}!\fIch ziehe dann\nmal weiter!\fWenn ich in den\nPOKéDEX sehe,\verkenne ich, wie\vstark die POKéMON\vsind und wie sie\vsich entwickeln!\fIch werde zur\nPKMN-Liga gehen.\fDann werde ich\ndie TOP VIER\vausstechen!\fBald bin ich der\nmächtigste\vTrainer der Welt!\fViel Glück,\n{PLAYER}! Und\vtrainiere schön\vweiter! Ciao!",
  ["_SilphCo7FRivalText"] = "{RIVAL}: Was hat\nDich aufgehalten,\v{PLAYER}?",
  ["_SilphCo7FRivalVictoryText"] = "{RIVAL}: Was soll\nich dazu sagen?\fWeicheier sind\nhier fehl am\vPlatz! Geh lieber\vtrainieren!",
  ["_SilphCo7FRivalWaitedHereText"] = "{RIVAL}: Hahaha!\nIch wußte, Du\vwürdest hier\vvorbeikommen!\fIch schätze, \nTEAM ROCKET hat\vDir ganz schön\vzugesetzt!\fIch hab Dich in\nSAFFRONIA CITY\vgesehen und mich\vgefragt, ob Du\vseitdem besser \vgeworden bist!",
  ["_SilphCo7FRocket1AfterBattleText"] = "Wenn Du nur so\ndurch die Gegend\vläufst, findest\vDu den BOSS nie!",
  ["_SilphCo7FRocket1BattleText"] = "Du bist\nganz schön mutig!",
  ["_SilphCo7FRocket1EndBattleText"] = "\nLicht aus!",
  ["_SilphCo7FRocket2AfterBattleText"] = "Warte nur, meine\nBrüder werden\vmich rächen!!!",
  ["_SilphCo7FRocket2BattleText"] = "Ich bin einer der\nvier berüchtigten\vROCKET-BRÜDER!",
  ["_SilphCo7FRocket2EndBattleText"] = "Tut\nmir leid, Brüder!",
  ["_SilphCo7FRocket3AfterBattleText"] = "Geh nach Hause,\nbevor mein BOSS\vDich in den Boden\vstampft!",
  ["_SilphCo7FRocket3BattleText"] = "Ein Kind im\nGebäude? Das\vmußt Du sein!",
  ["_SilphCo7FRocket3EndBattleText"] = "\nNa toll!\vIch hab verloren!",
  ["_SilphCo7FScientistAfterBattleText"] = "Kaum trocken\nhinter den Ohren,\vaber schon ein\vbegabter Trainer!",
  ["_SilphCo7FScientistBattleText"] = "Haha!\fDu dachtest wohl,\nich arbeite für\vdie SILPH CO.?",
  ["_SilphCo7FScientistEndBattleText"] = "\nFeierabend! Ich\vgeh nach Hause!",
  ["_SilphCo7FSilphWorkerM1HaveThisPokemonText"] = "Oh! Du bist kein\nROCKET! Kommst\vDu, um uns zu\vretten? Klasse!\fVielen Dank! Nimm\ndieses POKéMON\vals Dankeschön.",
  ["_SilphCo7FSilphWorkerM1IsOurPresidentOkText"] = "TEAM ROCKETS\nBOSS ging in den\vSitzungsaal! Ob\vunser PRÄSIDENT\vwohlauf ist?",
  ["_SilphCo7FSilphWorkerM1LaprasDescriptionText"] = "Es heißt LAPRAS\nund ist sehr\vintelligent.\fEs hat bisher bei\nuns im Labor\vgelebt. Aber bei\vDir ist es besser\vaufgehoben!\fDu wirst LAPRAS\nsicher ein guter\vTrainer sein!\fEs ist ein guter\nSchwimmer und\vkann Dich übers\vWasser tragen!",
  ["_SilphCo7FSilphWorkerM1SavedText"] = "Endlich befreit!\nIch danke Dir!",
  ["_SilphCo7FSilphWorkerM2AfterTheMasterBallText"] = "TEAM ROCKET\nist hinter dem\vMEISTERBALL her,\vmit dem man jedes\vPOKéMON \vfangen kann!",
  ["_SilphCo7FSilphWorkerM2CancelledMasterBallText"] = "Wir haben das\nProjekt gestoppt.\vDer MEISTERBALL\vin TEAM ROCKETS\vHänden? Niemals!",
  ["_SilphCo7FSilphWorkerM3ItWouldBeBadText"] = "Es wäre fatal,\nwenn TEAM ROCKET\vdie SILPH CO.\voder unsere\vPOKéMON\vübernehmen würde!",
  ["_SilphCo7FSilphWorkerM3YouChasedOffTeamRocketText"] = "Wow! Du bist\nganz allein mit\vTEAM ROCKET\vfertig geworden?",
  ["_SilphCo7FSilphWorkerM4ItsReallyDangerousHereText"] = "Hier ist es sehr\ngefährlich! Du\vwirst mich nicht\vretten können!",
  ["_SilphCo7FSilphWorkerM4SafeAtLastText"] = "Endlich gerettet!\nIch danke Dir!",
  ["_SilphCo8FRocket1AfterBattleText"] = "Hau lieber ab,\nsonst rufe ich\vVerstärkung!",
  ["_SilphCo8FRocket1BattleText"] = "Endstation! Bis\nhierher und nicht\vweiter!",
  ["_SilphCo8FRocket1EndBattleText"] = "Mist, \nder Mut hat mich\vverlassen!",
  ["_SilphCo8FRocket2AfterBattleText"] = "Dann werden sich\nmeine Brüder\vum Dich kümmern!",
  ["_SilphCo8FRocket2BattleText"] = "Ich bin einer der\nvier berüchtigten\vROCKET-BRÜDER!",
  ["_SilphCo8FRocket2EndBattleText"] = "Ups!\nBrüder, ich habe\vversagt!",
